window.EXPL={"세무사2016_53-11-2":{"f":"오염 발생 기업에 대한 과세는 오염 감축기술의 개발을 촉진한다.","w":"오염세를 내는 기업은 감축기술을 개발해 배출량을 줄이면 세금도 줄어든다. 그래서 과세는 기술 개발의 유인이 된다.","c":"상","v":1},"세무사2016_53-31-4":{"f":"외부성 문제 해결에 있어서 효율성만 고려하고 형평성은 고려하지 않는 해결 방안이다.","w":"코즈 정리는 재산권이 설정되면 협상으로 효율적 배분에 이른다는 내용이다. 재산권을 누구에게 주느냐에 따른 분배 문제는 다루지 않는다.","c":"상","v":1},"세무사2017_54-25-4":{"f":"여러 사람이 공동으로 사용하려는 목적으로 구입한 자원은 소유권이 불분명하여 과다하게 사용되고 고갈되기 쉽다.","w":"공유지의 비극은 소유권이 분명하지 않아 누구도 아껴 쓸 유인이 없어 자원이 남용되는 현상이다. 소유권이 한 사람에게 귀착된다는 결론은 나오지 않는다.","c":"상","v":1},"세무사2017_54-31-5":{"f":"환경오염 감축효과가 확실한 것이 장점이다.","w":"배출권거래제는 배출 총량을 미리 정해 놓으므로 오염 감축량이 확실하다. 불확실한 쪽은 감축효과가 아니라 배출권 가격(감축비용)이다.","c":"하","v":1},"세무사2017_54-32-1":{"f":"하천의 재산권을 기업 A에게 부여하든 기업 B에게 부여하든 하천의 오염도는 같을 것이다.","w":"코즈 정리가 성립하면 재산권을 누구에게 주어도 협상 결과 효율적인 오염 수준이 같다. 재산권 귀속은 분배에만 영향을 준다.","c":"상","v":1},"세무사2017_54-33-3":{"f":"금전적 외부성이 존재하면 상대가격구조의 변동을 가져오지만 비효율적인 자원배분의 원인으로 작용하지 않는다.","w":"금전적 외부성은 가격 변화를 통해 시장 안에서 전달되는 효과라서 자원배분의 효율성에는 영향이 없다. 비효율을 낳는 것은 기술적(실질적) 외부성이다.","c":"상","v":1},"세무사2021_58-25-4":{"f":"정부가 재산권을 설정하여 당사자의 한쪽에게 권리를 주면 협상을 통해 효율적 자원배분을 이룰 수 있다.","w":"코즈 정리는 정부가 세금으로 개입하지 않아도 재산권이 분명하고 거래비용이 작으면 당사자 간 자발적 협상으로 효율적 배분에 이른다는 내용이다. 환경세 부과는 피구의 해결책이다.","c":"상","v":1},"세무사2022_59-26-5":{"f":"코즈 정리에 따르면 외부성 관련 거래비용이 작을수록 협상이 용이하다.","w":"거래비용이 클수록 협상으로 얻는 이득이 비용에 못 미쳐 협상이 어렵다. 코즈 정리는 거래비용이 없거나 작을 때 성립한다.","c":"상","v":1},"세무사2022_59-29-2":{"f":"정부는 총배출량을 설정할 때 개별 기업의 한계저감비용에 관한 정보를 필요로 하지 않는다.","w":"배출권거래제에서는 정부가 총량만 정하고, 기업별 한계저감비용은 배출권 거래 과정에서 시장이 균등하게 만든다. 정부가 기업별 비용 정보를 알 필요가 없다는 점이 장점이다.","c":"상","v":1},"세무사2023_60-29-1":{"f":"부정적 외부성이 있는 경우에 정부가 교정세를 부과하면 효율적 자원배분을 이룰 수 있다.","w":"한계피해액만큼의 교정세(피구세)를 부과하면 외부비용이 내부화되어 사회적 한계비용과 사회적 한계편익이 일치하는 효율적 배분이 된다.","c":"상","v":1},"세무사2024_61-30-1":{"f":"목장 주인에게 소를 방목할 수 있는 권리가 주어진다면, 농부는 울타리를 설치하지 않게 된다.","w":"울타리 설치비용이 소로 인한 피해액 500만원보다 커서, 권리가 누구에게 있든 울타리를 설치하지 않는 것이 효율적이다. 목장 주인에게 권리가 있으면 농부는 피해를 감수한다.","c":"상","v":1},"세무사2024_61-30-2":{"f":"농부에게 재산권이 주어진다면, 목장 주인은 울타리를 설치하지 않게 된다.","w":"울타리 설치비용이 피해액보다 커서 효율적인 결과는 울타리 없음이다. 농부에게 권리가 있으면 목장 주인은 설치비용 대신 피해를 보상하는 쪽을 택한다.","c":"상","v":1},"세무사2024_61-30-3":{"f":"해당 권리가 누구에게 주어지든 울타리가 설치되지 않는다.","w":"코즈 정리에 따라 권리 귀속과 무관하게 효율적 결과가 같고, 이 사례에서는 설치비용이 피해액보다 커서 울타리는 설치되지 않는다.","c":"상","v":1},"세무사2024_61-30-5":{"f":"농부에게 재산권이 주어진다면, 목장 주인은 농부에게 500만원을 피해보상하고 울타리를 설치하지 않게 된다.","w":"농부에게 권리가 있어도 울타리를 세우는 비용이 보상액 500만원보다 크므로, 목장 주인은 보상만 하고 울타리는 설치하지 않는다.","c":"상","v":1},"세무사2025_62-30-5":{"f":"이로운 외부성이 존재하면 해당재화의 생산량은 사회적 최적 수준보다 과소 생산되는 경향이 있다.","w":"이로운 외부성이 있으면 사회적 한계편익이 사적 한계편익보다 커서 시장 생산량이 최적 수준에 못 미친다. 과다 생산되는 쪽은 해로운 외부성이다.","c":"상","v":1},"세무사2025_62-36-4":{"f":"조세 부과에 비하여 보조금 지급에 따른 생산량 감소의 크기는 단기적으로는 동일하지만 장기적으로는 작다.","w":"오염 감축 보조금은 단기에는 세금과 같은 감산 효과를 내지만, 장기에는 기업 이윤이 늘어 신규 진입이 생기므로 산업 전체의 생산량 감소가 세금보다 작아지거나 오히려 늘 수 있다.","c":"중","v":1},"세무사2026_63-29-5":{"f":"코즈정리는 현실에서 적용하기 어렵다는 한계를 가진다.","w":"현실에서는 거래비용, 당사자 수, 정보 비대칭 때문에 협상이 잘 이루어지지 않아 코즈 정리를 항상 적용할 수는 없다.","c":"상","v":1},"세무사2016_53-25-1":{"f":"위험부담 행위의 소득탄력성이 양이면, 소득효과와 대체효과 모두 위험자산에 대한 투자를 줄인다.","w":"소득탄력성이 양이면 과세로 소득이 줄 때 소득효과가 위험자산 투자를 줄이고, 세후 수익률 하락의 대체효과도 투자를 줄인다. 두 효과가 같은 방향이라 총효과는 감소로 정해진다.","c":"상","v":1},"세무사2016_53-25-2":{"f":"위험부담 행위의 소득탄력성이 음이면, 소득효과는 위험자산에 대한 투자를 늘리고 대체효과는 줄여 총효과는 불확실하다.","w":"소득탄력성이 음이면 소득이 줄 때 위험자산 투자는 오히려 늘어나므로 소득효과는 투자를 늘리고, 대체효과는 투자를 줄인다. 두 효과가 반대 방향이다.","c":"상","v":1},"세무사2016_53-25-4":{"f":"위험부담 행위의 소득탄력성이 음이면, 소득효과는 위험자산에 대한 투자를 늘리고 대체효과는 줄인다.","w":"소득탄력성이 음인 경우 소득 감소는 위험자산 투자를 늘리는 소득효과를 낳는다. 두 효과가 모두 투자를 줄이는 경우는 소득탄력성이 양일 때다.","c":"상","v":1},"세무사2016_53-25-5":{"f":"위험부담 행위의 소득탄력성이 양이면 소득효과와 대체효과가 모두 위험자산에 대한 투자를 줄인다.","w":"소득탄력성의 부호와 관계없이 과세에는 소득효과와 대체효과가 모두 발생한다. 양이면 두 효과가 같은 방향으로 투자를 줄인다.","c":"상","v":1},"세무사2016_53-27-1":{"f":"여가가 정상재일 때, 비례소득세 부과로 인한 대체효과가 소득효과보다 크면 노동공급은 줄어든다.","w":"비례소득세는 순임금을 낮춰 여가가 싸지므로 대체효과는 노동을 줄이고, 소득 감소의 소득효과는 정상재인 여가를 줄여 노동을 늘린다. 대체효과가 더 크면 노동공급은 감소한다.","c":"상","v":1},"세무사2016_53-27-2":{"f":"여가가 정상재일 때, 비례소득세와 동일한 조세수입을 가져다주는 비왜곡적인 정액세를 부과하는 경우 노동공급에 미치는 효과는 다르다.","w":"정액세는 소득효과만 있어 정상재 여가가 줄고 노동공급이 늘어난다. 비례소득세는 대체효과가 더해져 노동공급 효과가 정액세와 같지 않다.","c":"상","v":1},"세무사2016_53-27-3":{"f":"여가가 열등재일 때, 비례소득세 부과로 인한 소득효과와 대체효과 모두 노동공급을 줄이므로 노동공급은 줄어든다.","w":"여가가 열등재이면 소득 감소의 소득효과로 여가가 늘고, 대체효과로도 여가가 늘어 두 효과가 모두 노동을 줄인다. 대체효과와 소득효과의 크기를 비교할 필요 없이 노동공급은 감소한다.","c":"상","v":1},"세무사2016_53-27-4":{"f":"여가가 열등재일 때, 비례소득세와 동일한 조세수입을 가져다주는 비왜곡적인 정액세를 부과하는 경우 노동공급에 미치는 효과는 다르다.","w":"열등재 여가에서는 정액세도 소득효과로 노동공급을 줄이지만, 비례소득세는 대체효과가 더해져 감소폭이 더 크다. 따라서 효과가 동일하지 않다.","c":"상","v":1},"세무사2016_53-35-4":{"f":"자원배분의 효율성이 저하된다.","w":"누진적 증세와 이전지출은 근로·투자 유인을 왜곡하는 대체효과로 초과부담을 낳아 효율성을 떨어뜨리고, 대신 형평성을 높인다.","c":"중","v":1},"세무사2017_54-10-2":{"f":"합산과세방식은 가족 간 수직적 공평성과 수평적 공평성 조건은 충족하나 결혼 중립성 조건은 충족하지 못한다.","w":"부부 소득을 합산하면 소득이 같은 가족에게 같은 세금이 부과되므로 수평적 공평성이 충족된다. 누진세율 아래에서는 결혼으로 세 부담이 달라져 결혼 중립성은 깨진다.","c":"상","v":1},"세무사2017_54-12-1":{"f":"여가가 정상재일 경우 임금변화에 따른 소득효과가 대체효과보다 크다면 후방굴절형 노동공급곡선이 될 것이다.","w":"임금이 오를 때 소득효과가 노동을 줄이는 힘이 대체효과가 노동을 늘리는 힘보다 크면 노동공급곡선이 뒤로 굽는다.","c":"상","v":1},"세무사2017_54-12-3":{"f":"여가가 정상재일 경우 비례소득세를 부과하면 대체효과는 노동공급을 줄이는 방향으로 작용하고 소득효과는 노동공급을 늘리는 방향으로 작용한다.","w":"세금으로 순임금이 내려가면 여가가 상대적으로 싸져 대체효과가 노동을 줄이고, 소득이 줄어든 소득효과는 정상재인 여가를 줄여 노동을 늘린다. 방향이 반대로 서술되어 있다.","c":"상","v":1},"세무사2017_54-12-4":{"f":"여가가 정상재일 경우 누진소득세 부과가 노동공급에 미치는 영향은 비례소득세 부과와 유사하지만 고소득자에게 불리하다.","w":"누진소득세는 소득이 높을수록 한계세율이 높아 순임금이 더 크게 깎이므로 고소득자의 대체효과가 커져 불리하다.","c":"상","v":1},"세무사2017_54-12-5":{"f":"여가가 정상재일 경우 선형누진소득세의 평균세율이 비례소득세와 동일하더라도 노동공급에 미치는 효과는 다르다.","w":"선형누진세는 한계세율이 평균세율보다 높아 대체효과가 더 크게 작용하므로 같은 평균세율의 비례세보다 노동공급을 더 줄인다.","c":"상","v":1},"세무사2017_54-18-1":{"f":"후방굴절 구간에서는 소득효과가 대체효과보다 크다.","w":"임금이 올라도 노동공급이 줄어드는 후방굴절 구간은 소득효과가 대체효과를 앞서는 구간이다.","c":"상","v":1},"세무사2017_54-18-2":{"f":"임금과 노동공급이 정(＋)의 관계인 구간에서는 근로소득세를 증가시키면 노동 공급은 감소한다.","w":"정(＋)의 관계 구간은 대체효과가 소득효과보다 큰 구간이다. 근로소득세로 순임금이 내려가면 노동공급이 줄어든다.","c":"상","v":1},"세무사2017_54-18-4":{"f":"근로소득세 과세는 초과부담을 초래한다.","w":"근로소득세는 순임금을 바꿔 여가와 소비의 상대가격을 왜곡하는 대체효과를 낳으므로 초과부담이 생긴다. 정액세만 초과부담이 없다.","c":"상","v":1},"세무사2017_54-18-5":{"f":"근로소득세 납부 후 임금율은 하락한다.","w":"근로소득세를 내면 세후(순) 임금률은 시장임금률에서 세금만큼 내려간다.","c":"상","v":1},"세무사2021_58-09-3":{"f":"조세를 소득의 함수로 나타내면 원점을 지나는 선형조세함수의 형태가 되지 않는다.","w":"누진세는 소득이 늘수록 평균세율이 올라가므로 조세함수가 원점을 지나는 직선이 될 수 없다. 원점을 지나는 직선은 평균세율이 일정한 비례세다.","c":"상","v":1},"세무사2021_58-14-5":{"f":"자기자본의 귀속이자비용이 공제되지 않으면, 차입금에 대한 이자공제가 허용되고 세법상 감가상각률과 경제적 감가상각률이 일치하더라도 법인세는 투자에 영향을 미친다.","w":"법인세가 투자에 중립적이려면 자기자본의 귀속이자와 차입금 이자를 모두 공제하거나, 자본재를 즉시상각하고 이자공제를 불허해야 한다. 귀속이자를 공제하지 않으면 자기자본 투자의 비용이 높아진다.","c":"상","v":1},"세무사2021_58-16-5":{"f":"대체효과와 소득효과가 동일하여 노동공급이 일정하면 순임금률은 시장임금률보다 낮다.","w":"노동공급곡선이 수직이면 세금은 근로자가 전부 부담한다. 시장임금률은 그대로이고, 순임금률은 세금만큼 낮아진다.","c":"상","v":1},"세무사2021_58-17-1":{"f":"기대수익률이 하락하여 안전성에 대한 기회비용이 감소함으로써, 위험자산의 비중은 작아진다.","w":"위험자산의 기대수익률이 내려가면 안전자산을 택하는 데 포기하는 수익이 줄어, 안전성의 기회비용이 감소한다. 그 결과 위험자산 비중이 작아진다.","c":"중","v":1},"세무사2021_58-17-3":{"f":"완전손실상계제도가 있는 경우, 투자 수익과 마찬가지로 손실에 대해서도 정부와 투자자가 공동 부담하도록 한다.","w":"완전손실상계에서는 이익에 세금을 내는 만큼 손실도 세율만큼 정부가 보전해 주므로 손실과 이익을 정부와 투자자가 나눈다.","c":"상","v":1},"세무사2021_58-17-4":{"f":"손실상계제도를 전혀 허용하지 않는 경우, 위험자산의 비중은 소득효과와 대체효과의 상대적 크기에 따라 달라진다.","w":"투자의 안전성이 정상재이므로 세금으로 소득이 줄면 안전자산 수요가 줄어 소득효과는 위험자산 비중을 늘린다. 기대수익률 하락의 대체효과는 비중을 줄이므로 결과는 두 효과의 크기에 달려 있다.","c":"상","v":1},"세무사2021_58-17-5":{"f":"손실상계제도를 전혀 허용하지 않는 경우, 소득효과가 대체효과보다 큰 경우에 위험자산의 비중은 증가한다.","w":"투자의 안전성이 정상재이므로 손실상계 불허 때 소득효과는 위험자산 비중을 늘리고 대체효과는 줄인다. 소득효과가 더 크면 위험자산 비중은 증가한다.","c":"상","v":1},"세무사2022_59-03-1":{"f":"감면 총규모가 일정할 때, 소득공제를 세액공제로 변경하면 수직적 공평성은 개선된다.","w":"소득공제는 한계세율이 높은 고소득층에 더 큰 감면을 주고, 세액공제는 소득과 관계없이 같은 금액을 감면한다. 세액공제로 바꾸면 저소득층이 상대적으로 유리해진다.","c":"상","v":1},"세무사2022_59-05-4":{"f":"자본재 구입에 가속상각을 도입하면 투자에 유리하다.","w":"가속상각은 초기에 감가상각비를 많이 공제해 세금 납부를 미루게 하므로 자본의 사용자비용이 낮아져 투자가 늘어난다.","c":"상","v":1},"세무사2022_59-06-4":{"f":"선형누진 소득세에서도 실질적인 조세부담을 증가시킨다.","w":"인플레이션으로 명목소득이 오르면 선형누진세에서도 평균세율이 올라가 실질 조세부담이 늘어난다. 평균세율이 일정한 비례세에서만 실질 부담이 변하지 않는다.","c":"상","v":1},"세무사2022_59-12-3":{"f":"편익원칙에 따라 경제적 능력이 큰 사람일수록 정부서비스 혜택을 많이 받기 때문에 찬성한다.","w":"정부서비스 혜택을 많이 받는 사람이 세금을 많이 내야 한다는 논리는 편익원칙이다. 능력원칙은 지불능력이 큰 사람이 더 낸다는 기준이다.","c":"중","v":1},"세무사2022_59-18-1":{"f":"여가가 정상재일 경우, 비례소득세를 부과하면 소득효과는 노동공급을 증가시키고 대체효과는 감소시키므로 총노동공급은 불확실하다.","w":"소득효과는 노동을 늘리고 대체효과는 노동을 줄여 서로 반대 방향이다. 어느 쪽이 큰지에 따라 총노동공급이 정해진다.","c":"상","v":1},"세무사2022_59-19-3":{"f":"자본스톡의 사용자비용탄력성이 작을수록 법인세가 기업의 투자에 미치는 영향이 작다.","w":"사용자비용탄력성이 작으면 사용자비용이 바뀌어도 투자가 거의 변하지 않으므로 법인세의 투자 효과도 작다.","c":"상","v":1},"세무사2023_60-06-1":{"f":"우리나라의 현행 법인세 최고세율은 25 %이다.","w":"2023년 출제 당시 최고세율은 24%였다(2022년 개정으로 25%에서 인하). 2025년 개정으로 2026년 1월 1일 이후 시작하는 사업연도부터 과세표준 3천억원 초과분에 25%가 적용되어 현행 최고세율은 25%다.","c":"중","v":1},"세무사2023_60-06-2":{"f":"인플레이션이 있을 경우 감가상각공제의 현재가치는 감소하므로 법인세 부담은 증가하게 된다.","w":"감가상각은 취득 당시 가격(역사적 원가)으로 공제하므로 물가가 오르면 공제액의 실질가치가 줄어 법인세의 실질 부담이 커진다.","c":"상","v":1},"세무사2023_60-06-3":{"f":"자기자본에 대한 귀속이자를 경비로 인정해 주지 않는 법인세제상의 특성이 법인들로 하여금 차입에 대한 의존도를 높이는 유인이 될 수 있다.","w":"차입금 이자는 비용으로 공제되지만 자기자본 귀속이자는 공제되지 않으므로 법인은 유상증자보다 부채로 자금을 조달하려 한다.","c":"상","v":1},"세무사2023_60-06-4":{"f":"법인세가 경제적 이윤에 대한 과세가 되기 위해서는 당기순이익이 경제적 이윤과 같아야 한다.","w":"경제적 이윤은 수입에서 귀속이자를 포함한 모든 기회비용과 경제적 감가상각을 뺀 값이다. 과세소득이 이와 일치할 때 법인세가 경제적 이윤에 대한 과세가 된다.","c":"상","v":1},"세무사2023_60-07-1":{"f":"다른 조건이 일정할 때 인플레이션으로 명목소득이 증가하게 되면 소득세 부담은 증가하게 된다.","w":"누진세율 구조에서 명목소득이 오르면 더 높은 세율구간으로 올라가 실질소득이 그대로여도 세 부담이 늘어난다.","c":"상","v":1},"세무사2023_60-07-3":{"f":"부가가치세는 모든 생산단계의 부가가치에 과세되어 수직적 통합을 촉진하지 않는다.","w":"부가가치세는 각 단계에서 추가된 부가가치에 과세하므로 기업이 거래 단계를 합쳐도 세 부담이 줄지 않는다. 수직적 통합에 중립적이다.","c":"상","v":1},"세무사2023_60-07-4":{"f":"비례소득세는 수직적 공평성을 개선하지 못한다.","w":"비례세는 소득과 관계없이 세율이 같아 소득이 높은 사람이 더 높은 비율로 부담하지 않는다. 수직적 공평성을 높이는 것은 누진세다.","c":"상","v":1},"세무사2023_60-07-5":{"f":"이자소득세를 부과할 경우, 소득효과는 저축의욕을 높인다.","w":"이자소득세로 세후 이자소득이 줄면 미래소비를 유지하려고 저축을 늘리는 소득효과가 생긴다. 저축을 줄이는 쪽은 대체효과다.","c":"상","v":1},"세무사2023_60-10-3":{"f":"여가가 정상재일 경우 누진소득세 부과가 노동공급에 미치는 영향은 비례소득세 부과와 유사하지만 고소득자에게 불리하다.","w":"누진소득세는 한계세율이 소득에 따라 올라 고소득자의 순임금이 더 크게 내려가므로 고소득자에게 불리하다.","c":"상","v":1},"세무사2024_61-08-1":{"f":"현재소비가 정상재인 경우에 이자소득세의 부과에 의한 소득효과는 저축의욕을 증가시킨다.","w":"이자소득세로 소득이 줄면 정상재인 현재소비가 줄어드는 소득효과가 생기고, 그만큼 저축이 늘어난다.","c":"상","v":1},"세무사2024_61-08-2":{"f":"비례소득세는 조세부담의 수직적 공평성을 향상시키지 못한다.","w":"비례소득세는 모든 소득에 같은 세율이 적용되어 소득 수준에 따른 부담의 차이를 만들지 않는다.","c":"상","v":1},"세무사2024_61-08-4":{"f":"소득공제는 조세의 부담에 있어서 고소득층이 저소득층에 비해 유리하다.","w":"소득공제의 감세액은 공제액에 한계세율을 곱한 값이라 한계세율이 높은 고소득층에 더 크다.","c":"상","v":1},"세무사2024_61-08-5":{"f":"세액공제의 도입은 한계세율에 영향을 주지 않는다.","w":"세액공제는 산출세액에서 일정 금액을 빼는 방식이라 세율구조를 바꾸지 않는다. 한계세율은 그대로다. 소득공제는 과세표준을 줄이므로 구간에 따라 한계세율에 영향을 줄 수 있다.","c":"상","v":1},"세무사2024_61-09-1":{"f":"부가가치세는 조세부담이 역진적이다.","w":"소득이 낮을수록 소득에서 소비가 차지하는 비중이 커서 단일세율의 부가가치세는 저소득층의 부담률이 더 높다.","c":"상","v":1},"세무사2024_61-09-2":{"f":"수출품의 부가가치세 부담은 국내 판매용 제품과 달리 영(0)이다.","w":"수출품에는 영세율이 적용되어 매출세액이 없고 매입세액은 환급되므로 부가가치세 부담이 남지 않는다.","c":"상","v":1},"세무사2024_61-09-4":{"f":"기업이 자본재 구입 시에 투자세액공제를 적용하면 법인세 부담이 감소한다.","w":"투자세액공제는 자본재 구입액의 일정 비율을 법인세에서 직접 빼 주므로 세 부담이 줄고 투자가 늘어난다.","c":"상","v":1},"세무사2024_61-09-5":{"f":"법인세는 법인의 소득을 과세대상으로 한다.","w":"법인세의 과세대상은 법인의 소득이다. 자산을 과세대상으로 하는 세금은 재산세 등이다.","c":"상","v":1},"세무사2024_61-14-3":{"f":"자본스톡의 사용자비용탄력성이 작을수록 조세제도상 투자 유인책의 효과는 작아진다.","w":"사용자비용탄력성이 작으면 사용자비용이 변해도 투자량이 거의 변하지 않는다. 투자세액공제 같은 유인책으로 사용자비용을 낮춰도 투자가 별로 늘지 않는다.","c":"상","v":1},"세무사2025_62-07-1":{"f":"수출품에 대한 부가가치세 영세율은 매출세액이 없다는 의미이지만 매입세액공제는 하며 환급을 받는다.","w":"영세율은 매출세액을 0으로 하되 매입세액은 공제하여 환급해 주는 제도다. 매입세액을 공제하지 않는 것은 면세다.","c":"상","v":1},"세무사2025_62-07-2":{"f":"부가가치세는 생산단계마다 추가된 부가가치에 대해서만 과세하므로 수직적 통합에 대해 중립적이다.","w":"각 단계의 부가가치에 과세하므로 거래 단계를 합쳐도 세 부담 총액이 같다. 매출액 전체에 단계마다 과세하는 거래세와 달리 통합으로 세금을 줄일 유인이 생기지 않는다.","c":"상","v":1},"세무사2025_62-07-4":{"f":"경제적 이윤에 대한 법인세과세방식은 기업의 생산결정을 왜곡하지 않는다.","w":"경제적 이윤은 정상이윤을 넘는 초과 몫이어서 이를 과세해도 한계적인 투자·생산 결정은 달라지지 않는다. 이 방식은 중립적이다.","c":"상","v":1},"세무사2025_62-07-5":{"f":"타인자본에 대해서만 이자비용공제를 허용하는 법인세는 투자재원조달방식의 왜곡을 가져온다.","w":"타인자본 이자만 공제하면 자기자본보다 차입으로 자금을 조달하는 쪽이 유리해져 조달방식이 부채 쪽으로 쏠린다.","c":"상","v":1},"세무사2025_62-09-2":{"f":"여가가 정상재일 때, 근로소득세의 부과에 따른 노동공급은 대체효과에 의해서 감소한다.","w":"근로소득세는 순임금을 낮추어 여가가 싸지므로 대체효과는 노동공급을 줄인다. 소득효과는 노동공급을 늘려 두 효과가 반대 방향이다.","c":"상","v":1},"세무사2025_62-09-3":{"f":"소득의 증가에 따라서 한계세율이 평균세율보다 클수록 누진성이 증가하게 된다.","w":"한계세율이 평균세율보다 높을수록 소득이 늘 때 평균세율이 더 빠르게 올라가므로 누진성이 커진다.","c":"상","v":1},"세무사2025_62-09-4":{"f":"소득공제는 세액공제보다 한계세율이 높은 고소득층에 유리하다.","w":"소득공제의 감세액은 공제액에 한계세율을 곱한 값이므로 한계세율이 높은 고소득층일수록 크다. 세액공제는 소득과 관계없이 같은 금액을 감면한다.","c":"상","v":1},"세무사2025_62-09-5":{"f":"헤이그-사이먼즈의 포괄적 소득 정의에 의하면, 개인의 경제적 능력의 증가는 실현 여부와 관계없이 소득세의 과세 대상이 된다.","w":"헤이그-사이먼즈 소득은 일정 기간 순자산의 증가분에 소비를 더한 값이다. 미실현 자본이득도 포함하며 실현된 소득에 한정하지 않는다.","c":"상","v":1},"세무사2025_62-10-4":{"f":"이자소득세의 부과에 의한 소득효과는 저축의욕을 높인다.","w":"세후 이자소득이 줄면 현재소비가 줄어드는 소득효과가 생겨 저축이 늘어난다. 저축의욕을 줄이는 쪽은 대체효과다.","c":"상","v":1},"세무사2025_62-11-5":{"f":"부채를 통한 투자의 경우 한계실효세율이 음(-)의 값을 갖는 것은 현행 조세제도가 부채의존도를 높이는 효과를 갖는다는 뜻이다.","w":"차입금 이자공제와 가속상각이 겹치면 부채로 조달한 투자에는 세금이 보조금처럼 작용해 한계실효세율이 음이 된다. 이는 부채 조달을 부추긴다는 뜻이다.","c":"상","v":1},"세무사2025_62-13-1":{"f":"완전손실보상제도가 있는 경우, 위험자산의 비중은 커진다.","w":"손실의 일부를 정부가 보전하면 투자자의 위험부담이 줄어 위험자산 비중이 늘어난다.","c":"상","v":1},"세무사2025_62-13-2":{"f":"완전손실보상제도 하에 정부의 위험부담 비용이 민간부문과 같다면, 조세의 부과는 사회후생을 증진시키지 못한다.","w":"정부가 민간 대신 위험을 떠안아도 위험부담 비용이 같으면 사회 전체가 지는 위험은 그대로여서 후생 증진 효과가 없다. 정부의 위험부담 비용이 더 낮을 때 후생이 늘 수 있다.","c":"중","v":1},"세무사2025_62-13-4":{"f":"손실보상제도를 전혀 허용하지 않는 경우, 대체효과는 위험자산의 비중을 줄인다.","w":"손실을 공제하지 못하면 위험자산의 세후 기대수익률이 내려가 대체효과가 위험자산 비중을 줄인다. 소득효과가 비중을 늘린다.","c":"상","v":1},"세무사2025_62-13-5":{"f":"완전손실보상제도가 있는 경우, 투자 수익과 마찬가지로 손실에 대해서도 정부와 투자자가 공동 부담하도록 한다.","w":"수익에 세금을 내는 만큼 손실도 세율만큼 정부가 보전하므로 이익과 손실을 정부와 투자자가 나눈다.","c":"상","v":1},"세무사2026_63-07-2":{"f":"법인세 과세대상은 경제적 이윤과 항상 일치하지는 않는다.","w":"법인세의 과세소득은 귀속이자를 공제하지 않고 감가상각도 세법상 기준으로 하므로 경제적 이윤과 다르다.","c":"상","v":1},"세무사2026_63-08-1":{"f":"공평한 과세라는 개념은 오직 개인에 대해서만 적용된다는 주장은 법인세 과세를 반대하는 논거이다.","w":"공평성은 사람 사이에서만 따질 수 있어 법인에 세금을 매기는 것은 공평성 기준과 맞지 않는다는 주장은 법인세 반대론의 논거다. 법인세 찬성론의 근거는 법인의 독자성, 법인이 받는 사회적 혜택, 정책 수단, 사내유보 이윤 과세 등이다.","c":"상","v":1},"세무사2026_63-10-5":{"f":"대부분의 국가들은 법인세와 소득세 간 부분적 통합을 이루고 있다.","w":"법인세와 소득세 간 완전 통합을 한 나라는 드물고, 배당세액공제 같은 방식으로 이중과세를 부분적으로 줄인다.","c":"상","v":1},"세무사2026_63-12-3":{"f":"여가가 정상재일 경우, 비례소득세 부과로 인한 대체효과가 소득효과보다 크다면 총노동 공급은 감소한다.","w":"대체효과는 노동을 줄이고 소득효과는 노동을 늘린다. 대체효과가 더 크면 총노동공급은 줄어든다.","c":"상","v":1},"세무사2026_63-16-1":{"f":"불완전한 자본시장 가정하에서 배당정책은 기업의 가치에 영향을 미친다.","w":"배당무관련 정리는 완전자본시장(세금·거래비용 없음)을 전제한다. 시장이 불완전하면 세금과 거래비용 때문에 배당정책이 기업가치에 영향을 준다.","c":"상","v":1},"세무사2026_63-16-3":{"f":"주주는 기업의 배당정책에 영향을 받지 않는다.","w":"배당무관련 정리에서는 배당을 받아 재투자하든 유보 이익으로 주가 상승을 얻든 주주의 부가 같아 배당정책에 무차별하다.","c":"중","v":1},"세무사2026_63-16-4":{"f":"대부분의 국가는 소득세상 배당금과 자본이득을 다르게 취급한다.","w":"배당소득은 일반적으로 소득세를 내고, 자본이득은 낮은 세율이나 실현 시점 과세, 비과세로 우대하는 나라가 많다.","c":"상","v":1},"세무사2026_63-16-5":{"f":"실증연구에 따르면, 조세는 기업의 배당정책에 영향을 미치는 것으로 나타난다.","w":"배당소득과 자본이득의 세 부담 차이가 배당 결정에 영향을 준다는 실증연구가 많다. 영향이 없다고 단정하는 연구 결과는 일반적이지 않다.","c":"중","v":1},"세무사2016_53-05-4":{"f":"이론적으로 동결효과(lock-in effect)는 부동산 거래를 위축시킨다.","w":"동결효과는 양도소득세를 피하려고 매도를 미루는 현상이라 거래를 줄인다. 재산세 같은 보유 과세는 오히려 보유 부담을 키워 매도를 늘리는 쪽으로 작용한다.","c":"중","v":1},"세무사2017_54-15-2":{"f":"기초생활필수품은 면세 대상이다.","w":"기초생활필수품은 면세 대상이다. 영세율 대상은 수출 등이며, 영세율은 매입세액을 환급해 주는 방식이다.","c":"상","v":1},"세무사2021_58-01-5":{"f":"어떤 상품이 면세의 대상인 경우 중간단계에서 납부한 부가가치세는 환급해 주지 않는다.","w":"면세는 매출세액이 없는 대신 매입세액도 공제·환급되지 않아 앞 단계의 부가가치세가 비용으로 남는다. 매입세액까지 환급하는 것은 영세율이다.","c":"상","v":1},"세무사2021_58-13-2":{"f":"부동산 보유세 인상 시 조세의 자본화에 의하여 부동산 가격이 하락하게 된다.","w":"보유세가 오르면 미래 순수익의 현재가치가 줄어들고, 그만큼 부동산 가격이 내려가는 것이 조세의 자본화다.","c":"상","v":1},"세무사2022_59-01-5":{"f":"우리나라는 소비형 부가가치세를 채택하고 있다.","w":"우리나라는 자본재 구입액도 구입 시점에 매입세액으로 공제하는 소비형 부가가치세를 채택한다. 총소득형은 자본재 구입액을 공제하지 않는다.","c":"상","v":1},"세무사2026_63-09-1":{"f":"부가가치세는 모든 재화와 용역에 과세하는 일반소비세이다.","w":"부가가치세는 특정 물품에 한정하는 개별소비세와 달리 면세 대상을 제외한 거의 모든 재화·용역의 부가가치에 과세한다.","c":"상","v":1},"세무사2026_63-09-2":{"f":"부가가치세는 1954년 프랑스에서 제조업을 대상으로 하는 부분적인 과세제도로 처음 등장했다.","w":"부가가치세는 1954년 프랑스에서 처음 도입되었고 1968년 일반적 형태로 확대되었다. 독일이 처음이 아니다.","c":"중","v":1},"세무사2026_63-09-3":{"f":"미국은 연방 차원에서 부가가치세를 도입하지 않고 주 정부가 소매판매세를 과세하고 있다.","w":"미국은 연방 부가가치세가 없고, 대부분의 주가 소매판매세를 과세한다.","c":"상","v":1},"세무사2026_63-09-5":{"f":"우리나라 부가가치세는 도입 이래 국세 세목 가운데 세수가 가장 크지는 않다.","w":"소득세나 법인세의 세수가 부가가치세보다 많았던 해가 있고, 최근에는 소득세 세수가 부가가치세보다 많다.","c":"중","v":1},"세무사2022_59-31-1":{"f":"공공사업을 추진하는 행정주체는 내부적 편익과 외부적 편익을 모두 고려한다.","w":"공공사업은 사업 주체의 직접 편익뿐 아니라 사회 전체에 미치는 외부적 편익까지 따진다. 외부적 편익을 더 중시한다고 단정하는 근거는 찾기 어렵다.","c":"중","v":1},"세무사2022_59-31-2":{"f":"공공사업의 목표는 소득재분배, 총 소비 증대를 통한 국민의 후생증진에 국한되지 않는다.","w":"공공사업은 효율성 증대, 소득재분배, 고용 안정, 지역개발 등 여러 목표를 함께 추구한다.","c":"상","v":1},"세무사2022_59-31-3":{"f":"공공사업에서 발생하는 금전적 편익은 사회 전체적인 후생을 증진시키지 않는다.","w":"금전적 편익은 가격 변화로 한 집단의 이득이 다른 집단의 손실로 넘어가는 이전이어서 사회 전체로는 상쇄된다. 실질적 편익만 후생을 늘린다.","c":"상","v":1},"세무사2022_59-31-4":{"f":"공공사업의 유형적 편익과 무형적 편익 가운데 어느 쪽이 큰지는 사업에 따라 다르다.","w":"무형적 편익이 항상 크다고 할 수 없다. 사업마다 두 편익의 비중이 달라 일률적으로 비교할 수 없다.","c":"중","v":1},"세무사2022_59-39-1":{"f":"칼도-힉스 보상기준을 충족한 투자계획을 채택한다.","w":"비용편익분석은 순편익이 양(+)이면 손해 보는 사람이 있어도 이득을 본 사람이 보상할 수 있다는 칼도-힉스 기준을 쓴다. 누구도 손해 보지 않아야 하는 파레토기준은 현실의 공공사업에 적용하기 어렵다.","c":"상","v":1},"세무사2022_59-39-2":{"f":"공공부문뿐 아니라 민간부문의 투자계획 타당성 판정에도 적용된다.","w":"현재가치법은 투자의 비용과 편익을 할인해 비교하는 방법으로 민간 투자 평가에도 쓰인다.","c":"상","v":1},"세무사2022_59-39-4":{"f":"현재가치법은 투자계획의 채택가능성을 평가할 뿐 아니라 순현재가치의 크기로 투자계획들 간 우선순위도 결정할 수 있다.","w":"순현재가치가 양(+)이면 채택 가능하고, 여러 사업 중에서는 순현재가치가 큰 순서로 우선순위를 정할 수 있다.","c":"상","v":1},"세무사2022_59-39-5":{"f":"내부수익률이 투자계획에 소요되는 자금의 기회비용인 할인율보다 크다면 그 투자계획은 채택된다.","w":"내부수익률이 할인율을 넘으면 순현재가치가 양(+)이므로 채택한다.","c":"상","v":1},"세무사2023_60-39-4":{"f":"시장이자율이 사회적 할인율보다 높을 때 시장이자율을 할인율로 사용하면 공공사업의 경제성이 작아질 수 있다.","w":"할인율이 높아질수록 먼 장래의 편익의 현재가치가 줄어 순현재가치가 작아지고 공공사업의 경제성이 낮아진다.","c":"상","v":1},"세무사2025_62-31-1":{"f":"잠재가격은 시장이 불완전하거나 왜곡된 경우 자원의 사회적 기회비용을 계산하여 비용과 편익의 평가기준으로 사용하는 방법이다.","w":"시장가격이 사회적 기회비용을 제대로 반영하는 안정적인 시장에서는 시장가격을 쓰면 된다. 잠재가격(그림자가격)이 필요한 것은 시장이 불완전할 때다.","c":"상","v":1},"세무사2025_62-31-2":{"f":"독점자가 생산한 상품을 구입하여 그 상품의 생산량이 그만큼 증가하였다면 한계비용을 평가기준으로 한다.","w":"생산량이 늘면 추가로 투입된 자원의 가치가 사회적 비용이고, 이는 독점자의 한계비용이다. 평균비용은 기준이 아니다.","c":"상","v":1},"세무사2025_62-31-4":{"f":"물품세가 부과된 상품이 공공사업에 투입되었으나 그 상품의 생산량이 불변이라면 소비자가격이 적절한 평가기준이다.","w":"생산량이 그대로이면 공공사업이 민간 소비를 대체한 것이므로 소비자가 지불하던 세금 포함 가격이 포기한 편익을 나타낸다. 세금을 뺀 생산자가격은 생산량이 늘어난 경우에 쓴다.","c":"중","v":1},"세무사2025_62-31-5":{"f":"물품세가 부과된 상품이 공공사업에 투입되어 그 상품의 생산량이 투입된 양만큼 증가하였다면 생산자가격을 평가기준으로 한다.","w":"민간 소비는 줄지 않고 추가 자원이 들어갔으므로 세금을 뺀 생산자가격으로 평가한다.","c":"하","v":1},"세무사2025_62-32-2":{"f":"무형적 편익과 비용은 시장에서 파악되지 않아도 공공투자사업의 비용편익 분석에 고려해야 한다.","w":"소음, 환경 훼손, 경관 같은 무형적 편익과 비용도 사회적 후생에 영향을 주므로 간접 추정 등으로 반영한다.","c":"상","v":1},"세무사2016_53-06-5":{"f":"외부성이 지역 경계를 넘는 공공재는 중앙정부가, 편익이 지역 안에 국한되는 공공재는 지방정부가 공급하는 것이 바람직하다.","w":"공급 주체는 외부효과의 공간적 범위에 따라 정한다. 긍정이냐 부정이냐의 부호로 정하지 않는다.","c":"상","v":1},"세무사2016_53-07-4":{"f":"관료들이 중앙정부로부터 교부금을 받았다는 사실을 알리지 않을 때 나타나는 현상이다.","w":"재정착각은 주민이 교부금이 들어온 사실을 모르거나 정확히 인식하지 못해 공공재의 조세가격이 낮아졌다고 착각할 때 나타난다. 관료가 교부금 사실을 공개하면 오히려 착각이 줄어든다.","c":"중","v":1},"세무사2017_54-22-5":{"f":"대응보조금(matching grant)은 공공재의 소비를 증가시키지만 사적재의 소비는 증가할 수도 감소할 수도 있다.","w":"대응보조금은 공공재 가격을 낮춰 소득효과와 대체효과가 모두 공공재 소비를 늘린다. 사적재는 소득효과가 늘리고 대체효과가 줄이므로 방향이 정해지지 않는다.","c":"중","v":1},"세무사2021_58-19-4":{"f":"중앙정부의 교부금으로 인해 지방의 재정자립도가 낮아진다.","w":"교부금은 지방의 자체수입이 아닌 의존재원이라 교부금이 늘면 재정자립도(자체수입/총세입)는 낮아진다.","c":"상","v":1},"세무사2021_58-28-5":{"f":"공공재의 생산 규모가 증가할수록 단위당 생산비용이 하락하는 규모의 경제가 발생하지 않아야 한다.","w":"티부 모형은 지역 규모가 커질수록 평균비용이 줄어드는 규모의 경제가 없고 최적 규모가 존재한다고 가정한다.","c":"상","v":1},"세무사2022_59-04-3":{"f":"대응보조금은 사적재와 공공서비스 선택에서 소득효과와 대체효과가 모두 공공서비스 소비량을 증가시킨다.","w":"대응보조금은 공공서비스 가격을 낮춰 소득효과도 대체효과도 공공서비스 소비를 늘리므로 변화 방향이 분명하다.","c":"상","v":1},"세무사2023_60-18-2":{"f":"중앙정부는 법률로 국세를 신설할 수 있으며 지방자치단체도 법률에 근거하여야 지방세목을 신설할 수 있다.","w":"조세법률주의에 따라 세목은 법률로 정한다. 지방자치단체가 조례만으로 지방세목을 새로 만들 수는 없다.","c":"상","v":1},"세무사2023_60-19-1":{"f":"지방분권의 정도를 간접적으로 파악할 수 있는 중앙집권화율은 중앙정부의 지출을 정부 전체의 지출로 나누어 계산한다.","w":"중앙집권화율은 중앙정부 지출을 중앙정부와 지방정부 지출의 합으로 나눈 비율이다. 지방정부 지출로 나누지 않는다.","c":"상","v":1},"세무사2024_61-17-2":{"f":"무조건부 교부금의 경우에는 지역주민들의 소득증가와 조세부담의 감소를 가져오게 된다.","w":"무조건부 교부금은 지역 소득을 늘리고 주민이 내야 할 조세를 줄여 주는 효과가 있다.","c":"상","v":1},"세무사2024_61-17-3":{"f":"지역주민들의 공공재 소비규모와 후생수준은 교부금의 유형에 따라 달라진다.","w":"교부금이 무조건부냐, 조건부냐, 대응이냐에 따라 소득효과와 대체효과가 달라져 소비와 후생 수준이 다르다.","c":"상","v":1},"세무사2024_61-17-4":{"f":"무조건부 교부금의 경우에는 소득효과로 지역주민들의 공공재와 사용재의 소비를 모두 증가시킨다.","w":"무조건부 교부금은 가격 변화가 없는 소득 증가라 두 재화가 모두 정상재이면 소비가 함께 늘어난다.","c":"상","v":1},"세무사2024_61-17-5":{"f":"조건부 대응교부금의 경우에는 소득효과와 대체효과가 모두 지역주민들의 공공재 소비를 증가시킨다.","w":"대응교부금은 공공재의 상대가격을 낮추어 대체효과가 소비를 늘리고 소득효과도 소비를 늘린다.","c":"상","v":1},"세무사2024_61-18-5":{"f":"지방정부가 보조금을 받아서 공공재를 공급하는 경우에는 중앙집권화의 정도가 과소평가된다.","w":"보조금은 중앙정부의 재원이지만 지출은 지방정부의 지출로 잡히므로 중앙집권화율이 실제보다 낮게 나온다.","c":"상","v":1},"세무사2024_61-19-1":{"f":"지방교부세는 무조건부(비대응) 교부금이다.","w":"지방교부세는 용도를 정하지 않고 지급하는 무조건부 교부금이다. 대응교부금은 지방정부 지출액에 비례해 중앙정부가 지원한다.","c":"상","v":1},"세무사2024_61-19-2":{"f":"국고보조금은 조건부 교부금이다.","w":"국고보조금은 특정 사업에 쓰도록 용도를 정해 지급하는 조건부 교부금이다.","c":"상","v":1},"세무사2024_61-19-3":{"f":"국고보조금은 지방정부의 의존재원이다.","w":"국고보조금은 중앙정부에서 이전받는 의존재원이다. 지방세와 세외수입이 자체재원이다.","c":"상","v":1},"세무사2024_61-19-5":{"f":"지방교부세와 국고보조금은 지방정부의 재정자립도를 개선하지 못한다.","w":"두 재원 모두 중앙정부에서 이전받는 의존재원이라 자체수입 비중인 재정자립도를 높이지 못한다.","c":"상","v":1},"세무사2025_62-14-1":{"f":"정부부문의 총지출 중 중앙정부의 직접지출이 차지하는 비율을 중앙집권화율이라 하며, 분권 수준을 간접적으로 파악하는 지표로 사용한다.","w":"중앙집권화율은 중앙정부가 지방에 넘겨주는 교부금·보조금을 뺀 중앙정부의 직접지출로 계산한다. 이전재원까지 넣은 총지출로 계산하면 같은 돈이 중앙과 지방 지출에 두 번 잡힌다.","c":"중","v":1},"세무사2025_62-17-1":{"f":"보조금이 지급될 때, 지방세가 줄어들지 않고 지방정부 지출이 더 크게 증가하는 현상을 끈끈이 효과라 한다.","w":"끈끈이 효과는 정액교부금이 주민 소득 증가보다 지방정부 지출을 훨씬 더 많이 늘리는 현상이다. 민간지출이 늘어나는 현상이 아니다.","c":"상","v":1},"세무사2016_53-22-5":{"f":"","w":"한계수입과 한계비용이 같은 점은 독점기업의 이윤극대화 조건이다. 이렇게 가격을 매기면 생산량이 줄어 한계비용가격설정으로 얻으려던 효율성을 잃으므로 손실 보전 방안이 아니다. 손실 보전 방안은 일반 세원 보조, 평균비용가격, 가격차별, 이부가격이다.","c":"중","v":1},"세무사2016_53-32-1":{"f":"비배제성이 존재할 경우 공공재의 정확한 수요를 도출할 수 없다.","w":"비배제성 때문에 값을 내지 않고도 이용할 수 있어 소비자가 선호를 숨기는 무임승차가 생기고, 정확한 수요를 알기 어렵다.","c":"상","v":1},"세무사2016_53-32-2":{"f":"공공재의 전체 수요곡선은 개별수요곡선을 수직으로 합계한 것이다.","w":"공공재는 모두가 같은 양을 소비하므로 같은 수량에서 개인별 지불의사를 더해 시장수요를 구한다. 수평합은 사적재 방식이다.","c":"상","v":1},"세무사2016_53-32-4":{"f":"파레토 효율은 공공재 개별 이용자의 한계편익의 합과 한계비용이 일치할 때 달성된다.","w":"사무엘슨 조건에 따라 공공재의 최적 공급은 개인별 한계편익(한계대체율)의 합이 한계비용(한계변환율)과 같은 점이다.","c":"상","v":1},"세무사2016_53-32-5":{"f":"공공재의 각 이용자가 부담하는 공공재 가격의 합은 공급에 따르는 한계비용과 일치한다.","w":"린달 균형에서 개인이 내는 가격은 자신의 한계편익과 같고, 모든 이용자의 가격을 합한 값이 한계비용이다. 개별 가격이 한계비용과 같지는 않다.","c":"상","v":1},"세무사2017_54-26-1":{"f":"정부에 의해 공급되지 않고 기업에 의해 공급되는 재화라도 모두 사적재인 것은 아니다.","w":"재화가 사적재인지는 공급 주체가 아니라 경합성과 배제성으로 정해진다. 기업이 공급하는 방송 등에는 공공재적 성격이 있다.","c":"상","v":1},"세무사2017_54-26-2":{"f":"우편과 철도서비스는 순수공공재에 해당하지 않는다.","w":"우편과 철도는 요금을 내지 않는 사람을 배제할 수 있고 이용이 경합하는 사적재적 성격이 강해 순수공공재가 아니다.","c":"상","v":1},"세무사2017_54-26-3":{"f":"클럽재는 시장을 통해서도 효율적으로 공급될 수 있다.","w":"클럽재는 회원 요금으로 배제가 가능해 시장이나 민간 클럽이 효율적으로 공급할 수 있다.","c":"상","v":1},"세무사2017_54-26-4":{"f":"공공재의 규모가 일정할 때, 추가적 사용에 따른 한계비용은 영(0)이다.","w":"공공재는 비경합적이어서 이용자가 한 명 더 늘어도 추가 비용이 들지 않는다.","c":"상","v":1},"세무사2017_54-27-4":{"f":"수요표출메커니즘을 이용하면 정부의 균형예산 조건이 항상 충족되지는 않는다.","w":"클라크세 같은 수요표출메커니즘에서는 거둔 세금이 공공재 비용과 일치하지 않아 재정 잉여나 부족이 생길 수 있다.","c":"상","v":1},"세무사2021_58-20-1":{"f":"공공요금에서 더 많이 소비하는 사람이 더 많은 비용을 부담해야 한다는 원칙은 공평성의 한 기준일 뿐, 효율성 기준과 충돌할 수 있다.","w":"소비량에 비례해 부담하는 것은 수익자부담(편익원칙)으로 공평성 기준이다. 요금의 효율성 기준은 한계비용과 일치시키는 것이어서 이 원칙을 일률적으로 적용할 수는 없다.","c":"하","v":1},"세무사2021_58-20-2":{"f":"외부성이 존재하는 경우 사회적 한계비용과 일치하는 수준에서 가격이 설정되어야 한다.","w":"외부비용이 있으면 사적 한계비용에 외부비용을 더한 사회적 한계비용을 가격에 반영해야 효율적이다.","c":"상","v":1},"세무사2021_58-20-3":{"f":"기존시설에 대한 초과 수요가 존재하는 경우 한계비용에 경제적 지대를 더한 수준에서 가격이 설정되어야 한다.","w":"시설용량이 고정된 단기에 초과수요가 있으면 가격을 한계비용보다 높여 수요를 용량에 맞추고, 그 차이가 경제적 지대다.","c":"상","v":1},"세무사2021_58-20-5":{"f":"램지(F. Ramsey)의 원칙에 따르면 수요의 가격탄력성이 작을수록 가격을 한계비용보다 높게 설정할 때 효율성이 제고된다.","w":"램지 가격은 가격 인상에 따른 수요 감소가 작은, 즉 탄력성이 낮은 재화일수록 한계비용보다 더 높게 책정하는 역탄력성 규칙이다.","c":"상","v":1},"세무사2022_59-27-5":{"f":"가치재는 사적재이면서 정부가 소비를 장려하거나 공급하는 재화이다.","w":"가치재는 시장에서 배제와 경합이 가능한 사적재인데, 사회가 바람직하다고 보아 정부가 개입하는 재화다. 순수공공재와 다르다.","c":"상","v":1},"세무사2023_60-16-2":{"f":"민간기업이 생산하고 가격규제를 하지 않으면 사회적 최적생산량 달성이 불가능하다.","w":"규모의 경제가 있는 자연독점 상태에서 규제가 없으면 이윤극대화 가격을 매겨 사회적 최적 생산량보다 적게 생산한다.","c":"상","v":1},"세무사2023_60-16-3":{"f":"공공서비스의 경우 이부가격제도(two-part tariff)를 적용하면 결손을 줄일 수 있으며, 효율적 생산량에 도달하는 것도 가능하다.","w":"사용량당 요금을 한계비용으로 정하고 고정 요금으로 손실을 메우면 효율적 생산량과 손실 보전을 함께 이룰 수 있다.","c":"상","v":1},"세무사2023_60-16-4":{"f":"한계비용가격설정을 사용하는 경우 해당 공기업의 경제적 이윤은 음(-)이 된다.","w":"규모의 경제가 있으면 평균비용이 한계비용보다 높아, 가격을 한계비용으로 정하면 평균비용을 회수하지 못해 손실이 난다.","c":"상","v":1},"세무사2023_60-16-5":{"f":"평균비용가격설정을 사용하는 경우 해당 공기업의 경제적 이윤은 영(0)이 된다.","w":"가격을 평균비용과 같게 정하면 수입과 총비용이 같아져 초과이윤도 손실도 없다.","c":"상","v":1},"세무사2023_60-26-2":{"f":"현실에서 대부분의 공공재는 순수공공재가 아니라 경합성이나 배제성을 일부 가진 불순수공공재이다.","w":"순수공공재는 국방처럼 드물고, 도로·공원처럼 혼잡이나 배제 가능성이 있는 준공공재가 대부분이다. 시장 성립 여부도 재화에 따라 다르다.","c":"상","v":1},"세무사2023_60-26-3":{"f":"클럽재(club goods)는 배제성 적용이 가능하다.","w":"클럽재는 비경합적이지만 배제할 수 있어 회비 등으로 이용자를 가려낼 수 있다.","c":"상","v":1},"세무사2023_60-26-4":{"f":"순수공공재는 비배제성과 비경합성을 동시에 충족한다.","w":"모든 공공재가 두 성질을 다 가지는 것은 아니다. 두 성질을 모두 갖춘 것은 순수공공재이고, 일부만 갖춘 공공재도 있다.","c":"상","v":1},"세무사2023_60-26-5":{"f":"공공재의 소비자들은 자신의 선호를 정확하게 표출하지 않는다.","w":"대가를 내지 않아도 이용할 수 있어 소비자가 선호를 숨기고 무임승차하려 하므로 선호가 과소 표출된다.","c":"상","v":1},"세무사2024_61-16-2":{"f":"시설용량에 제한이 있는 시설에 초과수요가 발생하는 경우 한계비용에 경제적 지대를 더한 수준에서 가격을 결정해야 효율적이다.","w":"용량이 제한되면 한계비용만 받아서는 수요가 용량을 넘는다. 경제적 지대를 더해 수요를 용량에 맞춘다.","c":"상","v":1},"세무사2024_61-16-3":{"f":"공공요금은 소비과정에서의 효율성뿐 아니라 생산과정에서의 효율성 개선과도 관련된다.","w":"요금 설정 방식은 공급자의 비용 절감 유인에도 영향을 준다. 평균비용가격설정은 비용 절감 유인을 주지 못한다.","c":"중","v":1},"세무사2024_61-16-4":{"f":"공평성의 관점에서 보면 편익원칙에 입각하여 요금을 부과해야 한다.","w":"공공서비스를 이용하는 만큼 요금을 내는 것은 편익원칙(수익자부담)이다. 능력원칙은 소득이 높은 사람이 더 낸다는 기준이어서 요금보다 조세에 맞다.","c":"상","v":1},"세무사2024_61-16-5":{"f":"규모의 경제가 존재하는 경우 평균비용가격설정은 사회적 최적수준에 비해 과소생산을 유발한다.","w":"평균비용은 한계비용보다 높아 가격이 한계비용을 웃돈다. 그 결과 생산량이 가격과 한계비용이 같은 최적 수준보다 적다.","c":"상","v":1},"세무사2024_61-27-1":{"f":"서로 찬성하는 것은 우월전략균형이 아니다.","w":"상대가 찬성하면 나는 반대할 때 30, 찬성할 때 5를 얻고, 상대가 반대하면 반대할 때 0, 찬성할 때 -20을 얻는다. 반대가 우월전략이라 서로 반대하는 것이 우월전략균형이고 서로 찬성은 균형이 아니다.","c":"상","v":1},"세무사2024_61-27-2":{"f":"서로 찬성하는 것은 우월전략균형도 내쉬균형도 아니다.","w":"서로 찬성한 상태에서는 한쪽이 반대로 바꾸면 이득을 보므로 내쉬균형이 아니다. 유일한 내쉬균형은 서로 반대하는 것이다.","c":"상","v":1},"세무사2024_61-27-3":{"f":"무임승차문제로 인해 이 게임의 내쉬균형은 서로 반대하는 것이다.","w":"무임승차 유인이 있어도 내쉬균형은 존재하며, 서로 반대하는 것이 유일한 내쉬균형이다.","c":"상","v":1},"세무사2024_61-27-4":{"f":"이 문제는 치킨 게임이 아니므로 한 사람만 찬성하는 것은 내쉬균형이 아니다.","w":"치킨 게임이라면 한쪽만 양보하는 상태가 균형이 되지만, 이 게임의 유일한 내쉬균형은 서로 반대하는 것이다.","c":"상","v":1},"세무사2025_62-19-5":{"f":"램지(F. Ramsey)의 원칙에 따르면 수요의 가격탄력성이 작을수록 가격을 한계비용보다 높게 설정할 때 효율성이 제고된다.","w":"탄력성이 작은 재화는 가격을 올려도 수요 감소가 적어 초과부담이 작으므로 가격을 한계비용보다 더 높이는 것이 효율적이다.","c":"상","v":1},"세무사2025_62-21-1":{"f":"비배제성이란 대가를 지불하지 않고도 소비에 참여할 수 있는 성질을 의미한다.","w":"대가를 내지 않고도 소비할 수 있는 성질은 비배제성이다. 비경합성은 한 사람의 소비가 다른 사람의 소비를 줄이지 않는 성질이다.","c":"상","v":1},"세무사2025_62-21-3":{"f":"지방정부가 공급하는 상수도는 사적재의 성격이 강하다.","w":"상수도는 요금을 내지 않으면 배제할 수 있고 한 사람이 쓰면 다른 사람이 쓸 양이 줄어 사적재에 가깝다.","c":"상","v":1},"세무사2025_62-21-4":{"f":"모든 소비자는 등량의 공공재 소비로부터 서로 다른 수준의 효용을 얻을 수 있다.","w":"공공재는 같은 양을 소비하지만 선호가 사람마다 달라 얻는 효용도 다르다.","c":"상","v":1},"세무사2025_62-21-5":{"f":"소비자들은 공공재에 대한 수요를 정확하게 표출하지 않는다.","w":"무임승차 유인 때문에 소비자는 선호를 낮춰 말하는 경향이 있어 수요가 정확히 드러나지 않는다.","c":"상","v":1},"세무사2026_63-18-3":{"f":"이부가격(two-part tariff)을 적용하면 공급자의 결손을 줄이면서 효율적인 자원 배분도 실현할 수 있다.","w":"사용 요금을 한계비용으로 정하면 효율적 소비량에 이르고, 고정 요금으로 평균비용과의 차이만큼의 손실을 메운다.","c":"상","v":1},"세무사2016_53-16-5":{"f":"수요의 가격탄력성이 낮은 재화일수록 높은 세율을 적용한다.","w":"초과부담을 줄이려면 수요가 가격에 덜 반응하는 재화에 높은 세율을 매긴다. 이것이 램지의 역탄력성 규칙이다.","c":"상","v":1},"세무사2017_54-07-1":{"f":"조세수입이 동일한 경우, 한 재화보다는 두 재화에 세금을 부과할 때 초과부담은 작아진다.","w":"초과부담은 세율의 제곱에 비례해 커진다. 같은 세수를 여러 재화에 나누어 낮은 세율로 걷는 편이 초과부담이 작다.","c":"상","v":1},"세무사2017_54-07-2":{"f":"개별물품세가 부과되어 수요량이 변하지 않더라도 초과부담은 존재할 수 있다.","w":"초과부담은 보상수요의 변화, 곧 대체효과로 측정한다. 소득효과와 대체효과가 상쇄해 수요량이 그대로여도 상대가격 왜곡에 따른 초과부담은 생긴다.","c":"상","v":1},"세무사2017_54-07-3":{"f":"현금보조는 부(-)의 정액세의 일종이므로 초과부담이 발생하지 않는다.","w":"현금보조는 상대가격을 바꾸지 않고 소득만 바꾸므로 대체효과가 없고 초과부담이 없다.","c":"상","v":1},"세무사2017_54-07-4":{"f":"두 재화가 대체관계인 경우, X재에 조세가 부과된 상태에서 Y재에 조세를 부과하면 Y재의 과세에 따라 경제 전체의 초과부담이 줄어들 수도 있다.","w":"이미 X재 과세로 왜곡이 있는 상태에서는 차선의 원리가 적용된다. 대체재인 Y재에 과세하면 X재 왜곡이 줄어 전체 초과부담이 감소할 수 있다.","c":"상","v":1},"세무사2017_54-11-4":{"f":"이미 조세를 부과하고 있는 상태에서 새로운 조세를 부과하면 초과부담은 오히려 줄어들 수도 있다.","w":"이미 왜곡이 있는 상태에서는 차선이론에 따라 새 조세가 기존 왜곡을 줄이면 초과부담이 감소할 수 있다.","c":"중","v":1},"세무사2017_54-14-5":{"f":"임금률이 낮은 개인이 높은 개인보다 더 큰 효용을 누릴 수는 없다.","w":"고임금자는 저임금자와 같은 소득을 더 적은 노동시간으로 벌 수 있어 언제든 저임금자의 선택을 따라 할 수 있다. 그래서 멀리즈의 최적소득세에서 임금률이 높은 사람의 효용이 낮은 사람보다 낮아질 수 없다.","c":"상","v":1},"세무사2017_54-35-5":{"f":"최적이부요금은 비용함수와 수요함수 외에 고정 수수료에 대한 소비자의 탄력성 등도 알아야 산출할 수 있다.","w":"고정 수수료와 사용 요금의 비중은 고정 수수료에 대한 소비자의 탄력성에 달려 있어 비용함수와 수요함수만으로는 정할 수 없다.","c":"중","v":1},"세무사2021_58-02-1":{"f":"조세부과 시 발생하는 상대가격 변화에 의해 나타나는 납세자 선택의 왜곡현상을 의미한다.","w":"초과부담은 소득 변화가 아니라 상대가격 변화에 따른 대체효과로 생기는 선택의 왜곡이다.","c":"상","v":1},"세무사2021_58-02-2":{"f":"서로 다른 재화에 대해 조세징수액이 같더라도 초과부담의 크기는 다르게 나타날 수 있다.","w":"초과부담은 세율과 수요의 가격탄력성에 따라 달라지므로 세수가 같아도 재화마다 크기가 다르다.","c":"상","v":1},"세무사2021_58-02-4":{"f":"조세부과로 인하여 소득효과와 대체효과가 상반된 방향으로 작용하여 상쇄되어 수요량의 변화가 없더라도 초과부담은 발생한다.","w":"초과부담은 대체효과만으로 측정한다. 소득효과가 대체효과를 상쇄해 수요량이 그대로여도 대체효과가 있으면 초과부담은 있다.","c":"상","v":1},"세무사2021_58-02-5":{"f":"초과부담은 조세부과로 인해 발생하는 소비자잉여와 생산자잉여의 감소분에서 조세수입을 뺀 것이다.","w":"잉여 감소분 중 정부 세수로 옮겨 간 몫은 손실이 아니다. 초과부담은 세수를 제외한 순손실이다.","c":"상","v":1},"세무사2023_60-02-1":{"f":"초과부담은 사회후생 감소분에서 조세수입을 차감한 것이다.","w":"조세로 줄어든 소비자잉여와 생산자잉여 중 세수로 옮겨 간 부분을 뺀 순손실이 초과부담이다.","c":"상","v":1},"세무사2023_60-02-2":{"f":"초과부담은 주로 상대가격 변화에 따른 대체효과 때문에 발생한다.","w":"조세 부담의 전가는 누가 세금을 실질적으로 지는가의 문제다. 초과부담은 가격 왜곡으로 인한 소비·생산 선택의 변화에서 생긴다.","c":"상","v":1},"세무사2023_60-02-3":{"f":"세율이 높으면 조세수입이 늘어나지만 초과부담도 커진다.","w":"초과부담은 세율의 제곱에 비례해 커진다. 세율이 높을수록 초과부담이 줄지 않는다.","c":"상","v":1},"세무사2023_60-02-4":{"f":"수요의 가격탄력성이 클수록 초과부담은 커진다.","w":"수요가 가격에 민감하면 과세 때 거래량이 많이 줄어 후생 손실이 크다.","c":"상","v":1},"세무사2023_60-03-4":{"f":"생활필수품에 낮은 세율을 부과하는 것은 램지규칙에는 부합하지 않으나 사회적으로는 바람직하다.","w":"램지규칙은 수요가 비탄력적인 필수품에 높은 세율을 요구해 저소득층에 부담이 되므로 분배 면에서 바람직하지 않다. 필수품에 낮은 세율은 형평성을 위한 것이다.","c":"상","v":1},"세무사2024_61-03-2":{"f":"세율이 높아지면 초과부담이 늘어나지만 조세수입은 늘어나지 않을 수도 있다.","w":"세율이 일정 수준을 넘으면 거래량 감소가 커져 조세수입이 오히려 줄어드는 래퍼곡선 구간이 있다.","c":"상","v":1},"세무사2025_62-04-3":{"f":"조세부과로 인한 초과부담은 상대가격의 변화로 인한 소득효과와 대체효과가 서로 반대방향으로 작용하더라도 발생한다.","w":"초과부담은 보상수요, 곧 대체효과로 측정한다. 소득효과가 대체효과를 상쇄해 수요량이 그대로여도 상대가격이 왜곡되었으면 초과부담이 생긴다.","c":"상","v":1},"세무사2026_63-04-5":{"f":"대체재의 수가 적은 재화일수록 조세 부과의 초과부담은 작아진다.","w":"대체재가 적으면 수요가 비탄력적이어서 과세해도 소비 변화가 작다. 초과부담은 수요의 가격탄력성이 클수록 커진다.","c":"상","v":1},"세무사2016_53-19-3":{"f":"한계세율이 점증하는 누진소득세 체계에서 소득공제를 도입하면 고소득층의 세후 소득을 증가시킨다.","w":"소득공제의 감세액은 공제액에 한계세율을 곱한 값이라 한계세율이 높은 고소득층의 세후 소득이 더 크게 늘어난다.","c":"상","v":1},"세무사2016_53-20-5":{"f":"공적연금보험제도의 실시로 발생하는 은퇴효과는 민간저축을 증가시킨다.","w":"연금을 믿고 일찍 은퇴하면 소득이 없는 기간이 길어져 은퇴 전에 더 저축한다. 민간저축을 줄이는 쪽은 자산대체효과다.","c":"상","v":1},"세무사2016_53-39-5":{"f":"공립초등학교의 신설이 줄어들 것이다.","w":"교육바우처로 사립학교 선택이 늘면 학생이 사립으로 옮겨 가 공립 신설 수요는 줄어든다.","c":"중","v":1},"세무사2017_54-21-5":{"f":"달튼(H. Dalton)의 평등지수는 1에 가까울수록 평등한 상태를 의미한다.","w":"달튼지수는 실제 사회후생을 균등분배 때의 사회후생으로 나눈 값이라 1에 가까울수록 소득이 평등하다.","c":"상","v":1},"세무사2017_54-34-5":{"f":"셋 이상의 곡선도 동시에 비교할 수 있다.","w":"로렌츠곡선은 서로 교차하지 않으면 몇 개든 대각선에 가까운 순서로 비교할 수 있다. 교차할 때만 비교가 어렵다.","c":"상","v":1},"세무사2017_54-37-1":{"f":"연금제도는 노동공급의 감소를 가져와 경제성장을 저해할 수 있다.","w":"연금 수급에 대한 기대는 소득효과와 퇴직효과로 노동공급을 줄인다. 노동공급과 노동수요가 함께 늘어난다는 설명은 맞지 않다.","c":"중","v":1},"세무사2021_58-31-1":{"f":"국민기초생활보장제도는 기준 중위소득을 기준으로 수급 대상자를 선정한다.","w":"2015년 맞춤형 급여 개편 이후 소득인정액이 기준 중위소득의 일정 비율 이하인지로 선정하며, 상대빈곤 개념이다. 절대빈곤선(최저생계비)은 옛 기준이다.","c":"상","v":1},"세무사2021_58-33-1":{"f":"지니(Gini)계수: 0과 1 사이의 값을 가지며, 1에 가까울수록 소득이 불평등하게 분배되었음을 나타낸다.","w":"지니계수는 0이면 완전평등, 1이면 완전불평등이다.","c":"상","v":1},"세무사2021_58-33-3":{"f":"앳킨슨(A. Atkinson)지수: 0과 1 사이의 값을 가지며, 0이면 소득이 완전 평등하게 분배되었음을 나타낸다.","w":"앳킨슨지수는 1에서 균등분배대등소득/평균소득을 뺀 값이라 0~1 범위이고, 0이면 완전평등이다.","c":"상","v":1},"세무사2021_58-33-4":{"f":"5분위분배율: 상위 20 %에 속하는 사람들의 소득점유비율을 하위 20 %에 속하는 사람들의 소득점유비율로 나눈 값이다.","w":"5분위배율은 상위 20% 소득을 하위 20% 소득으로 나눈 값이라 클수록 불평등하다.","c":"상","v":1},"세무사2021_58-33-5":{"f":"십분위분배율: 하위 40 %에 속하는 사람들의 소득점유비율을 상위 20 %에 속하는 사람들의 소득점유비율로 나눈 값이다.","w":"십분위분배율은 하위 40% 소득을 상위 20% 소득으로 나눈 값이다. 완전평등이면 2이고 작을수록 불평등하다.","c":"상","v":1},"세무사2021_58-38-1":{"f":"가장 바람직한 분배 상태는 사회 전체 효용의 합을 극대화하는 원칙을 따른다.","w":"최소극대화 원칙은 롤스의 기준이다. 벤담의 공리주의는 사회 구성원 효용의 합이 가장 큰 분배를 바람직하다고 본다.","c":"중","v":1},"세무사2021_58-39-1":{"f":"인플레이션이 있는 경우 사적연금과 달리 공적연금에는 인플레이션에 조정된 연금이 지급된다.","w":"공적연금은 물가 상승에 맞춰 급여를 올릴 수 있지만, 사적연금은 정해진 명목 금액을 지급하는 것이 일반적이다.","c":"상","v":1},"세무사2022_59-33-2":{"f":"불균등한 분배가 사회후생을 떨어뜨리는 정도가 클수록 균등분배대등소득과 1인당 평균소득 간 격차는 커진다.","w":"불평등 회피 성향이 클수록 균등분배대등소득은 평균소득보다 더 낮아져 둘 사이의 격차가 커지고 앳킨슨지수도 커진다.","c":"상","v":1},"세무사2022_59-37-5":{"f":"지니계수가 커지면 소득분배의 악화로 본다.","w":"지니계수는 클수록 불평등하다.","c":"상","v":1},"세무사2023_60-32-5":{"f":"러너(A. Lerner)에 의하면 사람들의 효용함수가 서로 다르더라도 동등확률 하에서는 균등 분배가 최적이 될 수 있다.","w":"러너는 효용함수를 모르는 상태에서 누가 효용을 더 크게 얻을지 확률이 같다고 가정하면, 기대 사회후생을 극대화하는 분배가 균등분배라고 보았다.","c":"상","v":1},"세무사2023_60-33-1":{"f":"차상위계층이라 함은 소득이 기준 중위소득 50 % 이하인 가구를 말한다.","w":"차상위계층은 기초생활보장 수급자에 해당하지 않으면서 소득인정액이 기준 중위소득 50% 이하인 계층이다. 최저생계비 기준은 개편 전 방식이다.","c":"중","v":1},"세무사2023_60-33-2":{"f":"기초연금제도 운영에 필요한 재원은 조세(정부 일반회계)로 충당한다.","w":"기초연금은 보험료를 걷는 사회보험이 아니라 조세를 재원으로 하는 공공부조 성격의 급여다. 국민연금 보험료로 충당하지 않는다.","c":"상","v":1},"세무사2023_60-33-3":{"f":"국민기초생활보장제도 수급자로서 급여를 받기 위해서는 자산조사 결과 소득인정액이 기준 중위소득의 일정 비율 이하이어야 한다.","w":"급여별 선정기준은 소득인정액이 기준 중위소득의 일정 비율 이하인지다. 최저생계비 기준은 2015년 맞춤형 급여 개편으로 없어졌다. 부양의무자 기준도 교육급여·주거급여에서 폐지되었고 생계급여는 2021년 10월부터 고소득·고재산 부양의무자가 있는 경우에만 적용된다.","c":"중","v":1},"세무사2023_60-33-4":{"f":"사업장(직장)가입자의 사회보험료는 건강보험과 국민연금은 고용주와 근로자가 절반씩 분담하지만, 산재보험료는 전액 고용주가 부담하는 등 모두 절반씩 분담하는 것은 아니다.","w":"국민연금·건강보험은 노사가 반반이지만 산재보험은 사업주가 전액 내고, 고용보험은 사업주가 고용안정·직업능력개발 보험료를 추가로 낸다.","c":"상","v":1},"세무사2023_60-34-5":{"f":"동일한 재정을 투입하는 경우 일반적으로 현금보조가 현물보조에 비하여 소비자 만족도가 높다.","w":"현금은 소비자가 원하는 재화를 자유롭게 고를 수 있어 같은 금액이면 현물보다 효용이 같거나 높다.","c":"상","v":1},"세무사2023_60-35-3":{"f":"우리나라 의료보장제도는 사회보험 방식이다.","w":"우리나라는 국민건강보험을 중심으로 한 사회보험 방식이다. 국민보건서비스 방식은 영국처럼 조세로 의료를 직접 제공하는 방식이다.","c":"상","v":1},"세무사2023_60-36-3":{"f":"국민연금은 18세 이상 60세 미만으로 국내에 거주하는 국민이면 가입 대상이 된다.","w":"국민연금 가입 대상은 국내에 거주하는 18세 이상 60세 미만의 국민이다. 국외거주자는 당연가입 대상이 아니다.","c":"중","v":1},"세무사2024_61-24-1":{"f":"상품권을 받을 때 효용수준이 현금을 받을 때보다 높을 수는 없다.","w":"상품권은 사용처가 정해져 있고 현금은 어디에나 쓸 수 있다. 같은 금액이면 상품권의 선택 범위가 현금에 포함되므로 상품권의 효용이 더 높을 수 없다.","c":"중","v":1},"세무사2024_61-24-2":{"f":"현금으로 받을 때 효용수준이 같거나 더 높다.","w":"상품권 액수가 원래 소비하려던 해당 재화 지출 이하면 상품권이 제약이 되지 않아 효용이 같다. 그래서 반드시 더 높다고는 할 수 없다.","c":"중","v":1},"세무사2024_61-24-3":{"f":"가격이 달라져도 상품권을 받을 때 더 높은 효용을 얻을 수는 없다.","w":"상품권은 현금에 비해 선택 범위를 좁히기만 하므로 가격이 변해도 상품권의 효용이 현금보다 높을 수는 없다.","c":"중","v":1},"세무사2024_61-31-4":{"f":"균등분배대등소득은 사회 A가 가장 크다.","w":"앳킨슨지수는 B>C>A이므로 불평등이 가장 작은 A의 균등분배대등소득이 가장 크다.","c":"상","v":1},"세무사2024_61-32-5":{"f":"노직(R. Nozick)의 견해에 따르면 균등한 분배가 실현되더라도 절차가 정당하지 않다면 정당화될 수 없다.","w":"노직은 결과의 분배 상태가 아니라 취득과 이전의 절차가 정당한지를 기준으로 본다. 절차의 정당성은 무시될 수 없다.","c":"상","v":1},"세무사2024_61-33-3":{"f":"공리주의 사회후생함수의 경우 균등분배대등소득이 평균소득과 같다.","w":"공리주의 사회후생함수는 효용의 단순 합이라 분배 상태에 관심이 없어 균등분배대등소득이 평균소득과 같고 앳킨슨지수는 0이다.","c":"상","v":1},"세무사2024_61-35-1":{"f":"근로장려세제는 일을 하는 저소득 근로자의 생계안정과 근로유인 제공을 위한 제도이다.","w":"기초생활보장제도의 무소득 수급자가 아니라 소득이 있는 저소득 근로자를 대상으로 하는 제도다.","c":"상","v":1},"세무사2024_61-35-2":{"f":"가구의 구성원에 따라 지원혜택을 달리 운영하고 있다.","w":"근로장려금은 단독, 홑벌이, 맞벌이 가구로 나누어 지급액과 소득 상한을 다르게 정한다.","c":"상","v":1},"세무사2024_61-35-4":{"f":"근로소득이 증가함에 따라 근로장려금이 감소하는 점감구간에서의 대체효과는 노동공급을 감소시키는 방향으로 작용한다.","w":"점감구간에서는 소득이 늘면 장려금이 줄어 순임금이 낮아지므로 대체효과가 노동공급을 줄인다.","c":"상","v":1},"세무사2024_61-35-5":{"f":"암묵적 한계세율이 영(0)인 구간에서는 대체효과가 발생하지 않는다.","w":"한계세율이 0이면 일하는 시간당 순임금이 바뀌지 않아 상대가격 변화가 없고, 소득효과만 나타난다.","c":"상","v":1},"세무사2024_61-37-2":{"f":"재원을 부과방식으로 충당하면 세대 간 공평성 문제가 발생한다.","w":"적립방식은 가입자가 낸 보험료를 쌓아 자기 급여를 충당하므로 세대 간 이전이 없다. 현재 근로세대의 보험료로 현재 수급세대에게 지급하는 부과방식에서 세대 간 재분배가 생긴다.","c":"상","v":1},"세무사2024_61-38-1":{"f":"정부의 개입 정도가 국민보건서비스방식보다 약하다.","w":"사회보험방식은 보험료 중심의 운영이고, 국민보건서비스방식은 정부가 조세로 의료를 직접 공급하므로 정부 개입이 더 강하다.","c":"상","v":1},"세무사2025_62-33-5":{"f":"소득보조는 가격보조에 비하여 해당상품의 소비를 촉진하는 효과가 작다.","w":"가격보조는 해당 상품의 가격을 낮춰 대체효과와 소득효과가 모두 소비를 늘린다. 소득보조는 소득효과만 있다.","c":"상","v":1},"세무사2025_62-35-2":{"f":"공공부조는 기여 여부와 관계없이 대상자이면 혜택을 받을 수 있다.","w":"공공부조는 조세를 재원으로 하여 보험료 납부 같은 기여 없이 소득·재산 기준을 충족하면 지급한다. 기여한 사람만 받는 것은 사회보험이다.","c":"상","v":1},"세무사2025_62-35-3":{"f":"누진소득세는 조세를 이용한 대표적인 재분배정책이다.","w":"부가가치세는 단일세율이면 소득 대비 부담이 저소득층에 더 커서 역진적이다. 재분배에 쓰는 조세는 누진소득세 등이다.","c":"상","v":1},"세무사2025_62-35-4":{"f":"사회보험은 보험료를 낸 가입자가 혜택을 받을 수 있다.","w":"사회보험은 가입자가 보험료를 납부하고 보험사고가 발생할 때 급여를 받는다. 기여 여부와 무관하게 혜택을 받는 것은 공공부조다.","c":"상","v":1},"세무사2025_62-35-5":{"f":"근로장려세제는 근로에 참여한 저소득 근로자 중 소득과 재산 요건을 충족한 가구를 돕기 위한 제도이다.","w":"근로장려금은 가구의 총소득과 재산이 기준 이하인 근로자·사업자 가구에 지급한다. 근로자 모두에게 주지 않는다.","c":"상","v":1},"세무사2025_62-37-2":{"f":"가치판단이 달라지면 동일한 소득분배 상태라도 앳킨슨지수의 값이 달라진다.","w":"앳킨슨지수는 불평등 회피도(사회후생함수의 모양)를 정해 놓고 계산하므로 같은 분배도 가치판단에 따라 값이 다르다.","c":"상","v":1},"세무사2025_62-38-2":{"f":"러너(A. Lerner)는 동등확률 하에서는 효용함수가 서로 다르더라도 균등분배가 최적분배라고 하였다.","w":"러너는 효용함수 차이를 알 수 없고 확률이 같다면 기대효용을 극대화하는 분배가 균등분배라고 보았다.","c":"하","v":1},"세무사2025_62-39-3":{"f":"효용함수는 소득의 한계효용이 체감한다는 가정이 필요하다.","w":"공리주의에서 총효용을 극대화하는 분배가 균등분배가 되려면 소득이 늘수록 한계효용이 줄어야 한다. 한계효용이 불변이면 분배는 총효용에 영향을 주지 않는다.","c":"상","v":1},"세무사2026_63-31-4":{"f":"A와 B의 로렌츠곡선은 서로 교차하지 않아, 불평등도의 비교가 가능하다.","w":"하위 50%의 소득점유율이 A는 100/500=20%, B는 100/400=25%다. 두 계층뿐이라 로렌츠곡선이 한 번만 꺾이고, B의 곡선이 전 구간에서 A보다 대각선에 가까워 교차하지 않는다.","c":"상","v":1},"세무사2026_63-32-4":{"f":"러너(A. Lerner)는 동등확률 가정을 통해 사람들의 효용함수가 서로 다르더라도 균등분배가 정당화된다고 보았다.","w":"러너의 핵심은 효용함수가 다를 수 있는 불확실성 아래에서도 기대 기준으로 균등분배가 최적이 된다는 것이다. 효용함수가 모두 같아야만 성립하는 것이 아니다.","c":"하","v":1},"세무사2026_63-33-1":{"f":"지니계수는 로렌츠곡선에서 구할 수 있으며, 두 사회의 로렌츠곡선이 교차하더라도 지니계수라는 하나의 수치로 불평등도를 비교할 수 있다.","w":"로렌츠곡선은 교차하면 비교가 어렵지만, 지니계수는 곡선과 대각선 사이 면적으로 구한 값이어서 수치로 비교가 가능하다. 다만 이 비교에는 가치판단이 들어간다.","c":"중","v":1},"세무사2026_63-33-2":{"f":"달튼지수는 클수록 균등한 분배를, 5분위배율은 클수록 불균등한 분배를 의미한다.","w":"달튼지수는 1에 가까울수록 평등하고, 5분위배율은 상위 20% 소득을 하위 20% 소득으로 나눈 값이라 클수록 불평등하다.","c":"상","v":1},"세무사2026_63-33-3":{"f":"소득분배가 완전히 균등하다면 지니계수는 0, 십분위분배율은 2가 된다.","w":"십분위분배율은 하위 40% 소득점유율을 상위 20% 점유율로 나눈 값이다. 완전평등이면 40/20=2이다.","c":"상","v":1},"세무사2026_63-33-4":{"f":"달튼지수는 공리주의 사회후생함수를 가정한 것이다.","w":"달튼지수는 개인 효용의 합인 공리주의 사회후생을 균등분배일 때의 사회후생과 비교한다. 롤스의 사회후생함수에 기초하지 않는다.","c":"상","v":1},"세무사2026_63-34-1":{"f":"근로소득이 증가할수록 근로장려금이 커지는 점증구간에서의 대체효과는 노동공급을 증가시키고 소득효과는 노동공급을 감소시키는 방향으로 작용한다.","w":"점증구간에서는 일을 늘릴수록 장려금이 늘어 순임금이 오르므로 대체효과는 노동을 늘린다. 소득이 늘어난 소득효과는 여가를 늘려 노동을 줄인다.","c":"상","v":1},"세무사2026_63-35-3":{"f":"대체효과와 소득효과 모두 노동공급을 감소시키는 방향으로 작용한다.","w":"기초수당을 주고 세율을 올리면 순임금이 내려가 대체효과가 노동을 줄이고, 수당으로 소득이 늘어난 소득효과도 여가를 늘려 노동을 줄인다. 두 효과가 같은 방향이다.","c":"상","v":1},"세무사2026_63-36-1":{"f":"노동 능력의 유무와 관계없이 소득인정액이 기준 이하인 가구의 기초생활을 보장하는 제도를 국민기초생활보장제도라 한다.","w":"국민기초생활보장제도는 근로능력이 없는 사람만이 아니라 근로능력이 있는 저소득층도 대상으로 하며, 이들에게는 자활 조건이 붙는다.","c":"중","v":1},"세무사2026_63-37-1":{"f":"적립방식의 경우, 자산대체효과가 민간저축을 감소시켜도 연금기금 적립이 이를 상쇄하므로 국민저축은 감소하지 않는다.","w":"적립방식에서는 가입자의 보험료가 기금으로 쌓여 공적 저축이 늘므로 민간저축 감소분이 상쇄된다. 국민저축 감소 요인은 부과방식에서 두드러진다.","c":"중","v":1},"세무사2026_63-37-2":{"f":"부과방식의 경우, 자산대체효과는 민간저축을 감소시키는 방향으로 작용한다.","w":"부과방식에서는 연금 급여를 기대해 개인이 스스로 저축을 줄인다. 정부는 보험료를 걷어 바로 지급하므로 정부저축이 늘지 않는다.","c":"상","v":1},"세무사2026_63-37-3":{"f":"적립방식의 경우, 상속효과는 민간저축을 증가시키는 방향으로 작용한다.","w":"상속효과는 연금 때문에 자녀 세대의 부담이 커질 것을 예상한 부모 세대가 유산을 더 남기려고 저축을 늘리는 효과다.","c":"중","v":1},"세무사2026_63-37-5":{"f":"부과방식의 경우, 세대 간 소득재분배 효과가 발생한다.","w":"부과방식은 현재 근로세대의 보험료로 현재 수급세대에게 지급하므로 세대 간 재분배가 생긴다. 적립방식은 자기가 낸 보험료로 자기가 받는 구조라 세대 간 재분배가 없다.","c":"상","v":1},"세무사2026_63-20-2":{"f":"정부의 존재 이유는 개인이 아니라 사회 전체의 이익에 기여하는 데 있다.","w":"사회유기체설은 개인을 사회라는 유기체의 한 부분으로 보고 정부를 그 중심으로 본다. 정부가 오직 개인을 위해 존재한다는 설명은 개인주의의 입장이다.","c":"상","v":1},"세무사2026_63-21-1":{"f":"경쟁균형은 파레토 효율적이며, 모든 효율적 배분을 달성하려면 적절한 초기 부존의 재분배가 필요할 수 있다.","w":"후생경제학 제1정리는 경쟁균형이 효율적이라는 내용이고, 제2정리는 재분배를 통해 원하는 효율적 배분을 경쟁균형으로 달성할 수 있다는 내용이다. 모든 효율적 배분이 민간에서 자발적으로 달성되지는 않는다.","c":"상","v":1},"세무사2026_63-21-3":{"f":"파레토 효율적 배분을 경쟁균형으로 달성하려면 적절한 재분배가 필요하다.","w":"모든 파레토 효율적 배분이 곧 경쟁균형은 아니다. 초기 부존을 재분배해야 원하는 효율적 배분이 경쟁균형이 된다.","c":"상","v":1},"세무사2026_63-21-4":{"f":"모든 경쟁균형은 파레토 효율적이며, 재분배를 통해 효율적 배분을 경쟁균형으로 달성할 수 있다.","w":"후생경제학 제1정리에 따라 경쟁균형은 모두 파레토 효율적이다.","c":"상","v":1},"세무사2026_63-21-5":{"f":"효율적 배분은 경쟁균형보다 파레토 열등하지 않다.","w":"경쟁균형이 파레토 효율적이므로 이를 파레토 개선하는 배분은 없다. 효율적 배분이 경쟁균형보다 항상 열등하다는 말도 성립하지 않는다.","c":"상","v":1},"세무사2026_63-24-2":{"f":"한계비용으로 가격을 설정하는 경우, 평균비용이 한계비용보다 높아 음(-)의 경제적 이윤이 된다.","w":"자연독점 구간에서는 한계비용이 평균비용보다 작아 가격=한계비용이면 총수입이 총비용에 못 미쳐 손실이 난다.","c":"상","v":1},"세무사2026_63-24-3":{"f":"평균비용으로 가격을 설정하면 사회적으로 효율적인 생산량에 도달하지 못한다.","w":"평균비용 가격은 한계비용보다 높아 생산량이 가격=한계비용인 효율적 수준보다 적다.","c":"상","v":1},"세무사2026_63-24-4":{"f":"평균비용이 체감하는 구간에서 자연독점 현상이 발생한다.","w":"자연독점은 규모의 경제로 평균비용이 감소하는 구간에서 한 기업이 생산하는 것이 비용이 가장 작을 때 나타난다. 한계비용이 체증한다고 항상 생기지 않는다.","c":"상","v":1},"세무사2026_63-24-5":{"f":"규모의 경제하에서 자연독점으로 인한 시장실패가 발생한다.","w":"자연독점은 규모의 경제(규모에 대한 수익 체증) 때문에 생긴다. 규모의 불경제에서는 자연독점이 성립하지 않는다.","c":"상","v":1},"세무사2016_53-26-4":{"f":"독점시장에서 소비자에게 과세하는 경우 종가세와 종량세로 인한 조세수입이 같다면, 종량세의 생산량보다 종가세의 생산량이 더 많아진다.","w":"생산량이 같으면 종가세 세수가 종량세보다 많다. 그래서 세수를 같게 맞추면 종가세는 세율을 더 낮게 잡을 수 있고, 그만큼 생산량이 종량세보다 많다.","c":"상","v":1},"세무사2016_53-29-1":{"f":"노동의 수요탄력성이 무한히 클 경우 근로소득세는 근로자가 모두 부담한다.","w":"수요탄력성이 무한대면 임금이 조금만 올라도 고용주가 노동 수요를 모두 없앤다. 세금만큼 임금이 내려 근로자가 전액 부담한다.","c":"상","v":1},"세무사2016_53-29-2":{"f":"자본에 과세하는 경우 자본의 개방도가 높을수록 자본공급자의 부담은 낮아진다.","w":"개방경제에서는 자본이 세 부담이 낮은 곳으로 빠져나가므로 자본공급자는 세 부담을 피하고, 부담은 노동·토지 같은 이동이 어려운 요소로 넘어간다.","c":"상","v":1},"세무사2016_53-29-4":{"f":"토지의 공급이 비탄력적(고정)일 경우 토지에 대한 과세는 완전한 자본화를 가져온다.","w":"공급이 고정된 토지에 과세하면 토지가격이 조세의 현재가치만큼 하락해 완전한 자본화가 일어난다. 공급이 신축적이면 완전 자본화가 되지 않는다.","c":"상","v":1},"세무사2016_53-29-5":{"f":"노동의 공급탄력성이 매우 작을 경우 근로소득세는 근로자가 대부분 부담한다.","w":"공급이 비탄력적이면 임금이 내려도 노동공급이 줄지 않아 고용주가 부담을 넘기기 쉽고, 근로자가 대부분 부담한다.","c":"상","v":1},"세무사2016_53-33-3":{"f":"공공서비스로부터의 편익에 비례해 부담하더라도 무임승차 문제가 발생할 수 있다.","w":"편익원칙은 개인의 선호를 알아야 적용되는데, 값을 내지 않고 이용하려는 유인 때문에 선호를 숨겨 무임승차가 생긴다.","c":"상","v":1},"세무사2016_53-36-1":{"f":"독점적 경쟁시장의 상품에 과세한 경우, 기업이 충성고객을 확보하였을 때는 전가가 용이하다.","w":"충성고객은 가격 인상에 덜 민감해 수요가 비탄력적이므로 기업이 세금을 소비자에게 넘기기 쉽다.","c":"상","v":1},"세무사2016_53-36-2":{"f":"독점적 경쟁시장의 상품에 과세한 경우, 상품에 이질성이 높으면 전가가 용이하다.","w":"제품 차별화가 클수록 대체재가 적어 수요가 비탄력적이어서 세금을 가격에 반영하기 쉽다.","c":"상","v":1},"세무사2016_53-36-4":{"f":"완전경쟁시장 개별 기업의 상품에 과세한 경우에 비해 전가가 용이하다.","w":"완전경쟁시장의 개별 기업은 가격수용자라 자기 상품에만 과세되면 소비자에게 거의 넘기지 못한다. 독점적 경쟁기업은 가격 결정력이 있어 전가가 더 쉽다.","c":"상","v":1},"세무사2016_53-36-5":{"f":"독점적 경쟁시장의 상품에 과세한 경우, 상품에 동질성이 높으면 전가가 어렵다.","w":"동질성이 높으면 대체재가 많아 수요가 탄력적이므로 세금을 가격에 얹기 어렵다.","c":"상","v":1},"세무사2017_54-01-2":{"f":"자본화가 일어나면 조세부담은 과세 시점의 토지 소유자에게 귀착된다.","w":"토지가격이 장래 세금의 현재가치만큼 하락하므로, 하락분은 과세 시점의 기존 소유자가 진다.","c":"상","v":1},"세무사2017_54-01-3":{"f":"토지가격은 부과된 조세의 현재가치만큼 하락한다.","w":"자본화에 따른 가격 하락폭은 장래 조세부담의 현재가치와 같다. 항상 더 크게 하락하지 않는다.","c":"상","v":1},"세무사2017_54-01-4":{"f":"토지임대사용자에게는 조세부담이 귀착되지 않는다.","w":"토지공급이 고정되어 있어 임대료는 오르지 않고, 토지가격 하락으로 소유자가 부담한다.","c":"상","v":1},"세무사2017_54-01-5":{"f":"조세부과 후 토지구입자에게는 조세부담이 귀착되지 않는다.","w":"과세 후 토지를 사는 사람은 세금이 반영되어 낮아진 가격에 사므로 세 부담을 지지 않는다.","c":"상","v":1},"세무사2017_54-02-3":{"f":"정부의 재원배분 과정을 경직시켜 정부예산의 효율성을 낮출 수 있다.","w":"목적세는 세수가 정해진 용도에만 쓰이므로 재원을 필요한 곳으로 옮기기 어렵다. 예산 운용이 경직된다.","c":"상","v":1},"세무사2017_54-06-4":{"f":"균형예산귀착은 절대귀착보다 정부지출이 분배에 미치는 효과를 파악할 때 더 적합한 분석방법이다.","w":"절대귀착은 다른 조세와 지출이 변하지 않는다고 놓고 특정 조세의 효과를 보므로 지출 효과를 따지지 못한다. 지출까지 보는 것은 균형예산귀착이다.","c":"상","v":1},"세무사2017_54-08-1":{"f":"물품세의 법적 귀착과 경제적 귀착은 다를 수 있다.","w":"세금을 법적으로 내는 사람과 실제로 부담하는 사람은 수요와 공급의 탄력성에 따라 달라진다.","c":"상","v":1},"세무사2021_58-04-2":{"f":"","w":"한계효용의 소득탄력성이 1보다 크면 누진세가 된다는 것은 동등절대희생 원칙에서 쓰는 조건이다. 이 문항은 동등비례희생 원칙에서 누진세를 정당화하는 조건으로 한계효용이 감소하는 직선인 경우만 옳다고 보았다.","c":"하","v":1},"세무사2021_58-04-3":{"f":"","w":"한계효용의 소득탄력성이 1보다 작은 상수이면 동등비례희생 원칙에서 세후소득/세전소득이 모든 소득에서 같아져 비례세가 된다. 누진세를 정당화하지 못한다.","c":"상","v":1},"세무사2021_58-04-4":{"f":"","w":"한계효용이 일정하면 희생은 세액에 비례하므로, 희생 비율을 같게 하려면 모든 사람의 세액/소득이 같아야 한다. 결과는 비례세다.","c":"상","v":1},"세무사2021_58-04-5":{"f":"","w":"한계효용의 소득탄력성이 1이면 비례세가 된다는 것은 동등절대희생 원칙의 결론이다. 이 문항은 동등비례희생 원칙에서 누진세를 정당화하는 조건으로 한계효용이 감소하는 직선인 경우만 옳다고 보았다.","c":"하","v":1},"세무사2021_58-06-4":{"f":"독점시장에서는 공급곡선이 존재하지 않으므로 공급곡선의 형태로 귀착을 설명할 수 없다.","w":"독점기업은 가격수용자가 아니라 수요곡선을 보고 가격과 수량을 함께 정하므로 공급곡선이 정의되지 않는다. 귀착은 수요의 형태와 한계비용에 따라 달라진다.","c":"상","v":1},"세무사2021_58-08-2":{"f":"종량세 과세에 따른 초과부담은 600이다.","w":"거래량이 60에서 40으로 줄고 조세수입 2,400을 거래량 40으로 나누면 단위당 세액은 60이다. 초과부담은 1/2×60×20=600이다.","c":"상","v":1},"세무사2021_58-15-1":{"f":"자본화의 크기는 기간 당 할인율에 반비례한다.","w":"자본화의 크기는 매기 세액을 할인율로 나눈 값이라 할인율이 클수록 작다.","c":"상","v":1},"세무사2021_58-15-2":{"f":"세율이 높을수록 조세의 자본화 정도는 커진다.","w":"자본화의 크기는 매기 세액이 클수록 커지므로 세율이 높을수록 토지가격 하락폭이 크다.","c":"상","v":1},"세무사2021_58-15-3":{"f":"조세부담은 과세 시점의 토지소유자에게 귀착된다.","w":"자본화로 토지가격이 하락한 몫을 과세 시점의 소유자가 지고, 이후 임대사용자나 구입자는 부담하지 않는다.","c":"상","v":1},"세무사2021_58-15-4":{"f":"토지가격의 변동 폭은 부과된 조세의 현재 가치와 같다.","w":"자본화에 의한 토지가격 하락폭은 장래 조세의 현재가치와 일치한다.","c":"상","v":1},"세무사2022_59-09-1":{"f":"","w":"환경세는 오염이라는 외부효과를 바로잡으려는 교정 목적의 세금이라 효율성의 문제다. 능력이나 편익에 따라 부담을 나누는 공평과세의 사례가 아니다.","c":"중","v":1},"세무사2022_59-10-1":{"f":"세율 인상에 따른 대체효과는 탈루소득을 늘리는 방향으로 작용한다.","w":"세율이 오르면 탈루한 소득 1원당 아끼는 세금(한계편익)이 커져 탈루 유인이 커진다. 탈루소득을 줄이는 쪽은 소득효과다.","c":"상","v":1},"세무사2022_59-10-3":{"f":"","w":"알링햄-샌드모 모형은 세율, 감사확률, 벌금률과 위험기피도로 탈세 규모를 설명하고 탈세의 심리적 비용은 다루지 않는다. 심리적 비용은 이 모형 밖에서 덧붙인 논의다.","c":"중","v":1},"세무사2022_59-10-4":{"f":"탈세행위는 불법성을 특징으로 한다는 점에서 조세회피와 구별된다.","w":"조세회피(절세)는 합법적 범위에서 세 부담을 줄이는 행위이고 탈세는 불법이다. 불법성이 특징인 것은 탈세다.","c":"상","v":1},"세무사2022_59-10-5":{"f":"탈세의 편익은 세율로 표현될 수 있으며, 감사받을 확률의 증가나 벌금률의 증가는 탈루소득을 분명하게 줄인다.","w":"감사확률이나 벌금률이 오르면 탈세의 기대비용이 커져 탈루소득이 감소한다.","c":"상","v":1},"세무사2022_59-15-3":{"f":"소비자에게 귀착되는 종량세 부담은 1,500이다.","w":"시장가격이 120에서 150으로 30 오르고 거래량이 50이므로 소비자 부담은 30×50=1,500이다.","c":"상","v":1},"세무사2023_60-04-2":{"f":"독점기업에서는 공급곡선이 존재하지 않아 공급의 가격탄력성으로 귀착을 설명할 수 없다.","w":"독점기업은 공급곡선이 없어 공급의 가격탄력성이라는 개념으로 부담 크기를 판단할 수 없다.","c":"상","v":1},"세무사2023_60-04-3":{"f":"독점기업에게 부과하였더라도 9원 가운데 일부는 소비자에게 전가되어 독점기업과 소비자가 나누어 부담한다.","w":"독점기업은 세금만큼 가격을 올려도 수요가 줄어 이윤이 감소하므로 가격을 일부만 올린다. 세액 전부를 독점기업이 부담하지 않는다.","c":"상","v":1},"세무사2023_60-04-4":{"f":"독점기업에서는 공급곡선이 존재하지 않아 공급의 가격탄력성이 무한대라고 할 수 없고, 독점기업도 세금의 일부를 부담한다.","w":"독점기업은 공급곡선이 없고, 세금을 모두 소비자에게 전가할 수도 없다. 독점기업이 0원을 부담한다는 서술은 맞지 않는다.","c":"상","v":1},"세무사2023_60-04-5":{"f":"수요곡선이 직선이면 수요의 가격탄력성과 관계없이 독점기업은 9원의 절반인 4.5원을 부담한다.","w":"한계비용이 일정하고 수요곡선이 직선이면 한계수입곡선 기울기가 수요곡선의 2배여서 세금 9원이 붙을 때 가격은 4.5원 오른다. 탄력성과 관계없이 독점기업과 소비자가 4.5원씩 부담한다.","c":"상","v":1},"세무사2024_61-02-2":{"f":"편익원칙에 따를 때, 누진세를 도입하는 경우 편익의 소득탄력성이 1보다 크면 공평하다.","w":"편익이 소득보다 빠르게 늘어나는 경우에만 소득이 높은 사람이 세금을 더 높은 비율로 내는 것이 편익원칙에 맞다.","c":"상","v":1},"세무사2024_61-02-3":{"f":"납세 전후로 개인 간 효용수준의 순위가 변하지 않는 것이 바람직하다.","w":"공평한 과세는 세금을 낸 뒤에도 사람들 사이의 효용 순위가 뒤집히지 않아야 한다.","c":"상","v":1},"세무사2024_61-02-4":{"f":"수평적 공평성의 개선을 위한 정책수단으로 포괄적 소득세는 바람직하다.","w":"포괄적 소득세는 소득의 종류와 원천에 관계없이 모든 소득을 합산해 과세하므로 같은 소득이면 같은 세금을 내게 해 수평적 공평성을 높인다.","c":"상","v":1},"세무사2024_61-02-5":{"f":"소득세율의 누진성 강화는 납세자들 간의 수직적 공평성을 향상시킨다.","w":"누진성이 강해지면 소득이 높은 사람이 더 큰 비율로 부담하므로 수직적 공평성이 높아진다.","c":"상","v":1},"세무사2024_61-04-1":{"f":"수요가 탄력적일수록 정부의 조세 수입은 감소한다.","w":"수요가 탄력적이면 과세로 가격이 오를 때 거래량이 많이 줄어 조세수입이 줄어든다.","c":"상","v":1},"세무사2024_61-04-3":{"f":"단위당 세액이 커지면 정부의 조세수입이 증가하지 않을 수도 있다.","w":"세액이 일정 수준을 넘으면 거래량이 크게 줄어 조세수입이 오히려 감소할 수 있다(래퍼곡선).","c":"상","v":1},"세무사2024_61-04-4":{"f":"상대적으로 탄력성이 낮은 쪽의 조세부담이 상대적으로 커진다.","w":"가격 변화에 덜 반응하는 쪽이 거래를 포기하기 어려워 세금을 더 많이 부담한다.","c":"상","v":1},"세무사2024_61-04-5":{"f":"수요가 완전비탄력적이면 소비자가 조세 전부를 부담한다.","w":"수요가 완전비탄력적이면 가격이 올라도 소비량이 줄지 않으므로 세금만큼 가격이 오르고 소비자가 전부 부담한다.","c":"상","v":1},"세무사2024_61-10-3":{"f":"세율 상승이 소득효과와 대체효과를 발생시키며 두 효과가 반대 방향이어서 탈루소득의 변화 방향은 불확실하다고 분석하였다.","w":"세율이 오르면 대체효과는 탈루소득을 늘리고 소득효과는 탈루소득을 줄인다. 탈루소득을 더 크게 만든다고 단정할 수 없다.","c":"상","v":1},"세무사2025_62-02-2":{"f":"능력원칙은 밀(J. S. Mill)이 제시한 동등희생의 원칙이라는 재정이론에 그 근거가 있다.","w":"능력원칙의 이론적 기초는 밀 등의 희생설이고, 빅셀은 자발적 교환에 기초한 편익원칙을 제시했다.","c":"상","v":1},"세무사2025_62-02-3":{"f":"능력원칙에 따르면 상이한 경제적 능력을 가진 사람에게는 서로 다른 크기의 조세를 부과해야 한다.","w":"경제적 능력이 다른 사람에게 다른 세금을 매기는 것은 능력원칙이다. 편익원칙은 얻는 편익의 크기에 따라 부담한다.","c":"상","v":1},"세무사2025_62-02-4":{"f":"편익원칙에 따른 과세의 예로 통행료, 사용료 및 수수료가 해당된다.","w":"서비스를 이용한 만큼 부담하는 통행료·사용료·수수료가 편익원칙의 예다. 능력원칙은 지불능력에 따른다.","c":"상","v":1},"세무사2025_62-02-5":{"f":"편익원칙은 빅셀(K. Wicksell)이 제시한 자발적 교환의 재정이론에서 이념적 기초를 찾을 수 있다.","w":"자발적 교환 이론은 빅셀과 린달의 이론이다. 밀은 동등희생 원칙으로 능력원칙의 이론적 기초를 제공했다.","c":"상","v":1},"세무사2025_62-03-5":{"f":"직접세가 간접세에 비해서 소득분배의 개선에 유리하다.","w":"직접세는 누진세율을 적용하기 쉽고 납세자 특성을 반영할 수 있어 분배 개선에 유리하다. 간접세는 소득 대비 부담이 저소득층에 더 커서 역진적이다.","c":"상","v":1},"세무사2025_62-08-2":{"f":"세율인상에 따른 대체효과는 탈루소득의 한계편익이 커지기 때문에 탈루소득을 늘리는 방향으로 작용한다.","w":"세율이 오르면 탈루로 아낄 수 있는 세금이 늘어 탈루소득의 한계편익이 커진다. 줄이는 방향은 소득효과다.","c":"상","v":1},"세무사2026_63-05-1":{"f":"법인세 부담이 소비자에게 전가되었다면 전방전가(forward shifting)가 발생한 것이다.","w":"소비자에게 가격 인상으로 넘기는 것은 전방전가이고, 노동자나 원료 공급자에게 넘기는 것이 후방전가다.","c":"상","v":1},"세무사2026_63-05-2":{"f":"어떤 조세를 동일한 세수의 다른 조세로 대체할 때 어떤 분배효과가 나오는가를 분석하는 것을 차별귀착이라 부른다.","w":"균형예산귀착은 조세와 그 세수를 쓰는 지출까지 함께 고려하는 분석이다. 세수를 같게 두고 조세만 바꿔 비교하는 것은 차별귀착이다.","c":"상","v":1},"세무사2026_63-05-4":{"f":"독점시장에서는 공급곡선이 존재하지 않아 공급곡선의 탄력성으로 귀착을 설명할 수 없다.","w":"독점기업은 수요곡선을 보고 가격과 수량을 정하므로 공급곡선이 없다. 귀착은 수요의 탄력성과 한계비용에 달려 있다.","c":"상","v":1},"세무사2026_63-05-5":{"f":"독점시장의 경우 수요의 가격탄력성이 작을수록 소비자 부담이 커진다.","w":"수요가 비탄력적이면 가격을 올려도 판매량이 크게 줄지 않아 독점기업이 세금을 가격에 얹기 쉽고 소비자 부담이 커진다.","c":"중","v":1},"세무사2017_54-16-2":{"f":"시장의 기능이 자연적으로 축소되는 것이 원인은 아니다.","w":"정부지출이 소득보다 빠르게 늘어나는 이유는 공공서비스 수요의 소득탄력성이 크고, 관료가 예산을 극대화하려 하며, 공공부문의 생산성 향상이 더딘 데 있다.","c":"상","v":1},"세무사2021_58-32-1":{"f":"리카르도(D. Ricardo)는 총수요를 변화시키지 못한다고 하였다.","w":"리카르도 대등정리는 국채로 감세를 해도 사람들이 장래 세금 증가를 예상해 저축을 늘리므로 총수요가 변하지 않는다는 내용이다.","c":"상","v":1},"세무사2021_58-32-2":{"f":"러너(A. Lerner)는 내부채무는 미래세대의 부담을 증가시키지 않는다고 하였다.","w":"내부채무는 같은 국민 안에서 채무자와 채권자가 함께 있어 미래세대 전체로는 부담이 늘지 않는다. 외부채무는 부담이 전가된다.","c":"상","v":1},"세무사2021_58-32-3":{"f":"통화주의자들은 구축효과 때문에 총수요가 변하지 않는다고 하였다.","w":"통화주의자는 국채 발행으로 이자율이 올라 민간 투자와 소비가 밀려나므로 총수요가 거의 변하지 않는다고 본다.","c":"상","v":1},"세무사2021_58-32-5":{"f":"케인즈학파는 국채발행을 통해 조세부담을 경감시켜주면 총수요가 증가한다고 하였다.","w":"케인즈학파는 감세로 가처분소득이 늘면 소비가 늘어 총수요가 증가한다고 본다.","c":"상","v":1},"세무사2021_58-35-4":{"f":"구축 효과가 없다는 가정 하에 세금 감면액과 정부 지출 증가액이 동일한 크기라면 정부 지출 증가의 총수요 효과가 더 크다.","w":"정부 지출 승수는 1/(1-c)이고 조세 승수는 c/(1-c)로 정부 지출 승수가 더 크다. 감세액의 일부는 저축되기 때문이다.","c":"상","v":1},"세무사2022_59-13-3":{"f":"남북협력기업에 대한 보조금 지급은 재정지출에 해당한다.","w":"조세지출은 세금 감면·공제처럼 정부가 걷지 않는 세수를 말한다. 보조금은 직접 지급하는 재정지출이다.","c":"상","v":1},"세무사2022_59-38-2":{"f":"피코크-와이즈만(A. Peacock & J. Wiseman): 사회적 격변기에 전위효과(displacement effect)의 영향으로 정부지출이 팽창된다고 보았다.","w":"전위효과는 피코크-와이즈만의 이론이다. 보몰은 노동집약적인 공공부문의 생산성이 낮아 비용이 상대적으로 상승한다는 비용질병을 말했다.","c":"상","v":1},"세무사2022_59-38-3":{"f":"보몰(W. Baumol): 노동집약적인 공공부문이 민간부문보다 생산성 향상이 느리기 때문에 정부지출이 팽창된다고 주장하였다.","w":"공공부문의 생산성 향상이 느려 비용이 상대적으로 오른다는 주장은 보몰효과다. 피코크-와이즈만은 전쟁 같은 사회적 격변기의 전위효과를 설명했다.","c":"상","v":1},"세무사2022_59-38-4":{"f":"부캐넌(J. Buchanan): 정부지출의 편익이 직접적으로 인식되는 반면, 공공서비스의 공급비용은 과소평가되므로 정부지출이 팽창된다고 설명하였다.","w":"재정착각 논의에서 주민은 지출의 혜택은 분명히 느끼지만 조세부담은 간접세 등으로 인해 낮게 인식하므로 정부지출이 팽창된다.","c":"중","v":1},"세무사2022_59-38-5":{"f":"바그너의 법칙: 1인당 국민소득 증가 국면에서 공공부문의 상대적 크기가 증가하는 것을 말한다.","w":"바그너의 법칙은 1인당 소득이 늘수록 국민소득에서 공공부문이 차지하는 비중이 커진다는 경험적 법칙이다.","c":"상","v":1},"세무사2023_60-15-1":{"f":"통화주의학파는 국채발행이 구축효과를 가져와서 총수요가 증가하지 않는다고 하였다.","w":"통화주의는 국채 발행으로 이자율이 오르고 민간 지출이 줄어 재정지출 증가 효과가 상쇄된다고 본다.","c":"상","v":1},"세무사2023_60-15-2":{"f":"케인즈학파는 국채발행을 통해 조세부담을 경감시키면 총수요가 증가한다고 하였다.","w":"감세로 가처분소득이 늘면 소비가 늘어 총수요가 늘어난다는 것이 케인즈학파의 입장이다.","c":"상","v":1},"세무사2023_60-15-3":{"f":"리카르도(D. Ricardo)는 재정적자를 국채로 충당하더라도 총수요에 영향이 없다고 하였다.","w":"리카르도 대등정리는 국채 발행은 미래 조세의 연기일 뿐이라 합리적 경제주체가 저축을 늘려 총수요가 변하지 않는다고 본다.","c":"상","v":1},"세무사2023_60-15-5":{"f":"러너(A. Lerner)는 외부채무는 미래세대의 부담을 증가시킨다고 하였다.","w":"외부채무는 미래세대가 해외에 원리금을 갚아야 하므로 부담이 전가된다. 내부채무는 부담이 늘지 않는다.","c":"상","v":1},"세무사2023_60-38-1":{"f":"바그너(A. Wagner)법칙에 의하면, 1인당 소득이 증가할 때 국민소득에서 차지하는 공공부문은 민간부문보다 빠르게 성장한다.","w":"바그너의 법칙은 공공부문이 소득 증가율을 웃도는 속도로 커진다는 내용이다. 민간부문에 비례해 자란다는 설명은 맞지 않는다.","c":"상","v":1},"세무사2023_60-38-2":{"f":"보몰효과(Baumol effect)에 의하면, 정부가 생산·공급하는 서비스의 생산비용이 상대적으로 높아지면 정부지출이 증가하게 된다.","w":"공공서비스는 노동집약적이어서 생산성 향상이 더뎌 상대 비용이 올라간다. 비용이 상대적으로 낮아져서 지출이 늘어난다는 설명이 아니다.","c":"상","v":1},"세무사2023_60-38-3":{"f":"부캐넌(J. Buchanan)은 현대의 대의민주체제가 본질적으로 정부부문의 팽창을 초래한다는 리바이어던가설(Leviathan hypothesis)을 제기하였다.","w":"리바이어던가설은 정부가 세수를 극대화하려 해 정부부문이 계속 팽창한다는 가설이다. 정부 팽창을 억제한다는 내용이 아니다.","c":"상","v":1},"세무사2023_60-38-5":{"f":"브라운-잭슨(C. Brown & P. Jackson)에 의하면, 중위투표자의 공공서비스에 대한 수요의 소득탄력성이 커지게 되면 정부지출의 비중이 증가하게 된다.","w":"중위투표자의 수요 소득탄력성이 클수록 소득 증가에 따라 공공서비스 수요가 빠르게 늘어 정부지출 비중이 커진다.","c":"상","v":1},"세무사2024_61-15-2":{"f":"국채발행으로 이자율이 상승하는데, 이로 인해 자본유입이 발생하면 환율이 평가절상되어 경상수지가 악화된다.","w":"이자율 상승으로 해외 자본이 들어오면 원화 가치가 올라 환율(원/달러)이 하락하고 수출은 줄고 수입은 늘어 경상수지가 나빠진다.","c":"상","v":1},"세무사2024_61-21-2":{"f":"시차문제에 있어서 자동안정장치(built-in stabilizer)가 재량적 재정정책(discretionary fiscal policy)에 비해 나은 정책수단이다.","w":"자동안정장치는 경기 변동에 맞춰 즉시 작동해 인식시차와 실행시차가 거의 없다. 재량적 정책은 결정과 집행에 시간이 걸린다.","c":"상","v":1},"세무사2024_61-39-5":{"f":"브라운-잭슨(C. Brown and P. Jackson)은 중위투표자의 공공서비스에 대한 소득탄력성이 크게 되면 정부지출이 증가한다는 중위투표자 모형을 제시하였다.","w":"리바이어던가설은 부캐넌의 가설이다. 브라운-잭슨은 바그너의 법칙을 중위투표자의 선택으로 설명했다.","c":"상","v":1},"세무사2025_62-15-4":{"f":"이자율 상승은 국채의 시장가치를 하락시켜 정부부채를 감소시키는 효과가 있다.","w":"국채 가격은 이자율과 반대로 움직인다. 이자율이 하락하면 국채의 시장가치가 올라 정부부채의 시장가치가 늘어난다.","c":"상","v":1},"세무사2025_62-20-1":{"f":"가처분 소득이 늘어나고 화폐 수요가 증가한다.","w":"감세로 가처분소득이 늘면 거래용 화폐 수요가 늘어난다.","c":"상","v":1},"세무사2025_62-20-2":{"f":"소비 지출이 증가하여 총수요 곡선이 우측으로 이동한다.","w":"감세로 소비가 늘어 총수요가 증가하므로 총수요곡선이 오른쪽으로 이동한다.","c":"상","v":1},"세무사2025_62-20-3":{"f":"국내외 연구결과에 의하면 감세정책이 국민저축을 대폭 증대시키는 효과는 확인되지 않았다.","w":"감세는 민간저축을 일부 늘릴 수 있어도 재정적자로 정부저축이 줄어 국민저축이 크게 늘지 않았다는 연구가 많다.","c":"중","v":1},"세무사2025_62-20-4":{"f":"구축효과가 없다는 가정 하에 세금 감면과 정부 지출 증가의 금액이 동일한 크기라면 정부 지출 증가의 총수요 효과가 더 크다.","w":"정부 지출은 전액이 수요가 되지만 감세는 일부가 저축으로 빠져 정부 지출 승수가 조세 승수보다 크다.","c":"상","v":1},"세무사2026_63-17-3":{"f":"민간 보유 국채 잔액이 증가함에 따라 소비지출이 증가하는 현상을 러너(Lerner)효과라 부른다.","w":"러너효과는 국채를 가진 민간이 이를 자산으로 여겨 부유해졌다고 느끼고 소비를 늘리는 현상이다. 소비지출은 감소가 아니라 증가한다.","c":"상","v":1},"세무사2026_63-38-1":{"f":"품목별예산제도는 비슷한 일을 하는 부서 사이의 중복을 차단하기 어렵다.","w":"품목별예산은 지출 항목별로 통제하는 제도여서 사업 단위의 중복을 파악하기 어렵다. 중복 차단은 프로그램예산의 장점이다.","c":"상","v":1},"세무사2026_63-38-2":{"f":"성과주의예산제도는 사업의 성과(산출)를 중심으로 예산을 편성한다.","w":"투입요소 중심으로 편성하는 것은 품목별예산이다. 성과주의예산은 사업별 단위원가와 업무량을 기준으로 한다.","c":"상","v":1},"세무사2026_63-38-3":{"f":"영기준예산제도는 시간과 비용이 많이 든다는 단점이 있다.","w":"매년 모든 사업을 처음부터 다시 평가하므로 시간과 노력이 많이 들고 업무 부담이 크다.","c":"상","v":1},"세무사2026_63-38-4":{"f":"프로그램예산제도는 계획기능을 강조한 제도이다.","w":"프로그램예산제도는 정책 목표 아래 사업을 묶어 예산을 짜고 성과와 연계해 재원을 배분하는 제도로, 기획(계획) 기능을 강조한다. 관리기능을 강조한 것은 성과주의예산제도다.","c":"중","v":1},"세무사2026_63-39-5":{"f":"보몰효과(Baumol effect)에 의하면, 정부가 생산ㆍ공급하는 서비스의 생산비용이 상대적으로 빠르게 증가하여 정부지출이 늘어나게 된다.","w":"공공서비스의 상대비용이 빠르게 오른다는 설명은 보몰효과다. 뷰캐넌의 리바이어던가설은 정부가 세수를 극대화하려 팽창한다는 내용이다.","c":"상","v":1},"세무사2017_54-30-1":{"f":"공공재에 대한 수요는 고소득자가 저소득자보다 크다.","w":"효용함수가 같고 공공재가 정상재이므로 소득이 많은 사람일수록 공공재 수요가 크다.","c":"상","v":1},"세무사2017_54-30-2":{"f":"단순다수결투표로 정해지는 공공재 공급수준은 효율적이지 않을 수 있다.","w":"중위투표자의 선호가 공급을 결정하므로 개인별 한계편익의 합이 한계비용과 같아지는 효율적 수준과 일치한다는 보장이 없다.","c":"상","v":1},"세무사2017_54-30-3":{"f":"중위투표자의 소득을 높이는 소득 재분배 후 단순다수결투표를 한다면 공공재의 수요량은 많아질 것이다.","w":"공공재가 정상재이면 중위투표자의 소득이 오를 때 선호하는 공급량이 늘어난다.","c":"상","v":1},"세무사2017_54-30-5":{"f":"해당 공공재에 대해 대체관계가 있는 사적재가 존재하더라도 단순다수결투표의 균형이 성립할 수 있다.","w":"대체 관계의 사적재가 있으면 일부 투표자의 선호가 다봉형이 되어 균형이 깨질 수 있지만 항상 그런 것은 아니다. 선호가 단봉형으로 남으면 중위투표자 균형이 성립한다.","c":"중","v":1},"세무사2021_58-27-1":{"f":"양당제를 운영하고 있는 국가에서 정치적 성향이 대치되는 두 정당의 선거 공약이 비슷해지는 것과 관련이 있다.","w":"중위투표자 정리에 따르면 두 정당은 표를 얻으려고 중위투표자의 선호에 맞춰 공약을 수렴시킨다. 차별화되지 않는다.","c":"상","v":1},"세무사2022_59-28-5":{"f":"점수투표제에서 투표거래(logrolling)가 발생해도 선호의 강도가 반영될 수 있다.","w":"투표거래는 강하게 원하는 안건에 표를 몰아주고 다른 안건에서 양보하는 방식이라 선호의 강도를 반영한다.","c":"중","v":1},"세무사2022_59-30-2":{"f":"생산 수준이 미그-빌레인저(Migue-Belanger) 모형에서 제시한 수준보다 더 크다.","w":"니스카넨 모형에서는 관료가 총편익과 총비용이 같아지는 수준까지 생산해 가장 크고, 미그-빌레인저 모형은 관료가 재량 예산을 가져 그보다 적게 생산한다.","c":"상","v":1},"세무사2025_62-27-1":{"f":"중위투표자 정리의 정치적 균형은 파레토 효율성을 보장하지 않는다.","w":"다수결로 정해진 공급량은 중위투표자의 선호일 뿐이어서 개인별 한계편익의 합이 한계비용과 같은 효율적 수준과 다를 수 있다.","c":"상","v":1},"세무사2025_62-29-1":{"f":"니스카넨 모형에서 관료는 가격순응자가 아니라 독점적 공급자이다.","w":"니스카넨 모형의 관료는 의회에 서비스를 독점적으로 공급하며 예산을 극대화하려는 존재다.","c":"중","v":1},"세무사2025_62-29-2":{"f":"두 모형에서 관료는 예산의 극대화를 추구하는 존재이다.","w":"니스카넨 모형은 관료가 예산 극대화를, 미그-빌레인저 모형은 재량적 예산 극대화를 추구한다고 본다. 공익을 극대화하는 존재로 보지 않는다.","c":"상","v":1},"세무사2025_62-29-4":{"f":"다른 조건이 모두 동일할 때, 니스카넨 모형의 공공재 생산량은 미그-빌레인저 모형의 생산량보다 많다.","w":"니스카넨 모형은 총편익과 총비용이 일치하는 곳까지 생산하고, 미그-빌레인저 모형은 재량 예산 몫이 있어 생산량이 그보다 적다.","c":"상","v":1},"세무사2025_62-29-5":{"f":"니스카넨 모형에서 관료는 예산집행으로 인한 편익과 비용이 일치하는 점에서 생산하려 한다.","w":"니스카넨 모형의 관료는 순편익이 가장 큰 점이 아니라 총편익과 총비용이 같아 사회적 잉여가 0이 되는 점까지 생산한다.","c":"상","v":1},"세무사2016_53-18-4":{"f":"파레토최적 배분상태는 효용가능경계곡선 상에 무수히 많이 나타난다.","w":"효용가능경계 위의 점은 모두 한 사람의 효용을 줄여야만 다른 사람의 효용을 늘릴 수 있는 파레토 효율 상태다. 효율적인 배분은 분배에 따라 무수히 많다.","c":"상","v":1},"세무사2017_54-23-1":{"f":"사회후생함수는 그 사회가 선택한 가치 기준을 반영하여 나타낸 함수이다.","w":"사회후생함수는 사회가 정한 가치판단을 담아 표현할 뿐, 어떤 가치 기준을 선택해야 하는지에 대한 답은 주지 않는다.","c":"상","v":1},"세무사2021_58-24-3":{"f":"평등주의 사회후생함수는 효용이 낮은 개인의 효용에 더 큰 가중치를 부여하게 된다.","w":"각 개인의 효용에 동일한 가중치를 주는 것은 공리주의 사회후생함수다. 평등주의는 효용이 낮은 사람에게 높은 가중치를 준다.","c":"상","v":1},"세무사2021_58-26-5":{"f":"외부불경제로 사회적 최적생산량보다 과다 생산되는 경우에 발생한다.","w":"외부불경제가 있으면 사적 비용이 사회적 비용보다 작아 시장 생산량이 최적 수준을 넘는다. 과소 생산되는 것은 외부경제의 경우다.","c":"상","v":1},"세무사2022_59-21-3":{"f":"어떤 자원배분 상태에 파레토개선의 여지가 있다면 그 상태는 비효율적이다.","w":"파레토 개선이 가능하다는 것은 누구도 손해 보지 않으면서 누군가를 더 낫게 할 수 있다는 뜻이므로 효율적인 상태가 아니다.","c":"상","v":1},"세무사2022_59-22-5":{"f":"평등주의적 사회후생함수는 효용이 낮은 구성원에게 더 큰 가중치를 부여한다.","w":"모든 구성원에게 같은 가중치를 주는 것은 공리주의 사회후생함수다. 평등주의적 함수는 낮은 효용을 가진 사람의 효용에 더 큰 가중치를 둔다.","c":"상","v":1},"세무사2022_59-23-1":{"f":"국민연금의 강제 가입은 일찍 은퇴할 가능성이 높은 사람만 가입하는 역선택 문제를 해결할 수 있다.","w":"임의가입이면 연금을 오래 받게 될 사람, 곧 일찍 은퇴할 사람이 주로 가입하는 역선택이 생긴다. 강제 가입은 늦게 은퇴할 사람까지 모두 가입시켜 이 문제를 해결한다.","c":"상","v":1},"세무사2022_59-36-1":{"f":"롤즈(J. Rawls)적 가치판단에 기초한 사회무차별곡선은 L자 모양으로 표시된다.","w":"롤스의 사회후생함수는 효용이 가장 낮은 사람의 효용만 따지므로 사회무차별곡선이 직각으로 꺾인 L자 모양이다. 우하향하는 직선은 공리주의다.","c":"상","v":1},"세무사2024_61-20-5":{"f":"램지(F. Ramsey)가 제시한 최적조세이론은 사회후생을 극대화하는 조세구조에 관한 이론이다.","w":"최적조세이론은 효율성과 형평성을 고려해 사회후생이 가장 높은 조세구조를 찾는 이론이다. 조세수입 극대화가 목적이 아니며 케인즈의 이론도 아니다.","c":"중","v":1},"세무사2024_61-25-1":{"f":"","w":"CCTV로 직원의 업무 태도를 확인하는 것은 계약 뒤의 행동을 감시하는 모니터링으로, 도덕적 해이에 대한 대응이다. 나머지 선지는 숨겨진 특성을 드러내는 신호·선별이나 강제 가입으로 역선택에 대응한다.","c":"중","v":1},"세무사2025_62-22-4":{"f":"외부효과로 인한 비효율성은 교정세(피구세) 부과를 통해 해결할 수 있다.","w":"중립세는 민간의 의사결정을 왜곡하지 않는 세금이라 외부효과를 교정하지 못한다. 외부효과는 피구세나 보조금 같은 교정수단이 필요하다.","c":"상","v":1},"세무사2025_62-23-3":{"f":"비용체감산업에 대한 평균비용 가격설정은 독점으로 인한 비효율성을 완전히 제거하지 못한다.","w":"평균비용 가격은 한계비용보다 높아 여전히 과소생산이 남는다. 한계비용 가격설정이 효율적이지만 손실이 생긴다.","c":"상","v":1},"세무사2025_62-26-5":{"f":"공리주의적 사회후생함수에 의하면 소득의 한계효용이 감소할 때 사회후생의 극대화를 위해서는 각 개인소득의 한계효용이 서로 같아야 한다.","w":"소득의 한계효용이 개인 사이에 다르면 한계효용이 큰 사람에게 소득을 옮겨 사회후생을 더 늘릴 수 있다. 극대화 상태에서는 한계효용이 같다.","c":"상","v":1},"세무사2021_58-03-5":{"f":"어떤 재화의 시장에서 공급곡선이 수평이고 수요곡선이 우하향하며 직선인 경우 재화의 초기 균형가격은 {P_{1}}, 물품세의 세율은 t, 물품세 과세 이전과 이후의 균형 소비량(산출량)은 각각 {Q_{1}} 과 {Q_{2}}, 그리고 보상수요의 가격탄력성을 e로 나타내면 물품세의 과세로 인한 초과부담은 { {1} over {2} e(P_{1} Q_{1}) t^{2} } 이 된다.","w":"공급이 수평이면 소비자가격이 P₁에서 (1+t)P₁로 오르고 소비량 감소분은 ΔQ = e·Q₁·t다. 초과부담은 삼각형 넓이 ½·tP₁·ΔQ = ½·e·P₁Q₁·t²로, 과세 전 소비량 Q₁을 쓴다.","c":"상","v":1},"세무사2021_58-12-3":{"f":"다른 조건이 일정할 때, t가 인하되면 보조금은 늘어난다.","w":"보조금은 a − tE로 소득 E가 늘 때 t만큼씩 줄어든다. t를 내리면 같은 소득에서 깎이는 금액이 작아져 보조금이 늘고, 보조금을 받는 소득 구간(E < a/t)도 넓어진다.","c":"상","v":1},"세무사2026_63-28-1":{"f":"꽁도세 승자는 a, 보다 승자는 b이다.","w":"양자 대결에서 a는 b·c·d를 각각 6 대 4로 이기므로 꽁도세 승자는 a다. 보다 점수(1위 3점~4위 0점)는 a 18점, b 24점, c 11점, d 7점이어서 보다 승자는 b다.","c":"상","v":1},"세무사2026_63-28-2":{"f":"꽁도세 승자는 a, 보다 승자는 b이다.","w":"a는 A·B 유형 6명의 지지로 b·c·d를 각각 6 대 4로 이기므로 꽁도세 승자는 a다. 보다 점수는 a 18점, b 24점으로 b가 가장 높다.","c":"상","v":1},"세무사2026_63-28-4":{"f":"꽁도세 승자는 a, 보다 승자는 b이다.","w":"양자 대결에서 b는 a에게 4 대 6으로 지므로 꽁도세 승자가 될 수 없고, 꽁도세 승자는 a다. 보다 점수는 b 24점, a 18점으로 보다 승자는 b다.","c":"상","v":1},"세무사2026_63-28-5":{"f":"꽁도세 승자는 a, 보다 승자는 b이다.","w":"a는 다른 세 대안을 모두 6 대 4로 이기므로 꽁도세 승자가 존재한다. 보다 점수는 a 18점, b 24점, c 11점, d 7점이어서 보다 승자는 b다.","c":"상","v":1},"세무사2024_61-13-4":{"f":"여가가 정상재라면, 대체효과가 소득효과보다 클 경우 노동공급은 감소한다.","w":"근로소득세로 세후 임금이 내리면 대체효과는 여가를 늘려 노동을 줄이고, 여가가 정상재일 때 소득효과는 여가를 줄여 노동을 늘린다. 대체효과가 더 크면 노동공급은 감소한다.","c":"상","v":1},"세무사2016_53-01":{"w":"대기오염 같은 음(-)의 외부성은 오염을 일으키는 기업의 제품에 과세해 사적 비용에 외부 피해를 반영하는 피구세로 해결한다. 소비세·누진세·취득세·법인세는 외부성 교정과 관계가 없다.","c":"상","v":1},"세무사2016_53-23":{"w":"B의 비용에 X가 들어 있으므로 A의 생산 X가 B에 비용을 주는 음의 외부성이다. 외부성을 일으키는 쪽은 A이므로 환경세는 A(X재 생산)에 부과해야 하고, B에 부과하면 교정되지 않는다.\n신규시장 개설(배출권), 합병, 코즈 협상, 수량규제는 모두 효율적 배분 수단이다.","c":"상","v":1},"세무사2021_58-36":{"w":"푸드 스탬프는 저소득층에 식품 구입을 지원하는 소득재분배 제도로 외부효과 내부화와 무관하다. 피구세·오염 배출권·환경 투자 보조금·거래 가능 어획 쿼터는 가격이나 거래시장을 통해 외부효과를 내부화한다.","c":"상","v":1},"세무사2021_58-37":{"w":"사회적 한계비용 SMC = PMC + MD = 6Q + 2Q = 8Q.\n사회적 최적: PMB = SMC → 600 - 4Q = 8Q → Q = 50.\n피구세는 최적 생산량에서의 한계 외부피해이므로 MD = 2 × 50 = 100.","c":"상","v":1},"세무사2022_59-24":{"w":"저감의 한계비용: A는 q_A, B는 2q_B. 총 배출 1,000에서 30%를 줄이므로 총 저감량은 300.\n균형: q_A = 2q_B, q_A + q_B = 300 → q_B = 100, q_A = 200. 배출권 가격 = 한계저감비용 = 200.\nA의 할당량 400은 배출 100만큼 줄이는 몫인데 실제로는 200을 줄이므로 배출권 100을 팔고, B는 100을 산다. 거래량 100.","c":"상","v":1},"세무사2023_60-24":{"w":"사회적 한계편익 = 사적 편익 + 외부 편익. 수요 P = 5 - Q/2, 외부한계편익 P = 2.5 - Q/2이므로 SMB = 7.5 - Q.\nSMB = MC: 7.5 - Q = 4 → Q = 3.5.","c":"상","v":1},"세무사2024_61-29":{"w":"SMB = (150 - Q) + (30 - Q/4) = 180 - 1.25Q. 사회적 최적은 SMB = PMC: 180 - 1.25Q = Q → Q = 80.\n보조금 s를 받으면 생산자 한계비용은 Q - s이고, 균형 150 - Q = Q - s에 Q = 80을 넣으면 70 = 80 - s → s = 10.","c":"상","v":1},"세무사2025_62-28":{"w":"SMC = PMC + MD이므로 PMC = 6Q - 2Q = 4Q.\n사회적 최적: PMB = SMC → 600 - 4Q = 6Q → Q = 60.\n피구세 = 최적 생산량에서의 MD = 2 × 60 = 120.","c":"상","v":1},"세무사2026_63-30":{"w":"효율적 생산량: MB = MD → 120 - Q = Q/2 → Q = 80.\n배출권리가 공장에 있으면 공장은 MB = 0인 Q = 120까지 생산하려 한다. 80으로 줄이는 대가로 공장이 포기하는 편익은 Q 80~120 구간의 MB 면적 = 1/2 × 40 × 40 = 800.\n피해자가 줄어드는 피해(2,000)만큼 이익을 보므로 800을 제시할 수 있고, 공장이 받아들이는 최소 금액이 800이다.","c":"상","v":1},"세무사2016_53-02":{"w":"ㄱ 간이과세 적용요건 완화는 납부면제 대상을 늘려 면세자 비율을 높인다. ㄷ 인적공제 확대와 ㄹ 연금저축 공제 확대도 과세최저한 이하 소득자를 늘려 면세자 비율을 높인다.\nㄴ 면세점을 명목금액으로 유지하면 물가·소득 상승으로 면세자가 줄어드므로 옳은 방안이다.\n따라서 옳지 않은 것은 ㄱ, ㄷ, ㄹ.","c":"중","v":1},"세무사2016_53-08":{"w":"표의 소득형태별 점유율은 노동소득 86.0%, 자산소득 3.0%, 기타소득 11.0%이다. 세수를 극대화하려면 과세표준이 큰 노동소득에 과세해야 하며, 자산·기타소득은 합쳐도 14%라 효과가 작다. ①이 옳지 않다.\n②는 자산소득의 96.9%가 상위, ③은 노동소득 86%, ④·⑤는 분배·효율 해석으로 옳다.","c":"상","v":1},"세무사2016_53-14":{"w":"T = 0.3Y - 300 형태이며 한계세율은 0.3으로 일정하고 평균세율은 0.3 - 300/Y로 소득이 늘수록 올라 0.3에 접근하므로 누진세이다(Y > 1,000). ①, ②, ⑤는 옳다.\n주어진 식은 소득에서 1,000을 먼저 빼는 소득공제 구조이므로 ③ 소득공제액 1,000은 옳고, 세액공제액 300이라는 ④가 옳지 않다.","c":"중","v":1},"세무사2016_53-15":{"w":"소득공제 때 혜택은 400만원 × 한계세율: 저 20만, 중 60만, 고 120만. 세액공제 10%로 바꾸면 모든 계층이 40만으로 같다.\n저소득층은 늘고 중소득층은 줄고, 고소득층은 120만에서 40만으로 가장 크게 줄어 ④가 옳다. 공제한도(400만원) 때문에 저축이 한도를 넘으면 혜택이 같아지므로 ③은 '저축금액에 관계없이'가 틀리고, 저소득층 혜택이 늘어 ②·⑤도 틀리다.","c":"중","v":1},"세무사2017_54-03":{"w":"T = -300 + 0.5Y에서 한계세율은 0.5로 일정, 평균세율 = 0.5 - 300/Y는 소득이 늘면 올라가며 항상 0.5보다 작다.\n세수탄력성 = 한계세율/평균세율 = 0.5/(0.5 - 300/Y) > 1이다. ③이 옳지 않다.","c":"상","v":1},"세무사2017_54-04":{"w":"비례세는 명목소득과 물가가 같은 비율로 오르면 실질소득이 그대로이고 세율도 같아 실질세액이 변하지 않는다. 누진세는 명목소득 증가로 더 높은 세율구간에 들어가 평균세율이 올라가므로 실질세액이 증가한다(bracket creep).","c":"상","v":1},"세무사2017_54-05":{"w":"한계세율과 평균세율이 같으면 세율이 소득과 관계없이 일정한 비례세이다. 면세점이 있는 선형조세, 한계세율 증가, 세수탄력성 1 초과, 한계세율 일정·평균세율 증가는 모두 평균세율이 소득에 따라 오르는 누진세이다.","c":"상","v":1},"세무사2017_54-13":{"w":"ㄱ. 구간 (1)·(2) 소득자는 구간 (3)에 해당하는 소득이 없어 세액이 그대로이고 구간 (3) 소득자는 세액이 늘어 평균세율이 오른다. 내려가는 사람은 없다. X\nㄴ. 구간 (4)~(6) 소득자는 한계세율(35~40%)이 그대로라 대체효과는 생기지 않는다. 다만 구간 (3) 몫의 세액이 4,200만원 × 6%p = 252만원 늘어 세후소득이 줄고 소득효과로 노동공급 선택이 달라진다. 확정답안은 이를 노동공급 선택의 왜곡으로 보아 옳은 진술로 처리했다. O\nㄷ. 같은 이유로 이들의 세액이 252만원씩 늘어 평균세율이 오른다. O\n옳은 것은 ㄴ, ㄷ이다.","c":"중","v":1},"세무사2017_54-19":{"w":"A 첫해 전액 감가상각(즉시상각)은 세부담을 앞당겨 줄여 자본의 사용자 비용을 낮추므로 투자를 촉진한다.\nB 이자비용 손금 부인은 차입 비용에 대한 세 절감이 없어져 세후 자금조달 비용이 오르므로 투자를 위축시킨다.","c":"상","v":1},"세무사2017_54-38":{"w":"세후 명목이자율 = 5% × (1 - 0.2) = 4%. 납세 후 실질수익률 = 4% - 3% = 1%.","c":"상","v":1},"세무사2021_58-07":{"w":"과세소득 180: 0~100에 10% = 10, 100~180에 20% = 16 → 세액 26.\n한계세율은 마지막 구간 20%. 실효세율은 총소득 기준 26/240 ≈ 10.8%.","c":"상","v":1},"세무사2021_58-11":{"w":"완전통합은 법인세를 따로 두지 않고 법인소득 전체를 주주 소득으로 과세하는 방식으로 조합방식(partnership method)과 자본이득방식이 해당한다. 법인방식, 귀속제도, 차등세율제도, 배당세액공제제도는 부분통합이다.","c":"상","v":1},"세무사2022_59-02":{"w":"T = -400 + 0.5Y에서 평균세율 0.5 - 400/Y는 소득이 늘면 증가(ㄱ O), 한계세율 0.5는 일정(ㄴ O).\n세수탄력성 = 0.5/(0.5 - 400/Y) > 1이므로 ㄷ X, 한계세율 0.5 > 평균세율이므로 ㄹ X.","c":"상","v":1},"세무사2022_59-11":{"w":"개인기준 세액은 A부부 500만 + 3,500만 = 4,000만, B부부 2,000만 + 2,000만 = 4,000만이다. 가족기준에서는 합산소득 2억원에 대해 5,000만 × 10% + 1.5억 × 30% = 5,000만원이다. 두 부부 모두 2억원 소득에 같은 5,000만원 세액이므로 소득이 같으면 세액이 같은 수평적 공평성이 충족된다.\n합산과세는 결혼 전후 세부담이 달라 결혼중립성을 충족하지 않는다.","c":"중","v":1},"세무사2022_59-14":{"w":"이자소득세는 세후 수익률을 낮춰 현재소비의 상대가격을 낮추므로 대체효과로 현재소비 증가·저축 감소, 소득효과로 현재소비 감소·저축 증가이다.\n첫째 설명은 효과의 방향이 거꾸로이므로 X. 나머지 넷(시점간 모형 분석, 현재소비 유리, 현재소비의 대체효과 증가·소득효과 감소, 저축의 증감 불분명)은 O. 옳은 것은 4개.","c":"상","v":1},"세무사2023_60-11":{"w":"이자소득세로 현재소비의 상대가격은 하락한다(①). 현재소비는 대체효과로 늘고 소득효과로 줄어 방향이 상반되므로 상대적 크기에 따라 결정된다(④). 저축도 불분명하므로 ②는 틀리고, 미래소비는 소득효과·대체효과 모두 감소 방향이라 ⑤는 틀리다.","c":"상","v":1},"세무사2023_60-12":{"w":"한계실효세율은 세전 수익률과 세후 수익률의 차이를 세전 수익률로 나눈 것이다. 조세가 없으면 0(ㄱ O), 낮을수록 세후 수익이 커 투자에 유리하다(ㄴ O), 음수이면 세후 수익이 세전보다 커서 조세가 투자를 촉진한다(ㄷ O).","c":"상","v":1},"세무사2023_60-13":{"w":"자본의 사용자 비용을 낮추는 정책은 가속상각, 투자세액공제, 특정기간 조세감면, 법인세율 인하 등이다. 근로소득세 감면은 노동공급에 관한 정책이어서 자본의 사용자 비용과 관계가 없다.","c":"상","v":1},"세무사2023_60-14":{"w":"MM 제1명제(법인세 없음)는 자본구조와 기업가치가 무관하다는 것이므로 최적 자본구조의 존재를 증명했다는 ㄱ은 X.\n법인세 없음(ㄴ), 경영자가 주주 부를 극대화(ㄷ), 정보 대칭(ㄹ)은 모두 가정이므로 O.","c":"상","v":1},"세무사2023_60-20":{"w":"과세소득 4,500만원: 1,200~3,000만원에 9% = 162만, 3,000~4,500만원에 18% = 270만 → 세액 432만원.\n한계세율 18%, 실효세율 = 432/5,500 = 7.85%.","c":"상","v":1},"세무사2024_61-07":{"w":"ㄱ 자본이득방식은 완전통합이다. ㄷ 배당세액공제제도는 부분통합이다. 따라서 ㄱ, ㄷ은 X.\nㄴ 조합방식은 완전통합 O, ㄹ 차등세율제도는 부분통합 O.","c":"상","v":1},"세무사2024_61-12":{"w":"이자소득세로 세후 이자율이 내려가면 미래소비로 표시한 현재소비의 상대가격이 하락한다(ㄱ O). 대체효과로 현재소비가 늘고 저축이 줄어든다(ㄴ O). 실질소득이 감소해 소득효과로 정상재인 현재소비와 미래소비가 모두 줄어든다(ㄷ O). 실질소득 감소로 효용도 감소한다(ㄹ O). 모두 옳다.","c":"상","v":1},"세무사2025_62-16":{"w":"MM 제1명제는 법인세·파산비용·정보비대칭·대리인 문제가 없는 완전자본시장에서 자본구조가 기업가치와 무관하다는 명제이다.\nㄱ 최적 자본구조의 존재를 입증한 것이 아니므로 X, ㄷ 주인-대리인 문제가 없다고 가정하므로 X. ㄴ, ㄹ, ㅁ이 O.","c":"상","v":1},"세무사2025_62-18":{"w":"ㄱ 후방굴절형 노동공급곡선은 소득효과가 대체효과보다 클 때 나타난다. 작으면 X.\nㄴ 비례소득세로 세후임금이 내려갈 때 대체효과가 더 크면 여가가 늘고 노동공급은 줄어든다. X.\nㄷ 중립세(정액세)는 상대가격을 바꾸지 않아 대체효과가 없고 소득효과만 있다. O.","c":"상","v":1},"세무사2026_63-02":{"w":"T = -300 + 0.3Y에서 한계세율은 0.3으로 일정하고 평균세율은 0.3 - 300/Y로 소득이 늘수록 높아지지만 항상 0.3보다 낮다. 평균세율이 한계세율보다 높다는 ④가 옳지 않다. 세수탄력성은 한계세율/평균세율로 1보다 크다.","c":"상","v":1},"세무사2026_63-13":{"w":"이자소득세로 세후 이자율이 하락하면 미래소비의 상대가격이 오르고 현재소비의 상대가격은 하락한다. ①이 옳지 않다. 대체효과로 현재소비 증가·미래소비 감소, 소득효과로 둘 다 감소하며 저축과 현재소비의 변화는 두 효과의 크기에 달려 있다.","c":"상","v":1},"세무사2016_53-03":{"w":"X재 과세로 X의 가격이 오른다. 대체효과: 상대적으로 비싸진 X는 줄고 Y는 늘어난다(ㄱ). 소득효과: 가격 상승으로 실질소득이 줄면 열등재 X는 소비가 늘고 정상재 Y는 줄어든다(ㄹ). 옳은 것은 ㄱ, ㄹ.","c":"상","v":1},"세무사2016_53-04":{"w":"순흐름은 0기 -10, 1~3기 0, 4기 +10이다. 내부수익률은 -10 + 10/(1+r)^4 = 0에서 r = 0%이므로 12%는 X. 할인율이 양수이면 NPV = -10 + 10/(1+r)^4 < 0이므로 NPV 1도 X. 편익의 현재가치가 비용의 현재가치보다 작아 B/C < 1은 O. 할인율이 낮아지면 4기의 편익이 덜 깎여 NPV가 증가하므로 O. 옳은 것은 2개.","c":"중","v":1},"세무사2016_53-40":{"w":"회피행위접근법은 오염 위험을 피하려고 지출하는 금액(방독면, 정수기 등)을 편익으로 본다. 조건부가치측정법은 설문으로 표명된 선호를 이용하고, 헤도닉가격법은 부동산 가격 등 시장자료, 여행비용법은 방문 비용으로 환경가치를 추정한다.","c":"상","v":1},"세무사2017_54-39":{"w":"A의 NPV = 1,210/(1+r)² - 1,000, B의 NPV = 1,150/(1+r) - 1,000.\nr = 7%: A 56.9, B 74.8 → B가 유리하므로 ①이 옳지 않다. r = 8%: A 37.4, B 64.8 → B 유리.\nIRR은 A 10%, B 15%로 B가 유리. 할인율이 약 5.2% 아래이면 A의 NPV가 더 커서 평가가 달라진다.","c":"상","v":1},"세무사2017_54-40":{"w":"순편익이 음(비용)일 때 확실대등액은 위험할인율만큼 비용을 더 크게 잡아 -100 × (1 + 0.2)로 계산하고, 이를 이자율 10%로 50년 할인한다. -100 × 1.2/(1.1)^50.","c":"중","v":1},"세무사2021_58-30":{"w":"순편익의 현재가치 = -3,000 + 1,100/1.1 + 2,420/1.1² = -3,000 + 1,000 + 2,000 = 0.","c":"중","v":1},"세무사2021_58-40":{"w":"확실성등가 = 기대소득 - 위험프리미엄. 위험회피 정도가 클수록 위험프리미엄이 커 확실성등가가 작다. 확실성등가가 크면 클수록 더 위험회피적이라는 ①이 옳지 않다.","c":"상","v":1},"세무사2023_60-40":{"w":"현재 임금률로 더 일하고 싶어도 못 하는 사람은 시간을 임금률 만큼도 팔지 못하고 있으므로 시간가치는 임금률보다 낮다고 추정한다. ②가 옳지 않다.","c":"상","v":1},"세무사2026_63-40":{"w":"할인율이 높으면 먼 미래의 편익이 크게 할인되므로 편익이 일찍 나오는 단기 사업이 장기 사업보다 유리하다. 비용편익분석은 민간에도 쓰이고, 현재가치법은 순편익 현재가치로 판단하며, IRR은 순현재가치를 0으로 하는 할인율이고, 두 방법의 결과는 항상 같지 않다.","c":"상","v":1},"세무사2022_59-20":{"w":"ㄴ 교부금은 중앙정부 의존도를 높여 재정자립도를 낮춘다. ㄹ 오우츠 분권화 정리는 규모의 경제와 외부성이 없는 경우에 성립한다. ㅁ 분권제도는 지역 선호 정보를 얻는 비용이 더 낮다. 따라서 ㄴ, ㄹ, ㅁ이 옳지 않다.","c":"상","v":1},"세무사2026_63-19":{"w":"지방교부세에는 보통교부세, 특별교부세, 부동산교부세, 소방안전교부세가 있다. 지역발전교부세는 지방교부세의 종류가 아니다.","c":"상","v":1},"세무사2016_53-09":{"w":"린달모형은 공공재 비용 분담을 자발적 합의로 정해 사뮤엘슨 효율성 조건을 충족시키며(셋째 O), 합의된 부담비율이 가격 기능을 한다(넷째 O). 외부성을 협상으로 해결한다는 것은 코즈 정리이므로 첫째 X, 정부개입이 필요하다는 둘째 X, 다섯째 설명도 맞지 않는다. 옳은 것은 2개.","c":"중","v":1},"세무사2016_53-24":{"w":"공공재의 균형: MUA + MUB = MC → (4 - X) + (8 - 2X) = 2X → 12 = 5X → X = 2.4.","c":"상","v":1},"세무사2021_58-18":{"w":"역수요 P_A = 5 - Z/20, P_B = 10 - Z/10. 합 15 - 0.15Z = MC 3 → Z = 80.\nP_B = 10 - 8 = 2이므로 부담비율은 2/3.","c":"상","v":1},"세무사2022_59-17":{"w":"ㄱ 비성수기에는 시설에 여유가 있어 한계비용만 받는 것이 효율적이다. ㄷ 이부가격제는 고정요금으로 결손을 메운다. ㄹ 램지가격은 비탄력적 수요(필수재)에 높은 가격을 매겨 분배 문제가 생길 수 있다. 모두 O.\nㄴ 한계비용가격설정은 효율적 배분을 달성한다(결손이 문제). ㅁ 규모의 경제가 있으면 한 기업이 생산하는 것이 낫다. 둘은 X.","c":"상","v":1},"세무사2023_60-31":{"w":"해안 6명 합산: 6(200 - 2Q) = 1,200 - 12Q, 내륙 4명: 4(150 - 3Q) = 600 - 12Q. 합 1,800 - 24Q = MC 840 → Q = 40.\n개인 부담: 해안 200 - 80 = 120, 내륙 150 - 120 = 30.","c":"상","v":1},"세무사2024_61-26":{"w":"P1 + P2 = 90 - (5/3)Q = 60 → Q = 18.\nP1 = 50 - 18 = 32, P2 = 40 - 12 = 28.","c":"상","v":1},"세무사2025_62-25":{"w":"도시 5명: 5(20 - Q) = 100 - 5Q, 농촌 5명: 5(15 - 2Q) = 75 - 10Q. 합 175 - 15Q = 85 → Q = 6.","c":"상","v":1},"세무사2026_63-25":{"w":"순수공공재는 비경합성과 비배제성을 모두 갖는다. ㄴ 대가를 내지 않아도 소비할 수 있다는 비배제성이므로 O. 혼잡한 국도(경합성), 볼펜·얼음 생수(소비하면 남이 쓰지 못하는 사적재)는 순수공공재가 아니다.","c":"상","v":1},"세무사2026_63-26":{"w":"그룹1 6명: 6(30 - Q/6) = 180 - Q, 그룹2 4명: 4(60 - Q/2) = 240 - 2Q. 합 420 - 3Q = 240 → Q = 60.\n개별 부담 P1 = 30 - 10 = 20, P2 = 60 - 30 = 30.","c":"상","v":1},"세무사2016_53-10":{"w":"조세수입이 일정할 때 효용 극대화는 구간별 MU/MR이 같아지는 것이다. 1번째 구간은 비율이 낮아 세율을 올려도 효용 손실이 작고, n번째 구간은 비율이 높아 세율을 낮추는 쪽이 이익이다. 1번째 인상, n번째 인하.","c":"중","v":1},"세무사2016_53-28":{"w":"스턴은 선형소득세 T = -a + tY의 최적 한계세율을 모의계산으로 구했다.\nㄱ. 불평등을 싫어하는 정도가 낮으면 재분배로 얻는 사회후생 이득이 작아 최적 한계세율이 낮아진다. O\nㄴ. 걷어야 할 세수가 많으면 같은 조건에서 세율을 더 높여야 하므로 최적 한계세율이 높아진다. O\nㄷ. 선형소득세는 면세점 위에서 한계세율이 하나로 고정되어 소득 구간마다 세율을 달리할 수 있는 비선형소득세보다 수직적 공평을 높이는 힘이 약하다. O\n모두 옳다.","c":"중","v":1},"세무사2016_53-30":{"w":"램지의 역탄력성 원칙: (P - MC)/P = k/ε.\nY: (50 - 30)/50 = 0.4 = k/1 → k = 0.4. X: (25 - 20)/25 = 0.2 = 0.4/ε → ε = 2.","c":"상","v":1},"세무사2016_53-37":{"w":"소득세·일반소비세·동일한 물품세는 재화 간 상대가격을 바꾸지 않아 재화 선택에 중립적이다. 특정 재화에만 물품세를 부과하면 그 재화의 상대가격이 올라 선택이 왜곡된다.","c":"상","v":1},"세무사2017_54-20":{"w":"공급이 Q = 50으로 가격에 반응하지 않는(완전비탄력적) 경우 과세해도 거래량이 변하지 않아 사중손실이 0이다. 세금은 모두 소비자 아닌 생산자가 부담한다.","c":"상","v":1},"세무사2021_58-10":{"w":"종가세율 t = 10%, 수요·공급 탄력성 ε_D = ε_S = 0.1.\n사중손실 = 1/2 × t² × P × Q × ε_D·ε_S/(ε_D + ε_S) = 0.5 × 0.01 × 1,000 × 1,000 × (0.01/0.2) = 250.","c":"상","v":1},"세무사2022_59-07":{"w":"초과부담은 세율의 제곱, 임금총액, 수요·공급 탄력성이 클수록 커진다(탄력성의 곱/합 형태). 노동수요곡선이 비탄력적으로 바뀌면 초과부담은 작아진다. 따라서 ④가 초과부담을 키우는 경우가 아니다.","c":"상","v":1},"세무사2023_60-17":{"w":"가격차별 독점의 이윤극대화는 시장별 MR이 같다: P(1 - 1/ε).\n가정용: 1,200 × (1 - 1/2) = 600. 산업용: P × (1 - 1/3) = 600 → P = 900원.","c":"상","v":1},"세무사2025_62-05":{"w":"한계비용 50이 일정하므로 세전 P = 50, Q = 50. 과세 후 소비자가격 70, Q = 30.\n조세수입 = 20 × 30 = 600. 소비자잉여 감소 = (50 + 30)/2 × 20 = 800. 판매량 감소 20. 세금 20 전부 소비자 부담.\n사중손실 = 1/2 × 20 × 20 = 200, 비효율성계수(사중손실/조세수입) = 200/600 = 1/3이다. ②의 3/4이 옳지 않다.","c":"상","v":1},"세무사2016_53-12":{"w":"정량보조는 같은 금액의 현금(정액)보조보다 후생이 같거나 낮다. ㄴ 대형평수 주택소유자는 소규모 임대아파트를 받으면 선택이 제한되어 현금보조보다 열등하다. ㄱ 무주택자도 현금보다 우월하지 않다. ㄷ 임대주택 정량보조는 식품 정량보조와 구분되는 효과를 갖는다고 보아 옳지 않다.","c":"중","v":1},"세무사2016_53-13":{"w":"실업급여는 소득대체율이 높을수록 일을 하지 않아도 되는 유인이 커져 구직노력이 줄어드는 도덕적 해이가 생긴다. 자발적 실업자는 지급대상이 아니고, 경기가 좋아지면 실업자가 줄어 지급이 줄어든다.","c":"상","v":1},"세무사2016_53-21":{"w":"무보험 시 가격 100에서 Q = 300, 본인부담 20이면 Q = 380.\n도덕적 해이의 후생비용은 늘어난 80단위에서 소비자 가치(수요)와 비용(100)의 차이를 합한 삼각형 = 1/2 × 80 × (100 - 20) = 3,200.","c":"상","v":1},"세무사2017_54-24":{"w":"W = Y1·Y2 = 64 → 균등분배대등소득 Y_e는 Y_e² = 64에서 8. 평균소득 10.\n앳킨슨 지수 = 1 - 8/10 = 0.2.","c":"상","v":1},"세무사2017_54-36":{"w":"포괄수가제는 진료 항목과 관계없이 정액을 지급해 과잉진료는 줄지만 서비스 품질 저하가 우려된다(ㄱ, ㄴ O). 의학 발전에 부정적인 쪽은 새 기술 도입을 억제하는 포괄수가제이므로 ㄷ은 X.","c":"상","v":1},"세무사2021_58-29":{"w":"연금보험을 사회보험으로 운영하는 이유는 역선택 등 시장실패 보완(ㄷ), 세대 내 소득재분배(ㄴ), 근시안적 노후 준비를 막는 온정적 간섭주의(ㄹ)이다. 재정수입 확보(ㄱ)는 사회보험의 목적이 아니다.","c":"중","v":1},"세무사2021_58-34":{"w":"ㄱ 소비자는 선택이 자유로운 현금보조를 더 선호하므로 X. ㄴ 현물은 구입·배분·관리 비용이 크다. ㄷ 현금은 다른 용도로 쓰일 가능성이 높다. ㄹ 현금은 선택의 폭이 넓다. ㄴ, ㄷ, ㄹ이 O.","c":"상","v":1},"세무사2022_59-32":{"w":"교육기회 확대와 누진세제는 불평등을 줄인다. 인두세(정액세)는 소득과 관계없이 같은 금액이라 역진적이고, 복권은 저소득층의 부담이 상대적으로 커 역진적이다.","c":"상","v":1},"세무사2022_59-34":{"w":"사회보험은 시장실패(역선택 등) 보완(ㄴ), 보험료로 재원 조달(ㄷ), 온정적 간섭주의(ㄹ)와 관련이 있다. 재정수입 달성(ㄱ)은 관련이 없다.","c":"중","v":1},"세무사2022_59-40":{"w":"국민연금은 1988년 시행, 1973년 국민복지연금법이 최초 법적 기반이고, 사업장가입자 보험료는 기준소득월액의 9%(근로자·사용자 각 4.5%)이다. 1인 이상 사업장 확대는 2022년이 아니라 2006년이다. ④가 옳지 않다.","c":"중","v":1},"세무사2023_60-28":{"w":"ㄱ 5분위분배율(하위 20% 소득/상위 20% 소득)은 완전 균등이면 1이다.\nㄴ 10분위분배율(하위 40% 소득/상위 20% 소득)은 완전 균등이면 2다.\nㄷ 지니계수는 0이다.\nㄹ 앳킨슨지수 1 − (균등분배대등소득/평균소득)은 0이다.\nㅁ 달튼지수를 1 − (실제 사회후생/균등분배 시 사회후생)으로 정의하면 완전 균등에서 0이 된다. 이 정의로는 ㄷ, ㄹ, ㅁ(⑤)이 되어 데이터 정답 ③과 다르다. 달튼지수를 두 후생의 비율(평등지수)로 보면 1이므로 ③이 된다.","c":"의심","v":1},"세무사2024_61-24":{"w":"상품권으로 y 5단위(15)를 받은 소비점 (30, 5)는 현금 75를 받은 예산선 2x + 3y = 75 위에 있다. MRS(30, 5) = 1이면 가격비 2/3보다 커서 소비자는 x를 늘리고 y를 줄이려 하지만, 상품권은 y를 5 아래로 줄이지 못하므로 현금으로 받을 때 효용이 더 높다.\nMRS = 0.5이면 y를 더 사려고 하므로 상품권 제약이 구속하지 않아 효용이 같다.","c":"상","v":1},"세무사2024_61-34":{"w":"ㄱ 특정 현물 소비 증대가 목표면 현물보조가 효과적. ㄴ 선호 존중에는 현금보조. ㄹ 가격보조는 상대가격을 바꿔 비효율을 만든다. ㅁ 현금보조는 부정수급·오남용 가능성이 있다. ㄷ 현물보조가 현금보조보다 행정·운영비용이 더 높으므로 X.","c":"상","v":1},"세무사2024_61-36":{"w":"ㄱ 재원이 고정되면 기초수당을 올릴 때 한계세율도 올려야 한다. ㄴ 비범주적 보조금이라 자격심사가 필요 없다. ㄹ 한계세율이 높으면 근로의욕이 낮아진다. ㅁ 여가가 정상재이면 보조금의 소득효과와 한계세율의 대체효과가 모두 노동공급을 줄인다. 모두 O.\nㄷ 재분배 효과는 한계세율이 높을수록 커지므로 X.","c":"중","v":1},"세무사2025_62-34":{"w":"국민연금은 역선택으로 인한 시장실패를 치유하고(ㄱ), 노후 준비를 강제하는 온정적 간섭(ㄷ)이며, 소득재분배 수단(ㄹ)이다. 조세수입 확충(ㄴ)은 목적이 아니다.","c":"상","v":1},"세무사2025_62-40":{"w":"세대 내 재분배는 자신이 낸 보험료를 적립해 받는 완전적립방식에서, 세대 간 재분배는 현재 근로세대가 현재 노년세대를 부양하는 부과방식에서 일어난다. ②는 반대로 서술했다.","c":"상","v":1},"세무사2016_53-17":{"w":"공리주의 W = 3√Xa + √Xb, Xa + Xb = 1,000.\n극대화 조건 3/(2√Xa) = 1/(2√Xb) → √Xa = 3√Xb → Xa = 900, Xb = 100.\nW = 3 × 30 + 10 = 100.","c":"상","v":1},"세무사2016_53-38":{"w":"도덕적 해이를 줄이고 역선택도 줄여야 불확실성이 완화된다. 역선택의 확대는 불확실성 완화 방안이 아니다.","c":"하","v":1},"세무사2021_58-21":{"w":"효용가능경계 위의 점은 생산과 소비의 모든 효율 조건(MRS = MRT 포함)을 만족하고, 생산가능곡선 위의 점과 대응하며, 계약곡선을 효용공간에 옮긴 곡선들의 포락선이다(ㄴ, ㄹ).\nㄱ 소비 효율만이 아니고 ㄷ 모든 점에서 MRS = MRT이며, ㅁ 공평은 사회후생함수가 정하므로 X.","c":"상","v":1},"세무사2022_59-25":{"w":"W = min(U_A, U_B)이므로 3√X_A = √X_B → X_B = 9X_A. X_A + X_B = 1,000 → X_A = 100, X_B = 900.\nW = 3 × 10 = 30.","c":"상","v":1},"세무사2023_60-21":{"w":"총부존은 x = 40, y = 20이다. 효용함수 xy에서 파레토 효율의 조건은 y1/x1 = y2/x2이고 자원을 모두 써야 한다.\nㄱ (6,3)·(34,17): 합 (40,20), 0.5 = 0.5 → 효율.\nㄴ (16,8)·(22,11): x 합이 38이라 남는 자원이 있어 개선 가능.\nㄷ (24,10)·(16,10): 10/24 ≠ 10/16 → 개선 가능.\nㄹ (38,19)·(2,1): 합 (40,20), 0.5 = 0.5 → 효율.","c":"상","v":1},"세무사2023_60-22":{"w":"A는 U1 + U2, B는 min, C는 U1U2의 극대 접점이다. 접점이 일치하면 U1 = U2이고 그 점에서 접선 기울기가 -1이어야 한다.\nㄱ A = B이면 접선 기울기가 -1이어서 C(곱)도 같은 점이다. ㄴ A = C이면 기울기 -1에서 U1 = U2이므로 B와도 일치한다.\nㄷ 경계가 볼록하지 않으면 B = C라도 합 극대점 A는 다를 수 있다. ㄹ 세 점은 일치할 수 있다.","c":"중","v":1},"세무사2023_60-23":{"w":"ㄱ 후생경제학 제1정리는 경쟁시장의 균형이 파레토 효율적이라는 것이다. ㄴ 제2정리는 초기부존을 재분배하면 원하는 효율적 배분을 시장으로 달성할 수 있다는 것이지 효율성이 공평성을 보장한다는 뜻이 아니다. ㄷ 제2정리는 선호의 볼록성이 필요하다.","c":"상","v":1},"세무사2023_60-25":{"w":"ㄱ 시장실패는 정부개입의 필요조건이지 충분조건이 아니다. ㄴ 평균비용가격설정은 P = AC로 P > MC라 비효율이 남는다. ㄷ 정액세는 의사결정을 왜곡하지 않는다. ㄹ 사회보험은 시장실패를 보완한다. ㅁ 공공재는 비배제성·비경합성 때문에 시장실패가 생긴다.","c":"상","v":1},"세무사2024_61-22":{"w":"효용 xy에서 x = m/(2p_x), y = m/(2p_y). 목표 배분 (20, 15)에서 m1 = 20·2p_x = 15·2p_y → p_y/p_x = 4/3. p_x = 1, p_y = 4/3으로 두면 소비자 1의 소득은 40.\n새 초기부존의 가치가 40이어야 하므로 x̄1 + (4/3)ȳ1 = 40. ④ (16, 18): 16 + 24 = 40. 소비자 2도 (24, 12): 24 + 16 = 40.","c":"상","v":1},"세무사2024_61-23":{"w":"생산가능곡선 위의 점이므로 생산 측면의 효율이 만족된다(ㄱ). 두 소비자의 MRS가 같아 소비 효율이 만족된다(ㄴ). MRS = 2가 MRT = 1과 다르므로 x를 늘리고 y를 줄이는 쪽으로 생산을 바꾸면 모두의 효용이 올라 종합적 파레토 개선이 가능하다(ㄷ).","c":"상","v":1},"세무사2025_62-24":{"w":"사용재: 3√X_A = √X_B → X_A = 100, X_B = 900, W = 30. 공공재: 둘이 같은 양 X를 소비하므로 U_A = 3√X > U_B = √X이고 min은 B의 효용이다. W = √1,000 ≈ 31.6로 사용재일 때(30)보다 크다.\n④의 A의 효용이 아니라 B의 효용으로 결정되므로 옳지 않다.","c":"상","v":1},"세무사2026_63-22":{"w":"총부존은 x = 3, y = 4. MRS1 = y1/x1, MRS2 = y2/(2x2). 파레토 효율은 두 값이 같고 자원을 모두 쓸 때다.\n④ (2,2)·(1,2): MRS1 = 1, MRS2 = 2/2 = 1이고 합이 (3,4)이다. ①은 y 합이 3, ⑤는 x 합이 4로 맞지 않고 ②, ③은 MRS가 다르다.","c":"상","v":1},"세무사2026_63-23":{"w":"MR = 120 - Q = MC = Q → Q = 60, P = 90. 효율적 생산은 P = MC에서 Q = 80, P = 80. 사회후생손실 = 1/2 × (90 - 60) × (80 - 60) = 300.\nㄱ 폐지하면 소비자·생산자 잉여가 사라져 후생이 감소. ㄴ P = 100은 독점가격 90보다 높아 구속력이 없다. ㄷ P = 80이면 Q = 80이라 손실 0. ㄹ 손실 300 감소.","c":"상","v":1},"세무사2016_53-34":{"w":"수요 P = 100 - Q/3, MR = 100 - 2Q/3, MC = Q + 10 → Q = 54, P = 82.\n소비자에게 20을 과세하면 생산자 수취 가격 P = 80 - Q/3, MR = 80 - 2Q/3 = Q + 10 → Q = 42, 생산자 수취 가격 66. 공급자 부담 82 - 66 = 16, 소비자 부담 20 - 16 = 4이다. ④의 12는 옳지 않다.","c":"상","v":1},"세무사2017_54-09":{"w":"수요가 공급보다 탄력적이면 세금과 보조금은 비탄력적인 공급자 쪽에 더 많이 귀착된다. 납세자나 보조 대상이 누구인지는 귀착과 관계가 없다.\nㄱ, ㄴ은 수요자 쪽이라 X, ㄷ, ㄹ은 공급자에게 더 귀착되므로 O.","c":"상","v":1},"세무사2021_58-05":{"w":"조세부담뿐 아니라 정부 지출로 생기는 편익의 귀착까지 함께 보는 개념은 균형예산 조세귀착이다. 절대적 귀착은 조세 하나만의 귀착, 차별적 귀착은 한 조세를 다른 조세로 바꿀 때의 변화를 본다.","c":"상","v":1},"세무사2022_59-16":{"w":"하버거 모형에서 X부문 자본에 과세하면 X부문이 자본을 덜 쓰는 방향으로 요소대체가 일어나 경제 전체의 자본 수요가 줄고 노동에 대비한 자본의 상대가격이 낮아진다. 두 부문의 요소집약도가 같으면 산출효과는 요소가격을 바꾸지 않는다.","c":"중","v":1},"세무사2023_60-01":{"w":"지방세이면서 목적세인 것은 지방교육세와 지역자원시설세이다. 농어촌특별세는 국세 목적세, 주민세·담배소비세는 지방세 보통세이고 문화재관람료는 조세가 아니다.","c":"상","v":1},"세무사2023_60-05":{"w":"세전 균형: 120 - 2P = P → P = 40, Q = 40.\n소비자에게 12를 과세하면 120 - 2(P + 12) = P → P = 32(생산자 수취가격). 생산자 부담 40 - 32 = 8원, 소비자 부담 4원.","c":"상","v":1},"세무사2023_60-09":{"w":"탈세는 자원배분을 왜곡하고(ㄱ), 지하경제를 키우며(ㄴ), 정직한 납세자와 탈세자 사이의 부담을 불공평하게 하고(ㄷ), 정부가 파악하는 소득이 실제와 달라 경제정책 효과를 불확실하게 한다(ㄹ).","c":"하","v":1},"세무사2024_61-01":{"w":"바람직한 조세의 조건에는 공평성, 확실성, 편의성, 경제성 등이 있고, 재정수입을 극대화하는 것은 조세의 원칙이 아니라 충분한 수입 확보(충분성)가 기준이다. ②가 옳지 않다.","c":"중","v":1},"세무사2024_61-05":{"w":"세전: 50 - 2P = 3P - 20 → P = 14, Q = 22.\n생산자 과세 후 공급 Q = 3(P - 10) - 20 → 50 - 2P = 3P - 50 → P = 20, Q = 10.\n조세총액 = 10 × 10 = 100(120이 아님). 소비자 부담 20 - 14 = 6, 생산자 부담 4. 사회적 후생손실 = 1/2 × 10 × 12 = 60.","c":"상","v":1},"세무사2024_61-06":{"w":"공평한 조세부담의 기준은 능력원칙과 편익원칙이다. 중립성·효율성·최소징세비는 효율성 측면의 기준이다.","c":"상","v":1},"세무사2024_61-11":{"w":"담배소비세는 지방세 보통세이다. 지방교육세, 지역자원시설세, 농어촌특별세, 교통·에너지·환경세는 목적세이다.","c":"상","v":1},"세무사2025_62-01":{"w":"납부방법·시기·금액이 법과 규정에 따라 납세자가 알 수 있게 제시되어야 한다는 것은 확실성의 원칙이다.","c":"상","v":1},"세무사2025_62-06":{"w":"한 조세를 같은 세수의 다른 조세로 바꿨을 때의 분배효과를 보는 것은 차별적 조세귀착이다.","c":"상","v":1},"세무사2026_63-01":{"w":"ㄱ 직접세는 법적 납세의무자와 담세자가 같다. ㄴ 간접세는 세금이 가격에 포함돼 조세저항이 작고 징세비용도 적다.\nㄷ 간접세는 역진적이라 수직적 공평은 직접세가 우월하다. ㄹ 증여세는 수증자의 사정을 보는 인세 성격이므로 재산세만 물세에 해당한다.","c":"중","v":1},"세무사2026_63-03":{"w":"알링햄-샌드모 모형은 절대위험기피도 체감을 가정하고(ㄱ), 감사확률과 벌금률이 높아질수록 탈루소득이 준다(ㄴ). 샌드모는 세율을 적정하게 유지하고 감사확률·벌금률로 탈세를 막자고 한다(ㄹ). 세율 상승은 소득효과와 대체효과가 반대로 작용해 탈루소득의 방향이 불분명하므로 ㄷ은 X.","c":"중","v":1},"세무사2026_63-06":{"w":"수요 P = 80 - 2Q, 공급 P = 20 + Q. 세전 Q = 20, P = 40.\n생산자에게 12를 과세하면 소비자가 내는 가격 P = 32 + Q → 80 - 2Q = 32 + Q → Q = 16, P = 48.\n소비자 부담 48 - 40 = 8, 생산자 부담 12 - 8 = 4.","c":"상","v":1},"세무사2017_54-17":{"w":"균형재정이므로 G = T = 400. Y = 200 + 0.8(Y - 400) + 400 + G에서 Y = 1,400 + 5G, G = 400이면 Y = 3,400. 완전고용 4,000까지 부족분 600.\n정부지출 승수 5 → 추가 정부지출 600/5 = 120. 감세 승수 0.8/0.2 = 4 → 감세 600/4 = 150.","c":"상","v":1},"세무사2022_59-08":{"w":"ㄱ 통화주의자는 구축효과가 불황기에도 크다고 보며, 케인즈학파는 불황기에 구축효과가 작다고 본다. 호황기와 비교한 서술이 틀리다. ㄴ 케인즈학파는 승수효과를 인정, ㄷ 리카르도 대등정리는 총수요에 영향이 없다는 것, ㅁ 배로도 같은 입장이다. ㄹ 러너는 내부채무는 미래세대의 부담이 아니라고 했다.","c":"상","v":1},"세무사2022_59-35":{"w":"지출항목(품목)별로 편성하는 방식은 품목별 예산제도이고, 비슷한 업무를 묶어 편성하며 2007년부터 도입한 것은 프로그램 예산제도이다.","c":"상","v":1},"세무사2023_60-08":{"w":"조세지출은 세법상 감면으로 걷히지 않게 되는 세수이다. 특별감가상각(ㄴ), 투자세액공제(ㄹ), 기부금 소득공제(ㅂ)가 해당한다. 보조금 지급, 세수의 지출, 환경세 부과는 조세지출이 아니다.","c":"상","v":1},"세무사2023_60-37":{"w":"균형재정이므로 T = G = 1,000. Y = 1,000 + 0.6(Y - 1,000) + 1,000 + 1,000 → 0.4Y = 2,400, Y = 6,000. 부족분 1,000.\n정부지출 승수 2.5 → 400. 감세 승수 0.6/0.4 = 1.5 → 감세 1,000/1.5 ≈ 667이다. ①의 600은 옳지 않다.","c":"상","v":1},"세무사2025_62-12":{"w":"ㄱ 구축효과의 정의. ㄷ 중앙은행 인수는 통화량 증가로 물가를 올린다. ㄹ 이자율 상승이 없어 총수요 증대효과가 더 크다. ㄴ 통화주의자는 구축효과가 시기와 관계없이 크다고 보며, 불황기에 더 크다는 서술은 옳지 않다.","c":"중","v":1},"세무사2026_63-11":{"w":"조세지출은 민간의 특정 행위를 촉진할 필요가 있는지(ㄱ), 정부가 개입할 이유가 있는지(ㄷ), 조세지출이 최선의 수단인지(ㄹ)를 검토해야 한다. 항상 효율성이 우선이라는 것(ㄴ)과 매년 일정 비율 증가(ㅁ)는 기준이 아니다.","c":"상","v":1},"세무사2026_63-15":{"w":"과열기에는 투자 유인을 줄여야 한다. 특정기간 조세감면을 폐지하면 투자 유인이 줄어든다. 금리 인하, 투자세액공제 확대, 가속상각, 준비금제도는 투자를 촉진한다.","c":"상","v":1},"세무사2017_54-28":{"w":"선호가 A: x>y>z, B: y>z>x, C: z>x>y로 순환해 x>y(A,C), y>z(A,B), z>x(B,C)가 되어 이행성이 깨지는 투표의 역설이 생기고 대진 순서에 따라 승자가 달라진다. 이 선호는 단봉형이 아니어서 중위투표자 정리가 성립하지 않는다. ③이 옳지 않다.","c":"상","v":1},"세무사2017_54-29":{"w":"총비용 = 의사결정비용 + 외부비용 = 10n² + 10 - 6n² - 2n + 5 = 4n² - 2n + 15.\n미분 8n - 2 = 0 → n = 1/4.","c":"상","v":1},"세무사2021_58-22":{"w":"관료가 조직 규모(예산)를 극대화하면 총편익 = 총비용인 점까지 생산한다. 총편익 16Q - Q²/4 = 총비용 12Q → Q = 16.","c":"상","v":1},"세무사2021_58-23":{"w":"다수결 투표제도에서는 소수에게 비용을 전가해 과다공급이 생기고(ㄱ), 정치적 결탁(로그롤링)도 과다공급을 낳는다(ㄴ). 다운즈의 투표자 무지와 갤브레이드의 의존효과는 공공재 과소공급의 원인으로 설명한다.","c":"중","v":1},"세무사2023_60-27":{"w":"보다 점수(1순위 3점~4순위 0점):\na = 4×3 + 3×1 + 2×0 = 15, b = 4×2 + 3×3 + 2×1 = 19, c = 4×1 + 3×0 + 2×3 = 10, d = 0 + 3×2 + 2×2 = 10.\nb가 선택된다.","c":"상","v":1},"세무사2023_60-30":{"w":"b와 a: B, C가 b를 선호 → b 승. b와 c: A, B가 b를 선호 → b 승. b가 모든 대안을 이기는 꽁도세 승자이다.","c":"상","v":1},"세무사2024_61-28":{"w":"사례 1: b가 a를 3:0, c를 2:1로 이겨 승자 b. 사례 2: a와 b는 a(2:1), a와 c는 c(2:1), c와 b는 c(2:1)로 승자 c. 두 사례 모두 역설은 없다.","c":"상","v":1},"세무사2026_63-27":{"w":"ㄱ 꽁도세 승자는 투표의 역설이 있으면 존재하지 않는다. ㄴ 과반수 득표자는 다른 모든 대안에 대해 과반을 얻으므로 꽁도세 승자와 같다. ㄷ 최다득표자는 과반이 아니면 꽁도세 승자가 아닐 수 있다. ㄹ 강선호이면 두 대안이 서로를 이길 수 없어 꽁도세 승자는 유일하다.","c":"상","v":1},"세무사2016_53-11-1":{"w":"오염으로 인한 총사회비용은 감축비용과 오염피해의 합이고 이 합이 최소가 되는 점이 사회적 한계감축비용과 사회적 한계피해가 같아지는 점이다.","c":"상","v":1},"세무사2016_53-11-3":{"w":"기업마다 한계감축비용이 달라서 감축비용이 낮은 기업이 더 많이 줄이도록 해야 같은 감축량을 가장 적은 총비용으로 달성한다.","c":"상","v":1},"세무사2016_53-11-4":{"w":"코즈 정리에 따르면 재산권이 명확히 설정되고 거래비용이 작으면 당사자 간 협상으로 최적 오염 수준에 이른다.","c":"상","v":1},"세무사2016_53-11-5":{"w":"오염세(피구세)는 배출 1단위마다 세금을 내게 하므로 한계감축비용이 세율보다 낮은 기업이 스스로 배출을 줄인다.","c":"상","v":1},"세무사2016_53-31-1":{"w":"코즈 정리는 소유권이 명확히 설정되고 거래비용이 없으면 당사자 간 자발적 협상으로 외부성이 해결된다는 내용이다.","c":"상","v":1},"세무사2016_53-31-2":{"w":"코즈 정리는 외부성 때문에 생기는 과다 또는 과소 생산을 협상으로 바로잡는 민간 해결책이다.","c":"상","v":1},"세무사2016_53-31-3":{"w":"코즈 정리는 재산권을 누구에게 주느냐와 관계없이 효율적 결과가 같다고 보므로 가해자와 피해자의 구분이 결과를 좌우하지 않는다.","c":"중","v":1},"세무사2016_53-31-5":{"w":"거래비용이 작을수록 협상이 성사되기 쉬워서 코즈 정리가 성립하기 좋다.","c":"상","v":1},"세무사2017_54-25-1":{"w":"공유지의 비극은 소유권이 불분명한 자원을 각자 아껴 쓸 유인이 없어서 과다 사용되는 문제다.","c":"상","v":1},"세무사2017_54-25-2":{"w":"연근해 어족자원은 경합적이면서 배제가 어려운 공유자원이어서 남획으로 고갈되는 공유지의 비극의 대표 사례다.","c":"상","v":1},"세무사2017_54-25-3":{"w":"공유자원을 쓰는 개인은 자기 사용이 다른 사람에게 주는 비용(혼잡·고갈)을 고려하지 않으므로 외부불경제가 생긴다.","c":"상","v":1},"세무사2017_54-25-5":{"w":"공유자원은 비배제성 때문에 각자가 사회적 비용을 따지지 않고 사용해 최적 수준보다 빨리 고갈된다.","c":"상","v":1},"세무사2017_54-31-1":{"w":"배출권거래제는 정부가 허용 총배출량을 먼저 정하고 그만큼의 배출권을 기업에 할당한 뒤 거래하게 하는 제도다.","c":"상","v":1},"세무사2017_54-31-2":{"w":"한계감축비용이 낮은 기업은 배출권 가격보다 싸게 감축할 수 있어 더 줄이고 남는 배출권을 판다.","c":"상","v":1},"세무사2017_54-31-3":{"w":"기업들이 배출권 가격에 맞춰 감축량을 정하므로 균형에서는 모든 기업의 한계감축비용이 배출권 가격과 같아져 서로 같다.","c":"상","v":1},"세무사2017_54-31-4":{"w":"거래가 자유로우면 초기 할당과 관계없이 한계감축비용이 같아지는 균형에 이르러 총감축비용이 최소가 된다. 초기 할당은 기업 간 부의 분배만 바꾼다.","c":"상","v":1},"세무사2017_54-32-2":{"w":"코즈 정리는 재산권이 명확히 정해져 있어야 당사자들이 협상할 수 있다는 전제 위에 성립한다.","c":"상","v":1},"세무사2017_54-32-3":{"w":"협상 이득이 협상비용(거래비용)보다 작으면 협상이 이루어지지 않으므로 이득이 비용보다 커야 코즈 정리가 성립한다.","c":"상","v":1},"세무사2017_54-32-4":{"w":"코즈 정리는 효율성만 다루고 재산권을 누구에게 주느냐에 따라 달라지는 부의 분배는 해결하지 못한다.","c":"상","v":1},"세무사2017_54-32-5":{"w":"재산권 귀속이 소득효과를 낳으면 권리를 누가 갖느냐에 따라 수요가 달라져 결과가 달라지므로 소득효과가 없어야 한다.","c":"상","v":1},"세무사2017_54-33-1":{"w":"외부성이 있으면 사적 한계비용·편익이 사회적 값과 달라서 사회적 한계편익과 사회적 한계비용이 같을 때가 효율적 배분이다.","c":"상","v":1},"세무사2017_54-33-2":{"w":"실질적(기술적) 외부성은 시장 가격을 거치지 않고 제3자에게 직접 이득이나 손실을 주어 자원배분을 왜곡하는 외부성이다.","c":"상","v":1},"세무사2017_54-33-4":{"w":"긍정적 외부성이 있으면 사회적 한계편익이 사적 한계편익보다 커서 시장 생산량이 사회적 최적보다 적다.","c":"상","v":1},"세무사2017_54-33-5":{"w":"부정적 외부성이 있으면 사회적 한계비용이 사적 한계비용보다 커서 시장 생산량이 사회적 최적보다 많다.","c":"상","v":1},"세무사2021_58-25-1":{"w":"코즈 정리는 외부성을 협상으로 해결해 효율성을 달성하는 방안일 뿐 분배의 형평성은 다루지 않는다.","c":"상","v":1},"세무사2021_58-25-2":{"w":"코즈 정리에서는 재산권이 가해자와 피해자 중 누구에게 있든 협상 결과의 효율성이 같으므로 이해관계 귀속과 무관하게 적용된다.","c":"중","v":1},"세무사2021_58-25-3":{"w":"코즈 정리는 외부성으로 생기는 과다 또는 과소 공급을 협상으로 해결하는 민간 해결 방안이다.","c":"상","v":1},"세무사2021_58-25-5":{"w":"코즈 정리는 소유권이 분명하고 거래비용이 작으면 자발적 거래로 외부성이라는 시장실패가 해결된다는 내용이다.","c":"상","v":1},"세무사2022_59-26-1":{"w":"기술적 외부성은 가격을 통하지 않고 효용·생산에 직접 영향을 주므로 사적 최적과 사회적 최적이 달라 비효율이 생긴다.","c":"상","v":1},"세무사2022_59-26-2":{"w":"코즈 정리는 외부성에 대한 재산권이 명확히 설정되어야 협상이 가능하다는 조건에서 성립한다.","c":"상","v":1},"세무사2022_59-26-3":{"w":"해로운 외부성이 있으면 사회적 한계비용이 사적 한계비용보다 커서 시장은 최적 수준보다 많이 생산한다.","c":"상","v":1},"세무사2022_59-26-4":{"w":"건축자재 가격 상승은 시장 가격을 통해 전달되는 영향이므로 금전적 외부성이다. 금전적 외부성은 자원배분의 비효율을 낳지 않는다.","c":"상","v":1},"세무사2022_59-29-1":{"w":"배출권 시장에서 정부가 총량을 정하고 기업들이 이를 거래하므로 균형에서 기업별 배출량의 합은 목표 배출량과 같다.","c":"상","v":1},"세무사2022_59-29-3":{"w":"배출권은 시장에서 가격이 자동으로 조정되어 물가 같은 환경 변화에 적응하지만 환경세는 세율을 법으로 다시 정해야 한다는 것이 표준 비교다.","c":"중","v":1},"세무사2022_59-29-4":{"w":"배출권 가격이 자기 한계저감비용보다 낮은 기업은 감축하는 대신 배출권을 사므로 한계저감비용이 높은 기업이 구매자가 된다.","c":"상","v":1},"세무사2022_59-29-5":{"w":"모든 기업이 배출권 가격과 자기 한계저감비용이 같아질 때까지 거래하므로 균형에서 한계저감비용이 같다.","c":"상","v":1},"세무사2023_60-29-2":{"w":"연구개발의 성과는 다른 기업과 사회로 지식이 파급되어 대가 없이 이득을 주는 긍정적 외부성이다.","c":"상","v":1},"세무사2023_60-29-3":{"w":"코즈 정리는 재산권이 명확히 설정되어 있을 때 협상으로 효율적 배분에 이른다는 정리다.","c":"상","v":1},"세무사2023_60-29-4":{"w":"금전적 외부성은 한 경제주체의 행동이 시장의 상대가격을 변화시켜 다른 주체에게 이득이나 손실을 주는 경우다.","c":"상","v":1},"세무사2023_60-29-5":{"w":"양봉업자와 과수원은 서로의 생산에 직접 영향을 주므로 시장 밖에서 생기는 기술적 외부성의 전형적인 예다(미드의 사례).","c":"상","v":1},"세무사2024_61-30-4":{"w":"울타리 설치비용이 소로 인한 피해액보다 커서 코즈 정리에 따라 권리가 누구에게 주어지든 효율적 결과는 울타리를 설치하지 않는 것이다.","c":"상","v":1},"세무사2025_62-30-1":{"w":"금전적 외부성은 가격 변화를 통한 소득 이전일 뿐 사회 전체의 자원배분 효율성에는 영향을 주지 않는다.","c":"상","v":1},"세무사2025_62-30-2":{"w":"실질적 외부성은 가격에 반영되지 않는 비용이나 편익을 낳아 사적 최적과 사회적 최적이 어긋나므로 비효율을 유발한다.","c":"상","v":1},"세무사2025_62-30-3":{"w":"외부성은 공장의 오염 같은 생산 외부성과 흡연 같은 소비 외부성이 모두 있다.","c":"상","v":1},"세무사2025_62-30-4":{"w":"환경세(피구세)는 가격 기구를 이용해 오염 비용을 내부화하는 시장 친화적 방식이고 직접 규제와 구별된다.","c":"상","v":1},"세무사2025_62-36-1":{"w":"코즈 정리는 소유권이 명확하고 거래비용이 작으면 정부 개입 없이 당사자 협상으로 외부성 문제가 해결된다는 내용이다.","c":"상","v":1},"세무사2025_62-36-2":{"w":"외부성에 한계피해만큼 조세를 부과하면 사적 비용에 사회적 비용이 반영되어 효율적 자원배분이 이루어진다.","c":"상","v":1},"세무사2025_62-36-3":{"w":"피구세는 사회적 최적 생산량에서의 한계피해액과 같은 크기로 부과해야 사적 한계비용이 사회적 한계비용과 일치한다.","c":"상","v":1},"세무사2025_62-36-5":{"w":"배출권거래제는 배출권 가격이라는 시장 가격을 이용해 오염 비용을 내부화하는 시장 기반 정책이다.","c":"상","v":1},"세무사2026_63-29-1":{"w":"코즈 정리에 따르면 거래비용이 없을 때 재산권이 가해자와 피해자 중 누구에게 있든 협상으로 효율적 자원배분에 이른다.","c":"상","v":1},"세무사2026_63-29-2":{"w":"코즈 정리는 정부 개입 없이 당사자 협상으로 외부성을 해결하는 사적 해결 방안이다.","c":"상","v":1},"세무사2026_63-29-3":{"w":"거래비용이 커서 협상이 성사되지 않으면 코즈 정리가 작동하지 않으므로 피구세 같은 정부 개입이 정당화될 수 있다.","c":"상","v":1},"세무사2026_63-29-4":{"w":"피해 규모를 한쪽만 알면 협상 과정에서 정보를 확인하고 전략적으로 행동하는 데 비용이 들어 거래비용의 한 요소로 본다.","c":"중","v":1},"세무사2016_53-25-3":{"w":"소득탄력성이 양이면 과세로 소득이 줄 때 소득효과가 위험자산 투자를 줄이고 세후 수익률 하락의 대체효과도 줄이므로 두 효과가 같은 방향이다.","c":"상","v":1},"세무사2016_53-27-5":{"w":"정액세는 상대가격을 바꾸지 않고 실질소득만 줄인다. 여가가 열등재이면 소득이 줄 때 여가 소비가 늘어 노동공급이 감소한다.","c":"상","v":1},"세무사2016_53-35-1":{"w":"누진적 증세와 이전지출은 소득을 고소득층에서 저소득층으로 옮기므로 저소득층의 실질소득이 늘어난다.","c":"중","v":1},"세무사2016_53-35-2":{"w":"재산세 증세는 부동산 소유자의 실질소득을 줄이고 세후 수익률을 낮춰 재산수익률을 낮추는 방향으로 작용한다.","c":"중","v":1},"세무사2016_53-35-3":{"w":"여가가 정상재이면 세율 인상 시 대체효과는 노동을 줄이고 소득효과는 노동을 늘려 순효과가 불확실하다.","c":"하","v":1},"세무사2016_53-35-5":{"w":"누진적 증세와 이전지출은 소득 격차를 줄이므로 소득분배의 형평성을 높인다.","c":"상","v":1},"세무사2017_54-10-1":{"w":"수평적 공평성은 경제적 능력이 같은 사람에게 같은 세금을 부과해야 한다는 원칙이다.","c":"상","v":1},"세무사2017_54-10-3":{"w":"결혼중립성은 결혼 여부가 부부의 총조세부담을 바꾸지 않아야 한다는 기준이다.","c":"상","v":1},"세무사2017_54-10-4":{"w":"개인별 분리과세는 결혼해도 각자 세액이 그대로여서 결혼중립적이지만 가구소득이 같아도 소득 분포에 따라 세금이 달라져 가족 간 수평적 공평성은 충족하지 못한다.","c":"상","v":1},"세무사2017_54-10-5":{"w":"수직적 공평성은 능력이 큰 사람이 더 많이 부담해야 한다는 원칙이고 소득세에서는 한계세율이 소득에 따라 올라가는 누진구조로 나타난다.","c":"상","v":1},"세무사2017_54-12-2":{"w":"여가가 열등재일 때 비례소득세는 대체효과(순임금 하락)와 소득효과(소득 감소로 열등재인 여가 증가)가 모두 노동공급을 줄인다.","c":"상","v":1},"세무사2017_54-18-3":{"w":"후방굴절 구간에서는 소득효과가 대체효과보다 커서 세율이 오르면 순임금이 줄어 소득을 유지하려고 노동공급을 늘린다.","c":"상","v":1},"세무사2021_58-09-1":{"w":"누진세는 한계세율이 높아 세금을 줄이려는 유인이 커서 조세회피가 늘어날 수 있다.","c":"중","v":1},"세무사2021_58-09-2":{"w":"누진세의 높은 한계세율은 노동·저축의 상대가격을 왜곡하는 대체효과를 키워 초과부담을 낳고 효율성을 해친다.","c":"상","v":1},"세무사2021_58-09-4":{"w":"조세는 정부 서비스에 대한 대가가 아니라 지불능력에 따라 부담하는 강제적 납부다. 편익원칙이 아닌 능력원칙이 누진세의 근거다.","c":"상","v":1},"세무사2021_58-09-5":{"w":"경기가 좋아 소득이 늘면 평균세율이 올라 세수가 더 늘고 불황에는 반대여서 누진세는 경기변동을 완화하는 자동안정장치다.","c":"상","v":1},"세무사2021_58-14-1":{"w":"신고전파 투자이론에서 투자는 자본의 사용자비용에 의해 결정된다.","c":"상","v":1},"세무사2021_58-14-2":{"w":"사용자비용이 낮아지면 자본의 최적 보유량이 늘어 투자가 증가한다.","c":"상","v":1},"세무사2021_58-14-3":{"w":"자본의 사용자비용은 감가상각과 이자율(자기자본이든 차입이든 포기한 수익)을 함께 포함하며 이자율 항목이 기회비용이다.","c":"상","v":1},"세무사2021_58-14-4":{"w":"자본재 구입비용을 즉시 공제하고 이자공제를 불허하는 현금흐름 과세는 투자의 한계수익률과 세후 수익률의 격차를 없애 투자에 중립적이다.","c":"상","v":1},"세무사2021_58-16-1":{"w":"초과부담은 세율의 제곱에 비례하므로 세율이 높아질수록 급격히 커진다.","c":"상","v":1},"세무사2021_58-16-2":{"w":"근로소득세가 부과되면 노동공급이 줄어 공급곡선이 왼쪽으로 이동하므로 우상향 공급곡선에서는 세전 시장임금률이 상승한다.","c":"상","v":1},"세무사2021_58-16-3":{"w":"공급곡선이 수직이면 공급이 임금에 반응하지 않으므로 세금 전액이 근로자에게 귀착된다.","c":"상","v":1},"세무사2021_58-16-4":{"w":"세금으로 실질소득이 줄면 여가가 정상재일 때 여가를 줄이고 노동을 늘리는 소득효과가 나타난다.","c":"상","v":1},"세무사2021_58-17-2":{"w":"완전손실상계가 있으면 정부가 손실도 세율만큼 분담해 위험부담이 줄어 위험자산 비중이 커진다(도마-머스그레이브 모형).","c":"상","v":1},"세무사2022_59-03-2":{"w":"누진세에서는 소득이 클수록 한계세율이 높아 같은 소득공제액이라도 절감되는 세금이 크다.","c":"상","v":1},"세무사2022_59-03-3":{"w":"소득공제를 받는 재화의 실질 가격은 한계세율만큼 낮아지므로 해당 재화의 상대가격이 달라질 수 있다.","c":"상","v":1},"세무사2022_59-03-4":{"w":"교육비는 소득세법 제59조의4 제3항에 따른 교육비 세액공제 대상이다(공제율 15%).","c":"상","v":1},"세무사2022_59-03-5":{"w":"세액공제액은 지출액에 공제율을 곱해 정해지므로 납세자의 한계세율과 무관하다.","c":"상","v":1},"세무사2022_59-05-1":{"w":"법인세는 법인의 각 사업연도 소득을 과세대상으로 하는 조세다.","c":"상","v":1},"세무사2022_59-05-2":{"w":"인플레이션 때 선입선출법은 오래된 낮은 원가를 매출원가로 잡아 재고자산 이익이 과대계상되므로 법인세 부담이 늘어난다.","c":"상","v":1},"세무사2022_59-05-3":{"w":"지급이자는 법인세법상 손금에 산입되지만 배당은 손금이 아니므로 부채 비중을 높이면 법인세가 줄어든다(일부 지급이자는 법인세법 제28조로 손금불산입).","c":"상","v":1},"세무사2022_59-05-5":{"w":"법인세 부담이 제품 가격 인상으로 이어지면 소비자가 조세의 일부를 부담하는 전가다.","c":"상","v":1},"세무사2022_59-06-1":{"w":"인플레이션으로 명목소득이 늘면 누진세에서 더 높은 세율구간에 진입해 실질 조세부담이 늘어난다.","c":"상","v":1},"세무사2022_59-06-2":{"w":"국채 같은 국가채무는 명목금액이 고정되어 있으므로 인플레이션으로 실질가치가 줄어든다.","c":"상","v":1},"세무사2022_59-06-3":{"w":"차입금은 명목금액으로 상환하므로 인플레이션 때 실질 상환부담이 줄어 채무자인 기업에 유리하다.","c":"상","v":1},"세무사2022_59-06-5":{"w":"감가상각은 취득 당시 명목원가로 공제하므로 인플레이션이 있으면 공제의 실질가치가 줄어 법인세의 실질 부담이 커진다.","c":"상","v":1},"세무사2022_59-12-1":{"w":"누진세는 구간과 공제가 복잡해 소득 쪼개기 같은 회피 수단이 생기기 쉽다는 것이 반대 논거 중 하나다.","c":"중","v":1},"세무사2022_59-12-2":{"w":"높은 한계세율이 근로·저축·투자 유인을 낮춰 경제 활력을 떨어뜨린다는 것이 누진세에 대한 대표적 반대 논거다.","c":"중","v":1},"세무사2022_59-12-4":{"w":"자신의 미래 소득을 모르는 상황에서 위험회피적인 사람은 보험 성격의 누진세를 선호할 수 있다(롤스의 무지의 베일 논리).","c":"중","v":1},"세무사2022_59-12-5":{"w":"밀의 균등희생 원칙에서 소득의 한계효용이 체감하면 소득이 큰 사람이 같은 희생을 하려면 더 많이 내야 하므로 누진세 논리가 나온다.","c":"중","v":1},"세무사2022_59-18-2":{"w":"여가가 정상재일 때 비례세와 누진세는 모두 소득효과와 대체효과로 노동공급에 영향을 주며 누진세는 한계세율이 높아 고소득자에게 대체효과 부담이 더 크다.","c":"중","v":1},"세무사2022_59-18-3":{"w":"여가가 열등재이면 비례소득세의 대체효과와 소득효과가 모두 노동공급을 줄인다.","c":"상","v":1},"세무사2022_59-18-4":{"w":"임금이 오를 때 소득효과가 대체효과보다 크면 노동공급이 줄어 노동공급곡선이 후방굴절한다.","c":"상","v":1},"세무사2022_59-18-5":{"w":"비례소득세는 순임금을 낮춰 대체효과로 노동을 줄이고 실질소득을 낮춰 정상재인 여가를 줄이는 소득효과로 노동을 늘린다.","c":"상","v":1},"세무사2022_59-19-1":{"w":"신고전파 투자이론에서 자본의 사용자비용이 낮을수록 최적 자본량이 커져 투자가 증가한다.","c":"상","v":1},"세무사2022_59-19-2":{"w":"생산요소 간 대체탄력성이 작으면 사용자비용이 변해도 자본과 노동의 비율이 크게 바뀌지 않아 자본스톡의 사용자비용탄력성이 낮아진다.","c":"중","v":1},"세무사2022_59-19-4":{"w":"자본재 구입비용 즉시 공제와 이자공제 불허를 결합한 현금흐름 과세는 투자에 중립적이다.","c":"상","v":1},"세무사2022_59-19-5":{"w":"이자공제가 허용되고 세법상 감가상각이 경제적 감가상각과 같으면 법인세는 경제적 소득에 대한 과세가 되어 투자 결정을 바꾸지 않는다.","c":"상","v":1},"세무사2023_60-06-5":{"w":"법인세가 초과이윤 같은 순수 이윤에 대한 과세이면 가격과 생산량이 바뀌지 않아 부담이 소유주인 주주에게 귀착된다.","c":"상","v":1},"세무사2023_60-07-2":{"w":"소득세법은 개인을 납세의무자로 하여 개인 단위로 과세하며 부부 자산소득 합산과세는 헌법재판소에서 위헌으로 결정되었다(2002년).","c":"상","v":1},"세무사2023_60-10-1":{"w":"임금 상승의 소득효과가 대체효과보다 크면 노동공급이 줄어 후방굴절형 공급곡선이 된다.","c":"상","v":1},"세무사2023_60-10-2":{"w":"세금으로 순임금이 내려가는 대체효과가 노동을 줄이고 소득효과가 더 작으면 순효과는 노동공급 감소다.","c":"상","v":1},"세무사2023_60-10-4":{"w":"여가가 열등재이면 비례소득세의 대체효과와 소득효과가 모두 노동공급을 줄인다.","c":"상","v":1},"세무사2023_60-10-5":{"w":"정액세는 상대가격을 바꾸지 않고 실질소득만 줄인다. 열등재인 여가가 늘어나므로 노동공급이 감소한다.","c":"상","v":1},"세무사2024_61-08-3":{"w":"선형누진세는 T = -a + tY 형태여서 한계세율은 t로 일정하고 평균세율은 소득이 늘수록 t에 가까워지며 올라간다.","c":"상","v":1},"세무사2024_61-09-3":{"w":"이자비용은 손금에 산입되지만 배당은 손금이 아니므로 부채비중을 높이면 법인세를 줄일 수 있다.","c":"상","v":1},"세무사2024_61-13-1":{"w":"노동 가능 시간 T를 여가 L과 노동 T-L로 나누고 임금률 w를 곱한 소득 M = w(T-L)이 세금 부과 전 예산선이다.","c":"상","v":1},"세무사2024_61-13-2":{"w":"세율 t이면 세후 임금이 (1-t)w이므로 여가를 모두 노동에 쓴 소득(세로축 절편)은 (1-t)wT이다.","c":"상","v":1},"세무사2024_61-13-3":{"w":"비례소득세에서 대체효과는 노동을 줄이고 정상재인 여가의 소득효과는 노동을 늘려 순효과가 증가 감소 불변 모두 가능하다.","c":"상","v":1},"세무사2024_61-13-5":{"w":"열등재인 여가는 세후임금 하락의 대체효과로 노동이 줄고 소득 감소로 여가가 늘어나는 소득효과로도 노동이 줄어든다.","c":"상","v":1},"세무사2024_61-14-1":{"w":"자본의 사용자비용은 자본재를 쓰는 동안 드는 이자(기회비용)와 감가상각 및 세금 부담을 합친 값이다.","c":"상","v":1},"세무사2024_61-14-2":{"w":"가속감가상각은 감가상각 공제를 앞당겨 세금의 현재가치를 줄이므로 사용자비용이 낮아져 투자가 증가한다.","c":"상","v":1},"세무사2024_61-14-4":{"w":"한계실효세율은 (세전 수익률 - 세후 수익률)/세전 수익률이므로 두 값이 같으면 0이다.","c":"상","v":1},"세무사2024_61-14-5":{"w":"한계실효세율이 높으면 투자의 세후 수익이 낮아져 투자가 줄어든다.","c":"상","v":1},"세무사2025_62-07-3":{"w":"면세사업등에 관련된 매입세액은 매출세액에서 공제하지 않는다(부가가치세법 제39조 제1항 제7호).","c":"상","v":1},"세무사2025_62-09-1":{"w":"헤이그-사이먼즈 포괄소득개념은 모든 소득을 합산해 동일하게 과세하므로 경제적 능력이 같으면 같게 과세하는 능력원칙에 기반한다.","c":"상","v":1},"세무사2025_62-10-1":{"w":"이자소득세는 민간저축을 늘리거나 줄이는 방향이 소득효과와 대체효과에 달려 있고 정부 세수 증가까지 합친 국민저축의 변화는 정해지지 않는다.","c":"중","v":1},"세무사2025_62-10-2":{"w":"이자소득세는 세후 이자율을 낮춰 대체효과(현재소비 증가)와 소득효과(현재소비 감소)를 함께 낳으므로 순효과는 두 효과의 상대적 크기에 달려 있다.","c":"상","v":1},"세무사2025_62-10-3":{"w":"이자소득세로 소득이 줄면 현재소비도 정상재라서 줄어드는 소득효과가 생긴다.","c":"상","v":1},"세무사2025_62-10-5":{"w":"세후 이자율 하락으로 미래소비의 상대가격이 올라 현재소비가 늘어나는 대체효과가 생기고 소득효과로는 현재소비가 줄어든다.","c":"상","v":1},"세무사2025_62-11-1":{"w":"신고전파 투자이론에서 사용자비용이 낮아지면 요소 수요가 늘어 투자가 증가한다.","c":"상","v":1},"세무사2025_62-11-2":{"w":"사용자비용탄력성이 작으면 조세로 사용자비용을 바꿔도 자본스톡이 거의 변하지 않아 조세정책의 투자 효과가 작다.","c":"상","v":1},"세무사2025_62-11-3":{"w":"즉시 비용처리와 이자공제 불허의 조합은 현금흐름 과세여서 투자의 세전과 세후 한계수익률 격차를 없앤다.","c":"상","v":1},"세무사2025_62-11-4":{"w":"한계실효세율이 음이면 세후 수익률이 세전 수익률보다 높다는 뜻이므로 세제가 투자에 보조금으로 작용해 투자를 촉진한다.","c":"상","v":1},"세무사2025_62-13-3":{"w":"손실상계를 허용하지 않으면 소득효과는 위험자산 비중을 늘리고 대체효과는 줄이므로 소득효과가 크면 위험자산 비중이 증가한다.","c":"상","v":1},"세무사2026_63-07-1":{"w":"경제적 이윤은 수입에서 명시적 비용뿐 아니라 자기자본 이자 같은 암묵적 비용(모든 기회비용)을 뺀 값이다.","c":"상","v":1},"세무사2026_63-07-3":{"w":"법인세법의 감가상각은 내용연수와 상각방법을 세법이 정한 기준으로 계산하므로 자산의 실제 가치 하락인 경제적 감가상각과 다르다.","c":"상","v":1},"세무사2026_63-07-4":{"w":"법인세법은 차입금 이자는 손금에 산입하지만 자기자본에 대한 귀속이자는 비용으로 인정하지 않는다. 그래서 과세소득이 경제적 이윤과 달라진다.","c":"상","v":1},"세무사2026_63-07-5":{"w":"감가상각이 경제적 감가와 같고 한계투자의 자금 비용인 이자가 공제되면 과세소득이 정상 수익을 뺀 초과이윤에 가까워져 법인세를 순수한 경제적 이윤에 대한 과세로 볼 수 있다.","c":"중","v":1},"세무사2026_63-08-2":{"w":"법인세 찬성론은 법인이 주주와 별개로 독자적 의사결정과 사회적 영향력을 가진 실체라는 법인실재설을 근거로 든다.","c":"상","v":1},"세무사2026_63-08-3":{"w":"법인은 유한책임과 사회 기반시설 등 사회가 주는 혜택을 누리므로 그에 대한 대가로 과세해야 한다는 것이 법인세 찬성론의 논거다.","c":"상","v":1},"세무사2026_63-08-4":{"w":"법인세율과 공제·감면은 투자·고용·배당 같은 법인의 행동을 유도하는 정책 수단으로 쓰인다.","c":"상","v":1},"세무사2026_63-08-5":{"w":"법인세가 없으면 법인에 유보된 이윤은 배당될 때까지 개인소득세 과세가 미뤄지므로 법인세가 유보이윤에 대한 과세 장치가 된다.","c":"상","v":1},"세무사2026_63-10-1":{"w":"우리나라 부가가치세는 1977년 도입 이후 과세 대상을 넓혀 사업 전반의 재화와 용역으로 확대되어 왔다.","c":"중","v":1},"세무사2026_63-10-2":{"w":"법인세율은 각국의 경제 상황·역사·조세 전통에 따라 달라 국가마다 다르다.","c":"상","v":1},"세무사2026_63-10-3":{"w":"법인세와 배당소득세의 이중과세를 줄이려고 소득세법 제56조의 배당세액공제를 두고 있다.","c":"상","v":1},"세무사2026_63-10-4":{"w":"지방소비세는 부가가치세 납부세액의 일부를 지방세로 배분하는 세목이고 지방소득세는 소득세와 법인세를 과세표준으로 하는 지방세다(지방세법).","c":"상","v":1},"세무사2026_63-12-1":{"w":"비례소득세는 대체효과로 노동을 줄이고 정상재인 여가의 소득효과로 노동을 늘리므로 두 효과의 상대적 크기가 총노동공급의 증감을 정한다.","c":"상","v":1},"세무사2026_63-12-2":{"w":"소득효과가 대체효과보다 크면 노동공급이 줄어드는 구간이 생겨 노동공급곡선이 후방굴절한다.","c":"상","v":1},"세무사2026_63-12-4":{"w":"여가가 열등재이면 비례소득세의 대체효과와 소득효과가 모두 노동공급을 줄인다.","c":"상","v":1},"세무사2026_63-12-5":{"w":"정액세는 상대가격을 바꾸지 않고 실질소득만 줄인다. 열등재인 여가가 늘어나므로 노동공급이 감소한다.","c":"상","v":1},"세무사2026_63-16-2":{"w":"배당무관련성(배당무의미) 정리는 세금과 거래비용이 없고 정보가 완전한 자본시장이라는 비현실적 가정에서 도출된 결론이다.","c":"상","v":1},"세무사2016_53-05-1":{"w":"자산과세는 납세의무자가 소유자이지만 과세 기준이 사람이 아닌 물건 자체이므로 대물세로 분류한다.","c":"상","v":1},"세무사2016_53-05-2":{"w":"자산수익률이 노동수익률보다 높으면 자산소득 비중이 큰 고소득층의 몫이 커진다. 자산과세를 강화하면 이 격차가 줄어 불평등이 완화된다.","c":"상","v":1},"세무사2016_53-05-3":{"w":"자산이 특정 지역에 몰려 있으므로 자산과세를 지방세의 중심으로 삼으면 자산이 많은 지역만 세수가 커져 지역 간 재정 격차가 커진다.","c":"상","v":1},"세무사2016_53-05-5":{"w":"재산은 경제적 능력을 보여 주므로 능력원칙에 부합하고 재산세는 지방공공서비스의 혜택이 재산가치에 반영되는 점에서 편익원칙에도 부합한다고 설명한다.","c":"중","v":1},"세무사2017_54-15-1":{"w":"부가가치세 세수가 가장 크다는 서술은 2016년 결산 기준으로도 소득세가 더 컸던 것으로 알려져 있고 현재는 소득세 세수가 더 많다. 통계 원문을 확인하지 못했다.","c":"하","v":1},"세무사2017_54-15-3":{"w":"부가가치세는 가격에 포함되어 간접적으로 부담하므로 소득세처럼 납세자가 직접 체감하는 조세저항이 작다.","c":"상","v":1},"세무사2017_54-15-4":{"w":"영세율은 매출에 0% 세율을 적용하고 매입세액은 환급하므로 부가가치세 부담이 완전히 사라지는 완전면세다.","c":"상","v":1},"세무사2017_54-15-5":{"w":"부가가치세는 재화와 용역의 생산·유통 각 단계에서 새로 창출된 부가가치를 과세대상으로 한다.","c":"상","v":1},"세무사2021_58-01-1":{"w":"각 단계에서 추가된 부가가치에만 과세하므로 기업이 수직적으로 합쳐도 세부담이 같아 수직적 통합을 부추기지 않는다.","c":"상","v":1},"세무사2021_58-01-2":{"w":"영세율은 수출 단계의 매출세액을 0으로 하고 앞 단계에서 낸 매입세액을 환급하므로 수출품에 붙은 조세를 완전히 돌려준다.","c":"상","v":1},"세무사2021_58-01-3":{"w":"소비형 부가가치세는 자본재 구입비를 구입 연도에 전액 공제하므로 투자에 대한 세부담이 없어 투자를 촉진한다.","c":"상","v":1},"세무사2021_58-01-4":{"w":"매입세액공제방식은 거래 상대방이 세금계산서로 서로의 거래를 확인하게 하므로 매출 누락 같은 탈세를 억제한다.","c":"상","v":1},"세무사2021_58-13-1":{"w":"공급탄력성이 0이면 공급량이 세금에 반응하지 않아 거래량이 변하지 않으므로 초과부담이 없다.","c":"상","v":1},"세무사2021_58-13-3":{"w":"부동산 취득에 대한 조세는 지방세법상 지방세인 취득세다.","c":"상","v":1},"세무사2021_58-13-4":{"w":"재산세(지방세법 제105조)와 종합부동산세(종합부동산세법)는 모두 보유 단계의 과세다.","c":"상","v":1},"세무사2021_58-13-5":{"w":"양도소득세는 소득세법 제94조의 양도소득, 곧 부동산 등을 양도하여 생기는 차익에 부과하는 국세다.","c":"상","v":1},"세무사2022_59-01-1":{"w":"단일세율이면 소비 비중이 큰 저소득층의 소득 대비 세부담이 더 커서 부가가치세는 역진적이다.","c":"상","v":1},"세무사2022_59-01-2":{"w":"부가가치세는 생산·유통의 각 거래단계에서 창출된 부가가치에 과세한다.","c":"상","v":1},"세무사2022_59-01-3":{"w":"부가가치세법 제21조에 따라 재화의 수출에는 영세율을 적용한다.","c":"상","v":1},"세무사2022_59-01-4":{"w":"부가가치세법 제37조에 따라 납부세액은 매출세액에서 매입세액을 공제해 계산하는 전단계세액공제방식이다.","c":"상","v":1},"세무사2026_63-09-4":{"w":"순소득형 부가가치세는 총수입에서 중간투입물 구입비를 빼고 자본재 감가상각비도 추가로 빼서 과세한다. 자본재 구입비 전액을 빼는 것은 소비형이다.","c":"상","v":1},"세무사2022_59-31-5":{"w":"공공사업은 이윤 극대화가 목적이 아니고 시장이 불완전하거나 왜곡된 경우가 많아 시장가격 대신 사회적 기회비용을 나타내는 잠재가격으로 평가해야 한다.","c":"상","v":1},"세무사2022_59-39-3":{"w":"할인율은 자금을 다른 곳에 썼을 때 얻는 기간당 수익, 곧 자금의 기회비용으로 정해야 현재가치법의 평가가 올바르다.","c":"상","v":1},"세무사2023_60-39-1":{"w":"할인율이 높으면 먼 미래의 편익은 현재가치가 크게 줄어드므로 편익이 초기에 몰린 사업이 상대적으로 유리하다.","c":"상","v":1},"세무사2023_60-39-2":{"w":"불완전경쟁에서는 가격이 한계비용을 넘어 기회비용을 제대로 나타내지 못하므로 잠재가격(그림자가격)을 쓴다.","c":"상","v":1},"세무사2023_60-39-3":{"w":"공공사업으로 가격이 내리면 소비자잉여가 늘고 이는 사업의 사회적 편익이므로 편익에 포함한다.","c":"상","v":1},"세무사2023_60-39-5":{"w":"편익을 화폐로 측정하기 어려우면 같은 목표를 달성하는 대안 중 비용이 가장 낮은 것을 찾는 비용효과분석을 쓴다.","c":"상","v":1},"세무사2025_62-31-3":{"w":"생산량이 변하지 않으면 공공사업이 민간 소비를 대체한 것이므로 소비자가 지불하던 시장가격이 포기한 편익의 크기다.","c":"상","v":1},"세무사2025_62-32-1":{"w":"실질적 편익은 최종소비자가 얻어 사회후생을 늘리는 편익이고 가격 변화에 따른 소득 이전인 금전적 편익과 구별한다.","c":"상","v":1},"세무사2025_62-32-3":{"w":"확실성등가는 불확실한 수익과 같은 효용을 주는 확실한 금액이므로 위험이 있는 공공사업의 편익을 평가할 때 쓴다.","c":"하","v":1},"세무사2025_62-32-4":{"w":"시장이자율이 사회적 할인율보다 높으면 높은 할인율 때문에 미래 편익의 현재가치가 작아져 사업의 경제성이 낮게 평가될 수 있다.","c":"상","v":1},"세무사2025_62-32-5":{"w":"시장 가격이 없는 편익은 여행비용법·헤도닉 가격법 등으로 소비자의 관찰된 행동에서 간접적으로 추정한다.","c":"상","v":1},"세무사2016_53-06-1":{"w":"공공재의 편익이 미치는 공간적 범위가 전국이면 중앙정부가 지역에 한정되면 지방정부가 공급해야 편익과 비용이 일치한다(오우츠의 분권화 정리).","c":"상","v":1},"세무사2016_53-06-2":{"w":"조세부담과 편익이 지역 안에서 연결되는 공공재는 주민이 비용과 편익을 비교해 선택하므로 지방정부가 공급하기 알맞다.","c":"중","v":1},"세무사2016_53-06-3":{"w":"무임승차 가능성이 높은 공공재는 자발적 부담으로 재원을 모으기 어려워 강제 징수 능력이 있는 중앙정부가 공급하는 것이 낫다는 설명이다.","c":"중","v":1},"세무사2016_53-06-4":{"w":"국방과 외교는 편익이 전국에 미치는 순수공공재라 중앙정부가 맡고 쓰레기 수거와 거리청소는 편익이 지역에 한정되어 지방정부가 맡는다.","c":"상","v":1},"세무사2016_53-07-1":{"w":"정액교부금은 지방정부 수입으로 들어가 지출을 크게 늘리고 주민 소득 증가는 일부만 공공지출로 쓰이는 끈끈이 효과(flypaper effect)가 나타난다.","c":"상","v":1},"세무사2016_53-07-2":{"w":"주민은 교부금이 들어오면 공공재 생산비가 내려간 것처럼 인식하는 경향이 있고 이를 재정착각이라 한다.","c":"상","v":1},"세무사2016_53-07-3":{"w":"재정착각에서는 주민이 교부금 때문에 공공재 한계조세가격이 낮아졌다고 착각해 더 많은 공공재를 요구한다.","c":"상","v":1},"세무사2016_53-07-5":{"w":"관료가 예산을 극대화하려는 동기를 가지면 교부금 사실을 알리지 않아 재정착각이 생기기 쉬우므로 재정착각과 관련이 있다(니스카넨 모형).","c":"상","v":1},"세무사2017_54-22-1":{"w":"국고보조금은 보조금 관리에 관한 법률에 따라 지정된 사업에만 쓰도록 용도가 정해진 조건부 보조금이다.","c":"상","v":1},"세무사2017_54-22-2":{"w":"보통교부세는 지방교부세법에 따라 용도를 정하지 않고 교부하는 일반재원이므로 무조건부 보조금이다.","c":"상","v":1},"세무사2017_54-22-3":{"w":"무조건부 보조금은 소득효과로 쓰이므로 일부는 주민의 조세부담을 줄이는 데 쓸 수 있다.","c":"상","v":1},"세무사2017_54-22-4":{"w":"비대응보조금은 지방정부 수입 증가의 소득효과로 쓰이므로 일부가 주민의 세부담 경감을 통해 사적재 소비를 늘린다.","c":"상","v":1},"세무사2021_58-19-1":{"w":"지방정부는 지역 여건에 맞는 제도를 독자적으로 도입하기 쉽다는 것이 분권의 장점이다.","c":"상","v":1},"세무사2021_58-19-2":{"w":"지방정부는 주민과 가깝기 때문에 지역주민의 선호를 행정에 반영하기 쉽다.","c":"상","v":1},"세무사2021_58-19-3":{"w":"지방정부끼리 주민을 두고 경쟁하면 공공서비스 생산의 효율성이 높아진다.","c":"상","v":1},"세무사2021_58-19-5":{"w":"지역마다 세원이 달라 재정능력 격차가 있으면 분권이 이를 더 키워 지역 간 격차가 벌어질 수 있다.","c":"상","v":1},"세무사2021_58-28-1":{"w":"티부 모형은 주민이 자신의 선호에 맞는 지역으로 비용 없이 이동할 수 있다는 완전한 이동성을 가정한다.","c":"상","v":1},"세무사2021_58-28-2":{"w":"티부 모형은 지방정부의 공공재 공급이 다른 지역에 파급효과(외부성)를 주지 않는다고 가정한다.","c":"상","v":1},"세무사2021_58-28-3":{"w":"티부 모형은 주민이 선호에 맞는 지역을 고를 수 있도록 서로 다른 재정 프로그램을 가진 지역의 수가 충분히 많다고 가정한다.","c":"상","v":1},"세무사2021_58-28-4":{"w":"티부 모형은 주민이 각 지역의 공공재와 세금에 대해 완전한 정보를 가진다고 가정한다.","c":"상","v":1},"세무사2022_59-04-1":{"w":"무조건부 보조금은 상대가격은 그대로 두고 지방정부의 실질소득만 늘리므로 사적재와 공공서비스 선택에서 소득효과만 일으킨다.","c":"상","v":1},"세무사2022_59-04-2":{"w":"대응보조금은 공공서비스의 상대가격을 낮춰 대체효과를 일으키며 외부성이 없는 경우 공공서비스를 효율 수준보다 많이 소비하게 하므로 비효율을 낳는다.","c":"상","v":1},"세무사2022_59-04-4":{"w":"끈끈이 효과는 보조금이 들어오면 주민 소득 증가 때보다 지방정부 지출이 더 크게 늘어나는 현상이다.","c":"상","v":1},"세무사2022_59-04-5":{"w":"비대응보조금은 지방 수입을 늘려 주민의 세부담을 덜어 주므로 일부가 사적재 소비 증가로 이어질 수 있다.","c":"상","v":1},"세무사2023_60-18-1":{"w":"우리나라 지방세 규모는 국세의 약 1/3 수준이어서 국세보다 작다.","c":"중","v":1},"세무사2023_60-18-3":{"w":"조정교부금은 광역자치단체가 관할 기초자치단체에 재원을 배분하는 지방재정조정제도로 상위 지방자치단체가 하위 지방자치단체를 지원하는 제도다.","c":"상","v":1},"세무사2023_60-18-4":{"w":"지방교부세는 지방자치단체가 자율적으로 쓸 수 있는 일반재원이어서 지방교부세법상 용도가 정해져 있지 않다.","c":"상","v":1},"세무사2023_60-18-5":{"w":"취득세와 재산세 등 부동산 관련 세목의 비중이 커서 부동산 경기변동이 지방세수의 규모와 안정성에 영향을 준다.","c":"상","v":1},"세무사2023_60-19-2":{"w":"지방정부 간 경쟁은 주민을 끌기 위해 공공서비스를 효율적으로 생산하도록 유도한다.","c":"상","v":1},"세무사2023_60-19-3":{"w":"티부 모형은 지방공공재의 재원을 주민의 재산가치에 비례하는 재산세로 조달한다고 보는 것이 일반적인 설명이다.","c":"중","v":1},"세무사2023_60-19-4":{"w":"표준 이론은 분권화가 주민 선호 정보를 얻는 비용을 줄인다고 보므로 문장이 어떤 비교 맥락에서 맞는지 확인하지 못했다.","c":"하","v":1},"세무사2023_60-19-5":{"w":"오우츠의 분권화 정리는 공공재 공급비용이 중앙과 지방에서 같으면 지방정부가 지역 선호에 맞게 공급하는 편이 효율적이라는 내용이다.","c":"상","v":1},"세무사2024_61-17-1":{"w":"조건부 비대응교부금은 지방정부 소득을 늘리면서 공공재 구입을 유도하므로 공공재 소비와 주민 후생이 늘어난다.","c":"상","v":1},"세무사2024_61-18-1":{"w":"티부 모형은 지방공공재의 재원을 주민의 재산가치에 비례하는 재산세로 조달한다고 보는 것이 일반적인 설명이다.","c":"중","v":1},"세무사2024_61-18-2":{"w":"분권화로 지역별 공공서비스 구성이 달라지고 주민이 자유롭게 이동하면 선호에 맞는 지역을 선택해 후생이 커진다(티부 모형).","c":"상","v":1},"세무사2024_61-18-3":{"w":"한 지역의 공공재 편익이 다른 지역으로 흘러넘치는 외부성이 있으면 지방정부가 그 편익을 고려하지 않아 공공재 공급이 비효율적으로 된다.","c":"상","v":1},"세무사2024_61-18-4":{"w":"국방은 편익이 전국에 미치는 외부성이 있고 우편은 규모의 경제가 있어 중앙정부가 공급하는 편이 효율적이다.","c":"상","v":1},"세무사2024_61-19-4":{"w":"지방교부세는 용도 제한이 없는 일반재원이어서 용도가 지정된 국고보조금보다 지방정부의 자율적 재정운영에 알맞다.","c":"상","v":1},"세무사2025_62-14-2":{"w":"오우츠의 분권화 정리는 비용이 같으면 지역공공재를 중앙정부 대신 지방정부가 공급하는 편이 효율적일 수 있다고 본다.","c":"상","v":1},"세무사2025_62-14-3":{"w":"분권화로 지방정부는 지역 여건에 맞는 정책을 시도할 수 있다.","c":"상","v":1},"세무사2025_62-14-4":{"w":"지역별로 공공재 구성이 다르고 투표자가 이동해 고를 수 있으면 선호에 맞는 선택으로 후생이 커진다(티부 모형).","c":"상","v":1},"세무사2025_62-14-5":{"w":"티부 모형은 주민이 발에 의한 투표로 자신의 선호에 맞는 지역을 선택하면 지역공공재의 배분이 효율적으로 이루어진다고 설명한다.","c":"상","v":1},"세무사2025_62-17-2":{"w":"대응교부금은 공공재의 상대가격을 낮춰 대체효과를 일으키고 외부성이 없으면 공공재를 효율 수준보다 많이 소비하게 하므로 비효율적이다.","c":"상","v":1},"세무사2025_62-17-3":{"w":"무조건부 교부금은 상대가격을 바꾸지 않고 소득효과만 일으키므로 가격 왜곡에 따른 비효율이 생기지 않는다.","c":"상","v":1},"세무사2025_62-17-4":{"w":"국고보조금은 보조금 관리에 관한 법률에 따라 용도가 정해진 조건부 교부금의 성격을 가진다.","c":"상","v":1},"세무사2025_62-17-5":{"w":"같은 금액이면 무조건부 교부금은 상대가격을 왜곡하지 않고 소득만 늘려 주므로 지방정부가 가장 높은 무차별곡선에 도달해 대응교부금보다 후생이 높다.","c":"상","v":1},"세무사2016_53-22-1":{"w":"한계비용가격설정은 가격이 평균비용보다 낮아 손실이 나므로 일반 세원으로 손실을 메운다.","c":"상","v":1},"세무사2016_53-22-2":{"w":"평균비용가격설정(P = AC)은 평균비용으로 공공서비스 가격을 정해 손실 없이 자원을 확보하는 방식이다.","c":"상","v":1},"세무사2016_53-22-3":{"w":"사용량에 따라 단가를 달리하는 요금체계는 소비자마다 다른 가격을 매기는 가격차별 방식이다.","c":"상","v":1},"세무사2016_53-22-4":{"w":"이부가격제는 기본요금을 정액으로 내게 하고 사용량에 비례한 사용요금을 추가로 받는 요금제다.","c":"상","v":1},"세무사2016_53-32-3":{"w":"린달 균형에서는 모두 같은 양을 소비하지만 각자의 한계편익에 따라 서로 다른 가격(조세)을 부담하며 그 합이 한계비용과 같다.","c":"상","v":1},"세무사2017_54-26-5":{"w":"사무엘슨 조건 등 최적조건을 충족하면 순수공공재와 순수사적재를 함께 효율적으로 배분할 수 있다는 것이 이론의 결론이다.","c":"상","v":1},"세무사2017_54-27-1":{"w":"클라크세에서 각자가 내는 세금은 자신이 밝힌 선호가 아니라 다른 사람들이 밝힌 선호가 결과를 바꾸는 정도로 정해지므로 자기 표출이 자기 부담을 바꾸지 못한다.","c":"상","v":1},"세무사2017_54-27-2":{"w":"수요표출메커니즘은 선호를 정직하게 밝히게 하는 유인을 설계해 사무엘슨 조건을 만족하는 공공재 공급량을 찾아낸다.","c":"상","v":1},"세무사2017_54-27-3":{"w":"클라크세에서는 다른 사람의 표출과 관계없이 진실한 선호를 밝히는 것이 우월전략이므로 선호를 숨기는 무임승차가 생기지 않는다.","c":"상","v":1},"세무사2017_54-27-5":{"w":"클라크세(클라크-그로브스 메커니즘)는 수요표출메커니즘의 대표적인 예다.","c":"상","v":1},"세무사2021_58-20-4":{"w":"규모의 경제가 있어도 가격을 한계비용과 같게 정하면 생산량이 효율적이다. 다만 한계비용이 평균비용보다 낮아 손실이 생겨 별도로 메워야 한다.","c":"상","v":1},"세무사2022_59-27-1":{"w":"클럽재는 배제가 가능하고 이용자가 늘면 혼잡이 생기는 재화이므로 부분적으로 경합성을 가진다.","c":"상","v":1},"세무사2022_59-27-2":{"w":"순수공공재는 한 사람이 더 소비해도 다른 사람의 소비가 줄지 않는 비경합적 재화여서 소비자 추가의 한계비용이 0이다.","c":"상","v":1},"세무사2022_59-27-3":{"w":"사무엘슨 조건에 따르면 공공재의 최적 공급은 개인별 한계편익(한계대체율)의 합이 한계비용(한계변환율)과 같을 때다.","c":"상","v":1},"세무사2022_59-27-4":{"w":"클라크세에서는 진실한 선호를 밝히는 것이 어떤 경우에도 불리하지 않은 우월전략이다.","c":"상","v":1},"세무사2023_60-16-1":{"w":"규모의 경제가 있으면 평균비용이 계속 줄어서 한 기업이 전부 생산하는 편이 여러 기업이 나누어 생산할 때보다 총비용이 낮다.","c":"상","v":1},"세무사2023_60-26-1":{"w":"비경합성이 강할수록 소비자가 늘어도 추가 비용이 들지 않고 편익만 더해지므로 공공재의 사회적 편익은 개인 편익을 수직으로 합한 만큼 커진다.","c":"중","v":1},"세무사2024_61-16-1":{"w":"램지가격설정은 수요가 비탄력적인 필수품일수록 가격을 한계비용보다 높게 매기므로 저소득층 부담이 커지는 분배 문제가 생긴다.","c":"상","v":1},"세무사2024_61-27-5":{"w":"공공재 비용분담 게임에서 반대가 두 사람 모두의 우월전략이므로 서로 반대하는 것이 유일한 내쉬균형이다.","c":"상","v":1},"세무사2025_62-19-1":{"w":"가격을 한계비용과 같게 정하면 소비의 한계편익과 생산의 한계비용이 일치해 공급량이 효율적이다.","c":"상","v":1},"세무사2025_62-19-2":{"w":"평균비용이 감소하는 구간에서는 한계비용이 평균비용보다 낮아 한계비용가격으로는 총수입이 총비용에 못 미쳐 손실이 생긴다.","c":"상","v":1},"세무사2025_62-19-3":{"w":"평균비용가격설정(P = AC)은 가격이 한계비용보다 높아 공급량이 효율적 수준보다 적으므로 비효율적이다.","c":"상","v":1},"세무사2025_62-19-4":{"w":"가격을 평균비용과 같게 정하면 총수입이 총비용과 같아 손실이 나지 않는다.","c":"상","v":1},"세무사2025_62-21-2":{"w":"순수공공재는 비배제성 때문에 대가를 받지 못해 가격을 설정할 수 없고 시장에 맡기면 과소공급되므로 시장실패의 원인이 된다.","c":"상","v":1},"세무사2026_63-18-1":{"w":"규모의 경제가 있어도 가격을 한계비용과 일치시키면 소비의 한계편익과 한계비용이 같아 효율적 자원배분이 이루어지고 손실은 별도로 보전한다.","c":"상","v":1},"세무사2026_63-18-2":{"w":"단기에 설비 용량이 한정되어 초과수요가 있으면 한계비용에 용량의 희소성을 나타내는 경제적 지대를 더해야 수요를 용량에 맞게 배분한다.","c":"상","v":1},"세무사2026_63-18-4":{"w":"평균비용에 맞춰 가격을 정하면 비용이 늘어도 가격으로 보전되므로 공급자가 비용을 줄일 유인이 없다.","c":"상","v":1},"세무사2026_63-18-5":{"w":"램지가격은 수요가 비탄력적인 필수품의 가격을 한계비용보다 더 높게 정하므로 저소득층에게 불공평한 분배 문제를 낳을 수 있다.","c":"상","v":1},"세무사2016_53-16-1":{"w":"램지 규칙은 필요한 조세수입을 거두면서 초과부담을 최소로 하는 물품세율 구조를 찾는 최적과세 규칙이다.","c":"상","v":1},"세무사2016_53-16-2":{"w":"램지의 원래 규칙(등비례 감소 규칙)은 교차탄력성이 0일 때 모든 재화의 보상수요 감소율이 같아지도록 세율을 정하라는 것이다.","c":"상","v":1},"세무사2016_53-16-3":{"w":"최적 물품세는 재화마다 조세수입 1원당 후생비용(한계초과부담)이 같아지도록 세율을 정하는 것이다.","c":"상","v":1},"세무사2016_53-16-4":{"w":"램지 규칙에 따르면 수요가 비탄력적인 필수재에 높은 세율을 적용해야 초과부담이 작아진다.","c":"상","v":1},"세무사2017_54-07-5":{"w":"완전보완재는 상대가격이 변해도 소비 비율이 변하지 않아 대체효과가 없으므로 과세해도 초과부담이 생기지 않는다.","c":"상","v":1},"세무사2017_54-11-1":{"w":"초과부담은 상대가격 변화에 따른 대체효과로 생기고 소득효과는 후생 손실이 아니라 조세 부담 자체이므로 초과부담과 관련이 없다.","c":"상","v":1},"세무사2017_54-11-2":{"w":"초과부담은 소득효과를 제거한 보상수요곡선으로 측정해야 후생 손실을 정확히 잴 수 있다(보통수요곡선으로 재면 오차가 생긴다).","c":"상","v":1},"세무사2017_54-11-3":{"w":"정액세는 납세자의 행동에 따라 세액이 변하지 않아 상대가격을 바꾸지 않으므로 왜곡과 초과부담이 없다.","c":"상","v":1},"세무사2017_54-11-5":{"w":"이자소득세가 없고 노동공급이 고정된 2기간 모형에서 근로소득세는 정액세처럼 소득효과만 일으키므로 대체효과에 의한 초과부담이 없다.","c":"중","v":1},"세무사2017_54-14-1":{"w":"최적소득세 이론은 효율(왜곡 최소화)과 공평(재분배)을 함께 고려해 세율 구조를 정한다.","c":"상","v":1},"세무사2017_54-14-2":{"w":"한계소득세율이 1보다 작게 유지되어 소득을 더 벌면 세후소득이 늘어나므로 노동공급을 늘리는 유인이 남는다.","c":"중","v":1},"세무사2017_54-14-3":{"w":"최적소득세 이론(미리스)에서는 최고소득자에게 한계세율을 0으로 두어도 왜곡 없이 재분배 목표를 달성할 수 있다는 결과가 나온다.","c":"상","v":1},"세무사2017_54-14-4":{"w":"한계소득세율이 1이면 추가 소득이 전부 세금이 되어 세후소득이 늘지 않으므로 최적 한계세율은 항상 1보다 작다.","c":"상","v":1},"세무사2017_54-35-1":{"w":"이부가격에서 고정요금과 사용요금의 비중은 소비자가 고정요금에 얼마나 민감하게 반응하느냐(탄력성)에 따라 정해진다.","c":"상","v":1},"세무사2017_54-35-2":{"w":"탄력성이 큰 부문에서 덜 거두고 작은 부문에서 더 거두는 램지의 역탄력성 규칙과 같은 원리다.","c":"상","v":1},"세무사2017_54-35-3":{"w":"고정수수료에 대한 탄력성이 크면 고정수수료를 높이면 가입자가 이탈하므로 낮게 정하고 대신 사용요금을 높이는 것이 효율적이라는 램지 원리다.","c":"중","v":1},"세무사2017_54-35-4":{"w":"이부가격은 고정요금과 사용요금의 두 수단을 쓰므로 하나의 단일요금보다 한계비용가격에 가까워져 효율성이 높다.","c":"상","v":1},"세무사2021_58-02-3":{"w":"초과부담은 조세로 상대가격이 변해 소비자가 대체재로 옮겨 가는 대체효과 때문에 생긴다.","c":"상","v":1},"세무사2021_58-03-1":{"w":"최적 물품세는 필요한 세수를 거두면서 초과부담을 최소화하는 과세, 곧 램지 규칙을 따르는 과세다.","c":"상","v":1},"세무사2021_58-03-2":{"w":"물품세 때문에 소비자 지불가격과 생산자 수취가격 사이에 쐐기(조세)가 생겨 한계편익과 한계비용이 어긋나서 초과부담이 생긴다.","c":"상","v":1},"세무사2021_58-03-3":{"w":"수요의 가격탄력성이 클수록 같은 세율에서 거래량 감소가 커서 초과부담이 커진다.","c":"상","v":1},"세무사2021_58-03-4":{"w":"보상수요의 가격탄력성이 0이면 가격 상승에도 보상수요량이 변하지 않으므로 대체효과가 없어 초과부담이 없다.","c":"상","v":1},"세무사2023_60-02-5":{"w":"정액세는 행동에 따라 세액이 달라지지 않아 대체효과가 없으므로 초과부담이 없다.","c":"상","v":1},"세무사2023_60-03-1":{"w":"램지 규칙은 초과부담 최소화라는 효율성 기준만 따지며 분배의 형평성은 고려하지 않는다.","c":"상","v":1},"세무사2023_60-03-2":{"w":"램지 규칙의 단순한 형태(역탄력성 규칙)는 재화 간 교차탄력성이 0, 곧 재화가 서로 독립적일 때 성립한다.","c":"상","v":1},"세무사2023_60-03-3":{"w":"램지 규칙은 각 재화에서 조세수입 1원당 한계초과부담이 같아지도록 세율을 정하는 과정에서 도출된다.","c":"상","v":1},"세무사2023_60-03-5":{"w":"역탄력성 규칙에 따라 수요의 가격탄력성이 작은 재화에 높은 세율을 부과해야 초과부담이 최소가 된다.","c":"상","v":1},"세무사2024_61-03-1":{"w":"수요의 가격탄력성이 클수록 과세에 따른 거래량 감소가 커서 초과부담이 커진다.","c":"상","v":1},"세무사2024_61-03-3":{"w":"정액세는 상대가격을 바꾸지 않아 대체효과가 없으므로 초과부담이 없다.","c":"상","v":1},"세무사2024_61-03-4":{"w":"완전보완재는 대체효과가 없어 한 재화에 과세해도 소비 조합이 변하지 않으므로 초과부담이 없다.","c":"상","v":1},"세무사2024_61-03-5":{"w":"초과부담은 소득효과를 제거한 보상수요곡선으로 재어야 정확하다.","c":"상","v":1},"세무사2025_62-04-1":{"w":"물품세로 소비자의 한계대체율과 생산의 한계변환율이 달라지면 파레토 효율 조건(MRS = MRT)이 깨져 초과부담이 생긴다.","c":"상","v":1},"세무사2025_62-04-2":{"w":"물품세 때문에 소비자 지불가격과 생산자 수취가격이 달라져 한계편익과 한계비용이 어긋나므로 초과부담이 생긴다.","c":"상","v":1},"세무사2025_62-04-4":{"w":"램지 규칙은 조세수입 1원당 한계초과부담이 모든 재화에서 같아지도록 세율을 정하라는 것이다.","c":"상","v":1},"세무사2025_62-04-5":{"w":"초과부담은 소비자와 생산자의 후생 감소분 합계에서 정부가 거둔 조세수입을 뺀 값이다(조세수입은 이전일 뿐이다).","c":"상","v":1},"세무사2026_63-04-1":{"w":"조세로 줄어든 소비자잉여와 생산자잉여의 합에서 조세수입을 빼면 사회 전체의 순손실인 초과부담이 된다.","c":"상","v":1},"세무사2026_63-04-2":{"w":"조세가 상대가격을 바꾸면 민간의 소비와 생산 선택이 왜곡되어 초과부담이 발생한다.","c":"상","v":1},"세무사2026_63-04-3":{"w":"초과부담을 정확히 재려면 소득효과를 뺀 보상수요곡선을 사용해야 한다.","c":"상","v":1},"세무사2026_63-04-4":{"w":"초과부담은 세율의 제곱에 비례하고 수요의 가격탄력성에도 비례하므로 세율이 높고 탄력성이 클수록 커진다.","c":"상","v":1},"세무사2016_53-19-1":{"w":"누진 개인소득세는 고소득층의 세부담을 더 크게 하여 세후 소득 격차를 줄이므로 저소득층 소득을 직접 늘리지 않아도 분배를 개선한다.","c":"상","v":1},"세무사2016_53-19-2":{"w":"사치품은 주로 고소득층이 소비하므로 사치품 소비세는 고소득층이 세금을 더 부담해 소득분배를 개선한다.","c":"상","v":1},"세무사2016_53-19-4":{"w":"법인세가 가격에 얹혀 소비자에게 전가되면 소득 대비 소비 비중이 큰 저소득층의 부담이 상대적으로 커져 분배가 악화된다.","c":"중","v":1},"세무사2016_53-19-5":{"w":"자산소득이 고소득층에 몰려 있으면 자산소득에 높은 세율을 적용해 상위 계층의 세후 소득을 줄이므로 분배가 개선된다.","c":"상","v":1},"세무사2016_53-20-1":{"w":"연금제도는 노후 준비의 중요성을 알리는 인식효과가 있어서 민간저축을 늘린다.","c":"상","v":1},"세무사2016_53-20-2":{"w":"연금보험료를 내면 가처분소득이 줄어 그만큼 민간저축이 감소한다.","c":"상","v":1},"세무사2016_53-20-3":{"w":"연금급여를 받을 것으로 기대하면 자산이 늘어난 것과 같아 노후 대비 저축을 줄이므로 자산대체효과는 민간저축을 감소시킨다.","c":"상","v":1},"세무사2016_53-20-4":{"w":"상속효과는 연금으로 노후가 보장되면 자녀에게 물려줄 재산을 더 모으려 하는 효과여서 민간저축을 늘린다.","c":"상","v":1},"세무사2016_53-39-1":{"w":"교육바우처는 사립학교의 학비 부담을 줄여 주므로 사립초등학교 지원율을 높일 수 있다.","c":"중","v":1},"세무사2016_53-39-2":{"w":"바우처를 쓰면 사립학교도 선택할 수 있어서 사립과 공립 사이의 선택의 폭이 넓어진다.","c":"중","v":1},"세무사2016_53-39-3":{"w":"바우처로 사립학교 수요가 늘면 사립초등학교를 새로 세울 유인이 커져 신설이 늘어날 수 있다.","c":"중","v":1},"세무사2016_53-39-4":{"w":"학생을 두고 사립과 공립이 경쟁하게 되므로 학교 간 경쟁이 높아진다.","c":"중","v":1},"세무사2017_54-21-1":{"w":"앳킨슨 지수는 불평등 회피도(사회적 가치판단 모수)에 따라 값이 달라진다.","c":"상","v":1},"세무사2017_54-21-2":{"w":"로렌츠 곡선은 소득이 낮은 사람부터 누적한 인구 비율에 대해 그들이 차지하는 누적 소득 비율을 나타내는 곡선이다.","c":"상","v":1},"세무사2017_54-21-3":{"w":"지니계수는 로렌츠 곡선과 완전평등선(대각선) 사이 면적을 대각선 아래 삼각형 면적으로 나눈 값이다.","c":"상","v":1},"세무사2017_54-21-4":{"w":"지니계수는 모든 소득 쌍 사이의 평균적인 소득 격차를 평균소득으로 나눈 값이라는 평균소득격차 개념으로도 정의된다.","c":"상","v":1},"세무사2017_54-34-1":{"w":"두 로렌츠 곡선이 교차하면 어느 한쪽이 모든 구간에서 더 평등하지 않으므로 소득분배 평등도의 우열을 가릴 수 없다.","c":"상","v":1},"세무사2017_54-34-2":{"w":"로렌츠 곡선은 곡선의 위치로 평등한 정도의 순서만 보여 주는 서수적 평가다.","c":"중","v":1},"세무사2017_54-34-3":{"w":"로렌츠 곡선이 완전평등선인 대각선에 가까울수록 소득분배가 평등하다.","c":"상","v":1},"세무사2017_54-34-4":{"w":"로렌츠 곡선에서 대각선은 모든 구성원이 똑같은 소득을 가지는 균등분배를 뜻하며 이를 가장 평등한 분배의 기준으로 삼는다.","c":"상","v":1},"세무사2017_54-37-2":{"w":"적립방식 연금에서는 보험료를 낸 가입자가 자신의 몫을 적립하는데 장수한 사람이 단명한 사람의 적립금을 받는 등 같은 세대 안에서 구성원 사이에 부가 이전된다.","c":"중","v":1},"세무사2017_54-37-3":{"w":"연금급여를 기대하면 일찍 퇴직하는 퇴직효과가 생기고 노후 기간이 길어지므로 저축을 늘린다.","c":"상","v":1},"세무사2017_54-37-4":{"w":"연금제도는 노후 준비의 필요성을 알려 주는 인식효과가 있어서 개인저축을 늘린다.","c":"상","v":1},"세무사2017_54-37-5":{"w":"연금급여 기대는 자산을 늘리는 효과를 내므로 노후 대비 저축이 줄어드는 자산대체효과가 생긴다.","c":"상","v":1},"세무사2021_58-12-1":{"w":"보조금 B = a - tE이므로 a = 50만원 t = 0.2일 때 E = 250만원이면 B = 50 - 0.2 x 250 = 0이어서 보조금이 중단된다.","c":"상","v":1},"세무사2021_58-12-2":{"w":"B = a - tE에서 a = 50만원 t = 0.25이면 B > 0이 되려면 E < 50/0.25 = 200만원이어야 한다.","c":"상","v":1},"세무사2021_58-12-4":{"w":"부(-)의 소득세 형태의 보조금 B = a - tE에서 정부가 정할 수 있는 정책변수는 최저보장액 a와 보조금 삭감률 t다.","c":"상","v":1},"세무사2021_58-12-5":{"w":"다른 조건이 같을 때 a가 크면 모든 소득 수준에서 보조금이 커지고 보조금을 받는 소득 범위(a/t)도 넓어져 재분배 효과가 커진다.","c":"상","v":1},"세무사2021_58-31-2":{"w":"근로장려세제는 일하는 저소득 가구에 근로장려금을 지급해 생계를 돕고 근로를 유인하는 제도다(조세특례제한법 근로장려금).","c":"상","v":1},"세무사2021_58-31-3":{"w":"공공부조는 보험료가 아니라 국민이 낸 세금(일반재정)으로 저소득층을 지원하는 사회보장 프로그램이다.","c":"상","v":1},"세무사2021_58-31-4":{"w":"우리나라의 4대 사회보험인 국민연금 건강보험 고용보험 산재보험에 노인장기요양보험을 더해 사회보험을 운영한다.","c":"상","v":1},"세무사2021_58-31-5":{"w":"사회보험은 가입자가 낸 보험료를 기본 재원으로 한다.","c":"상","v":1},"세무사2021_58-33-2":{"w":"달튼의 평등지수는 평등분배 때의 후생 대비 실제 후생의 비율이어서 0과 1 사이이며 1에 가까울수록 소득이 평등하다.","c":"상","v":1},"세무사2021_58-38-2":{"w":"사람마다 효용함수가 달라도 사회가 정한 가치판단에 따라 바람직한 분배는 정할 수 있으므로 모든 사람이 같은 효용함수를 가진다는 가정이 필수는 아니다.","c":"중","v":1},"세무사2021_58-38-3":{"w":"벤담의 공리주의는 사회 구성원 효용의 합인 사회후생을 극대화하는 분배를 가장 바람직하다고 본다.","c":"상","v":1},"세무사2021_58-38-4":{"w":"효용함수가 사람마다 다르거나 사회후생함수가 효용 합 이외의 가치를 포함하면 균등하지 않은 분배가 사회후생을 극대화할 수 있다.","c":"중","v":1},"세무사2021_58-38-5":{"w":"효용함수가 소득의 한계효용 체감을 가정해야 소득을 고소득자에서 저소득자로 옮길 때 사회 전체의 효용이 늘어난다는 논리가 성립한다.","c":"상","v":1},"세무사2021_58-39-2":{"w":"공적연금은 강제 가입이어서 위험이 낮은 사람만 가입하는 역선택이 생기지 않는다.","c":"상","v":1},"세무사2021_58-39-3":{"w":"공적연금은 부과방식으로 운영하면 현재 가입자의 보험료로 급여를 지급하고 정부의 징세 능력이 뒷받침하므로 사적연금보다 적은 준비금으로 운영할 수 있다.","c":"상","v":1},"세무사2021_58-39-4":{"w":"사적연금은 가입자가 상품과 납입액을 고를 수 있어 공적연금의 획일적 급여 구조보다 다양한 요구에 맞추기 쉽다.","c":"상","v":1},"세무사2021_58-39-5":{"w":"공적연금은 전 국민이 보험료를 내고 위험을 함께 부담하는 강제 제도라 개인이 위험을 키우는 행동을 하거나 가입을 피할 여지가 줄어든다.","c":"중","v":1},"세무사2022_59-33-1":{"w":"앳킨슨 지수는 사회후생함수와 불평등 회피도라는 가치판단을 명시적으로 전제하고 불평등을 재는 지표다.","c":"상","v":1},"세무사2022_59-33-3":{"w":"앳킨슨 지수는 1 - (균등분배대등소득 / 평균소득)이므로 두 값이 같으면 0이다.","c":"상","v":1},"세무사2022_59-33-4":{"w":"앳킨슨 지수는 불평등 회피도에 따라 균등분배대등소득이 달라지므로 같은 분배 상태라도 값이 여러 가지로 나온다.","c":"상","v":1},"세무사2022_59-33-5":{"w":"균등분배대등소득은 0 이상 평균소득 이하이므로 앳킨슨 지수는 0과 1 사이의 값을 가진다.","c":"상","v":1},"세무사2022_59-37-1":{"w":"소득재분배정책의 목적은 로렌츠 곡선을 완전평등선인 대각선에 가깝게 만드는 것이다.","c":"상","v":1},"세무사2022_59-37-2":{"w":"상속세와 증여세는 부유한 사람에게서 세금을 거두어 부의 집중을 줄이는 세입 측면의 재분배정책이다.","c":"상","v":1},"세무사2022_59-37-3":{"w":"소득재분배 지출은 현금을 주는 방식과 의료 주거 같은 현물을 주는 방식으로 시행한다.","c":"상","v":1},"세무사2022_59-37-4":{"w":"로렌츠 곡선 지니계수 앳킨슨 지수는 어떤 분배를 불평등하다고 볼지 정하는 기준이 달라 평가에 가치판단이 개입된다.","c":"중","v":1},"세무사2023_60-32-1":{"w":"공리주의는 사회 구성원 효용의 합인 총체적 후생을 극대화하는 분배를 바람직하다고 본다.","c":"상","v":1},"세무사2023_60-32-2":{"w":"평등주의는 모든 사람에게 똑같이 분배하는 것을 정의로 본다.","c":"상","v":1},"세무사2023_60-32-3":{"w":"롤즈의 최소극대화 원칙은 가장 가난한 사람의 후생을 극대화하는 분배를 사회후생의 극대화로 본다.","c":"상","v":1},"세무사2023_60-32-4":{"w":"자유주의(자유지상주의)는 정부 간섭 없이 시장에서 결정된 분배를 정당하다고 본다.","c":"상","v":1},"세무사2023_60-33-5":{"w":"건강보험은 가입자와 사용자에게서 거둔 보험료와 정부 지원금을 재원으로 운영한다(국민건강보험법).","c":"상","v":1},"세무사2023_60-34-1":{"w":"특정 재화의 소비를 늘리는 것이 정책 목적일 때는 현물보조가 사용처를 정해 주므로 현금보조보다 목적 달성에 효율적이다.","c":"중","v":1},"세무사2023_60-34-2":{"w":"현물보조는 정부가 소비를 장려하려는 교육 의료 주거 같은 가치재를 대상으로 한다.","c":"상","v":1},"세무사2023_60-34-3":{"w":"현물보조는 재화를 직접 조달하고 전달하는 비용이 들어 현금보조보다 행정비용과 운영비용이 높다.","c":"상","v":1},"세무사2023_60-34-4":{"w":"규모의 경제가 있는 재화는 정부가 한꺼번에 구입하거나 생산하면 단위 비용이 낮아져 현물보조가 효율적이다.","c":"상","v":1},"세무사2023_60-35-1":{"w":"우리나라 사회보험은 국민연금 건강보험 고용보험 산재보험 노인장기요양보험의 5가지다.","c":"상","v":1},"세무사2023_60-35-2":{"w":"사회보험은 강제가입이어서 위험이 낮은 사람의 이탈로 생기는 역선택을 막는다.","c":"상","v":1},"세무사2023_60-35-4":{"w":"사회보험의 재원 조달은 보험료를 적립해 두었다가 급여에 쓰는 적립방식과 현재 보험료로 현재 급여를 지급하는 부과방식으로 나뉜다.","c":"상","v":1},"세무사2023_60-35-5":{"w":"국민연금은 연금이라는 현금급여가 원칙이고 건강보험은 요양급여라는 현물급여가 원칙이다.","c":"상","v":1},"세무사2023_60-36-1":{"w":"공적연금은 일반 국민이 가입하는 국민연금과 공무원연금 군인연금 사학연금 같은 직역연금으로 나뉜다.","c":"상","v":1},"세무사2023_60-36-2":{"w":"국민연금은 기여에 비례해 급여를 주는 적립방식이지만 완전적립이 아니고 가입자 평균소득 부분이 급여에 반영되어 세대 내 재분배와 세대 간 재분배가 함께 생긴다.","c":"상","v":1},"세무사2023_60-36-4":{"w":"국민연금법상 급여 종류는 노령연금 장애연금 유족연금 반환일시금이다(국민연금법 제49조).","c":"상","v":1},"세무사2023_60-36-5":{"w":"국민연금 연금보험료는 가입자의 기준소득월액에 보험료율을 곱해 산정한다(국민연금법).","c":"중","v":1},"세무사2024_61-31-1":{"w":"앳킨슨 지수는 B > C > A이므로 B가 A보다 높다.","c":"상","v":1},"세무사2024_61-31-2":{"w":"앳킨슨 지수는 B > C > A이므로 C가 A보다 높다.","c":"상","v":1},"세무사2024_61-31-3":{"w":"앳킨슨 지수는 B > C > A이므로 B가 C보다 높다.","c":"상","v":1},"세무사2024_61-31-5":{"w":"앳킨슨 지수가 가장 큰 B가 가장 불균등하게 분배되는 사회다.","c":"상","v":1},"세무사2024_61-32-1":{"w":"평등주의는 결과를 같게 하려고 개인이 정당하게 얻은 몫을 옮기므로 개인의 권리를 침해할 수 있다는 비판을 받는다.","c":"상","v":1},"세무사2024_61-32-2":{"w":"공리주의는 총효용만 보므로 총효용이 더 커지는 불균등한 분배도 정당화할 수 있다.","c":"상","v":1},"세무사2024_61-32-3":{"w":"롤즈는 평등한 자유의 원칙을 최소극대화원칙(차등의 원칙)보다 앞에 두었다.","c":"상","v":1},"세무사2024_61-32-4":{"w":"러너의 동등확률 가정에서는 누가 어떤 효용함수를 가졌는지 알 수 없어 기대효용을 극대화하는 분배가 균등분배가 된다.","c":"하","v":1},"세무사2024_61-33-1":{"w":"앳킨슨 지수는 1 - (균등분배대등소득 / 평균소득)이므로 1에 가까울수록 불평등하다.","c":"상","v":1},"세무사2024_61-33-2":{"w":"앳킨슨 지수는 사회가 불평등을 얼마나 싫어하는지를 사회후생함수에 명시적으로 넣어 계산한다.","c":"상","v":1},"세무사2024_61-33-4":{"w":"소득이 완전히 균등하면 균등분배대등소득이 평균소득과 같아 앳킨슨 지수는 0이다.","c":"상","v":1},"세무사2024_61-33-5":{"w":"앳킨슨 지수는 사회후생함수의 모양(불평등 회피도)에 따라 같은 분배에서도 값이 달라진다.","c":"상","v":1},"세무사2024_61-35-3":{"w":"근로장려세제는 일한 만큼 장려금이 늘어나는 구간이 있어서 일하지 않아도 받는 공공부조보다 근로의욕을 높인다.","c":"상","v":1},"세무사2024_61-37-1":{"w":"공적 보험은 강제가입이라 위험이 낮은 사람이 빠져나가 보험료가 오르는 역선택을 막는다.","c":"상","v":1},"세무사2024_61-37-3":{"w":"자산대체효과는 저축을 줄이고 은퇴효과는 저축을 늘리므로 자산대체효과가 더 작으면 개인 저축이 증가한다.","c":"상","v":1},"세무사2024_61-37-4":{"w":"국민연금 급여 기대는 소득을 늘리는 소득효과를 내어 여가를 늘리고 노동공급을 줄인다.","c":"중","v":1},"세무사2024_61-37-5":{"w":"세대 내 재분배는 급여 산식이 정하고 재원조달방식은 세대 간 재분배에 영향을 주므로 세대 내 재분배는 재원조달방식과 무관하다.","c":"상","v":1},"세무사2024_61-38-2":{"w":"공동보험은 의료비의 일정 비율을 본인이 내게 하여 의료서비스를 과다하게 쓰는 도덕적 해이를 부분적으로 줄인다.","c":"상","v":1},"세무사2024_61-38-3":{"w":"건강보험은 강제가입이어서 건강한 사람이 빠져나가는 역선택이 생기지 않는다.","c":"상","v":1},"세무사2024_61-38-4":{"w":"건강보험은 보험료를 재원으로 하는 점에서 넓은 의미의 사회보험방식이다.","c":"상","v":1},"세무사2024_61-38-5":{"w":"의료비에 세액공제를 주면 의료비 지출로 담세능력이 줄어든 사람의 세부담을 낮춰 주므로 공평성(능력원칙)과 관련된다.","c":"중","v":1},"세무사2025_62-33-1":{"w":"이전지출은 기초연금처럼 정부가 반대급부 없이 소득을 이전하는 지출이다.","c":"상","v":1},"세무사2025_62-33-2":{"w":"이전지출은 보조의 형태에 따라 소득(현금)보조 가격보조 현물보조로 나눈다.","c":"상","v":1},"세무사2025_62-33-3":{"w":"소득보조는 상대가격을 바꾸지 않고 소득만 늘리므로 소득효과만 일으키고 대체효과는 없다.","c":"상","v":1},"세무사2025_62-33-4":{"w":"가격보조는 보조 대상 재화의 상대가격을 낮추므로 대체효과와 소득효과를 모두 일으킨다.","c":"상","v":1},"세무사2025_62-35-1":{"w":"국민기초생활보장제도는 세금으로 최저생활을 보장하는 우리나라의 대표적 공공부조제도다.","c":"상","v":1},"세무사2025_62-37-1":{"w":"5분위배율은 상위 20% 소득을 하위 20% 소득으로 나눈 값이므로 모두 소득이 같으면 1이다.","c":"상","v":1},"세무사2025_62-37-3":{"w":"지니계수는 0(완전 평등)에서 1(완전 불평등) 사이의 값을 가진다.","c":"상","v":1},"세무사2025_62-37-4":{"w":"앳킨슨 지수는 0(완전 평등)에서 1 사이의 값이며 0에 가까울수록 평등하다.","c":"상","v":1},"세무사2025_62-37-5":{"w":"두 로렌츠 곡선이 교차하면 어느 쪽이 더 평등한지 곡선만으로는 정할 수 없다.","c":"상","v":1},"세무사2025_62-38-1":{"w":"롤즈는 가장 가난한 사람의 후생을 극대화하는 분배를 사회후생 극대화로 보는 최소극대화 원칙을 주장했다.","c":"상","v":1},"세무사2025_62-38-3":{"w":"에지워스는 효용함수가 같고 한계효용이 체감하며 총소득이 고정되었다는 가정 아래 균등분배가 총효용을 극대화한다고 보았다.","c":"상","v":1},"세무사2025_62-38-4":{"w":"공리주의는 총효용이 극대화되기만 하면 분배의 불균등을 문제 삼지 않으므로 불균등한 분배도 정당화된다.","c":"상","v":1},"세무사2025_62-38-5":{"w":"노직은 정당한 절차로 얻은 소유라면 결과가 불평등해도 정당하다고 보아 결과보다 절차의 정의를 중시했다.","c":"상","v":1},"세무사2025_62-39-1":{"w":"공리주의 사회후생함수는 구성원의 효용을 비교하고 합산하므로 개인 간 효용 비교를 전제로 한다.","c":"상","v":1},"세무사2025_62-39-2":{"w":"공리주의는 총효용이 늘면 일부 개인의 권리를 희생시키는 것도 허용할 수 있어 개인의 권리가 침해될 수 있다.","c":"상","v":1},"세무사2025_62-39-4":{"w":"공리주의에서는 사회 전체 후생을 늘리는 공리의 원칙이 유일한 도덕 기준이다.","c":"상","v":1},"세무사2025_62-39-5":{"w":"공리주의는 사회 구성원의 총체적 후생을 극대화하는 분배를 바람직한 분배로 본다.","c":"상","v":1},"세무사2026_63-31-1":{"w":"공리주의 사회후생함수에서는 균등분배대등소득이 평균소득과 같아 두 사회 모두 앳킨슨 지수가 0이다.","c":"상","v":1},"세무사2026_63-31-2":{"w":"롤스 함수에서는 균등분배대등소득이 최저소득 100인데 평균소득이 A 250 B 200이므로 앳킨슨 지수가 A 0.6 B 0.5로 A가 크다.","c":"상","v":1},"세무사2026_63-31-3":{"w":"롤스 함수에서 균등분배대등소득은 최저소득이며 두 사회 모두 100으로 같다.","c":"상","v":1},"세무사2026_63-31-5":{"w":"B의 하위 50% 소득점유율이 25%로 A의 20%보다 커서 B의 로렌츠 곡선이 대각선에 더 가까우므로 지니계수는 B가 더 작다.","c":"상","v":1},"세무사2026_63-32-1":{"w":"노직은 정당한 취득과 이전의 절차가 지켜졌다면 결과의 분배가 어떻든 정의롭다고 보았다.","c":"상","v":1},"세무사2026_63-32-2":{"w":"공리주의는 총효용만 극대화하면 되므로 매우 불균등한 분배도 정당화할 수 있다.","c":"상","v":1},"세무사2026_63-32-3":{"w":"롤즈의 최소극대화 원칙은 사회에서 가장 불리한 처지에 있는 사람의 후생을 극대화하라는 것이다.","c":"상","v":1},"세무사2026_63-32-5":{"w":"에지워스의 최적분배이론은 개인 효용의 합인 공리주의 사회후생을 극대화하는 분배를 찾는 이론이다.","c":"상","v":1},"세무사2026_63-33-5":{"w":"앳킨슨 지수는 사회후생함수라는 가치판단을 명시하고 로렌츠 곡선은 곡선의 위치로 순서만 매기는 서수적 평가다.","c":"상","v":1},"세무사2026_63-34-2":{"w":"근로장려금은 단독 홑벌이 맞벌이 가구 유형에 따라 지급액과 소득 상한을 달리 정한다.","c":"상","v":1},"세무사2026_63-34-3":{"w":"점감구간에서는 소득이 늘수록 장려금이 줄어 소득 1원 증가에 따른 가처분소득 증가분이 1원보다 작다.","c":"상","v":1},"세무사2026_63-34-4":{"w":"근로장려세제는 일해야 받는 급여여서 일하지 않아도 받는 부(-)의 소득세보다 근로의욕을 높이는 효과가 크다.","c":"상","v":1},"세무사2026_63-34-5":{"w":"암묵적 한계세율이 0이면 일을 더 해도 순임금이 변하지 않아 상대가격 변화가 없으므로 대체효과가 없다.","c":"상","v":1},"세무사2026_63-35-1":{"w":"부(-)의 소득세 보조금은 S = m - tE이므로 재원이 고정된 채 기초수당 m을 올리면 보조받는 소득 범위 m/t가 넓어지는 만큼 t를 올려 재원을 맞춰야 한다.","c":"상","v":1},"세무사2026_63-35-2":{"w":"다른 조건이 같을 때 기초수당이 크면 모든 소득 수준의 보조금이 커져 재분배 효과가 커진다.","c":"상","v":1},"세무사2026_63-35-4":{"w":"부(-)의 소득세에서는 면세점 이하 소득자도 소득이 늘면 보조금이 줄어 대체효과와 소득효과로 근로의욕이 낮아진다.","c":"상","v":1},"세무사2026_63-35-5":{"w":"부(-)의 소득세는 모든 가구에 같은 산식을 적용하므로 행정이 단순하고 자격 심사가 따로 필요 없다.","c":"상","v":1},"세무사2026_63-36-2":{"w":"근로장려세제는 일하는데도 소득이 낮아 빈곤에서 벗어나지 못하는 근로빈곤층을 지원하는 제도다.","c":"상","v":1},"세무사2026_63-36-3":{"w":"사회보험은 가입자가 낸 보험료로 급여를 지급하는 보험원리를 따르므로 조세로 재원을 마련하는 공공부조보다 재분배효과가 제한적이다.","c":"중","v":1},"세무사2026_63-36-4":{"w":"공공부조는 보험료가 아니라 국민이 낸 세금을 재원으로 저소득층을 지원한다.","c":"상","v":1},"세무사2026_63-36-5":{"w":"공공부조는 보험료 기여 없이 소득과 재산 요건만 충족하면 받는 급여다.","c":"상","v":1},"세무사2026_63-37-4":{"w":"부과방식에서 연금 기대로 일찍 은퇴하면 은퇴 후 기간이 길어져 필요한 노후 자금이 늘어 민간저축이 증가한다.","c":"중","v":1},"세무사2016_53-18-1":{"w":"모든 생산요소시장이 완전경쟁이면 요소가격이 같아져 생산자 간 한계기술대체율이 같아지므로 생산요소 배분이 효율적이다.","c":"상","v":1},"세무사2016_53-18-2":{"w":"모든 상품시장이 완전경쟁이면 소비자들이 같은 가격에 직면해 한계대체율이 같아지므로 소비자 간 재화 배분이 효율적이다.","c":"상","v":1},"세무사2016_53-18-3":{"w":"후생경제학 제1정리는 완전경쟁시장에서 선호가 강단조적이고 외부성이 없으면 경쟁균형이 파레토 효율적이라는 내용이다.","c":"상","v":1},"세무사2016_53-18-5":{"w":"재화의 최적 구성은 소비의 한계대체율과 생산의 한계변환율이 같을 때 이루어진다(MRS = MRT).","c":"상","v":1},"세무사2017_54-23-2":{"w":"사회후생함수는 개인의 효용을 측정하고 비교할 수 있다고 가정하고 사회의 가치판단에 따라 모양이 정해진다.","c":"상","v":1},"세무사2017_54-23-3":{"w":"공리주의 사회후생함수 W = U_A + U_B에서 소득 이전으로 더 늘릴 수 없는 극대점은 각자의 소득의 한계효용이 같을 때다.","c":"상","v":1},"세무사2017_54-23-4":{"w":"사회후생을 극대화하는 배분이 파레토 효율적이지 않으면 모두를 낫게 할 수 있어 후생이 더 커지므로 극대점은 파레토 효율적이다.","c":"상","v":1},"세무사2017_54-23-5":{"w":"효용가능경계 위에서는 한 사람의 효용을 늘리려면 다른 사람의 효용을 줄여야 하므로 효율과 공평을 함께 높일 수 없다.","c":"상","v":1},"세무사2021_58-24-1":{"w":"사회후생함수의 모양은 사회가 선택하는 가치판단에 따라 정해진다.","c":"상","v":1},"세무사2021_58-24-2":{"w":"사회후생함수는 개인 효용을 측정할 수 있다는 가정 위에 개인 효용을 모아 사회후생으로 만든다.","c":"상","v":1},"세무사2021_58-24-4":{"w":"공리주의 사회후생함수는 효용의 합이므로 극대점에서 각 개인 소득의 한계효용이 같아야 한다.","c":"상","v":1},"세무사2021_58-24-5":{"w":"사회후생을 극대화하는 배분이 파레토 효율적이지 않으면 모두를 낫게 하는 개선이 남아 있으므로 극대점은 파레토 효율적이다.","c":"상","v":1},"세무사2021_58-26-1":{"w":"불완전경쟁에서는 가격이 한계비용을 넘어 자원배분이 효율적이지 못하므로 시장실패가 일어날 수 있다.","c":"상","v":1},"세무사2021_58-26-2":{"w":"공공재는 비배제성과 비경합성 때문에 시장에 맡기면 무임승차로 과소공급되어 시장실패가 생긴다.","c":"상","v":1},"세무사2021_58-26-3":{"w":"시장실패는 정부개입이 필요하게 되는 필요조건이지만 정부실패가 있을 수 있어 충분조건은 아니다.","c":"상","v":1},"세무사2021_58-26-4":{"w":"위험을 나누는 모든 조건부 시장이 있어야 하는데 보험시장은 역선택과 도덕적 해이로 완비되기 어려워 시장실패가 생길 수 있다.","c":"상","v":1},"세무사2022_59-21-1":{"w":"후생경제학 제1정리는 외부성이 없는 완전경쟁시장의 균형이 파레토 효율적이라는 내용으로 애덤 스미스의 보이지 않는 손에 해당한다.","c":"상","v":1},"세무사2022_59-21-2":{"w":"정보의 비대칭이 있으면 역선택과 도덕적 해이로 거래가 왜곡되어 자원배분이 비효율적이 된다.","c":"상","v":1},"세무사2022_59-21-4":{"w":"영기준 예산제도는 전년도 예산을 기준으로 증감하는 점증주의를 버리고 모든 사업을 처음부터 다시 평가해 예산을 배분하는 제도다.","c":"중","v":1},"세무사2022_59-21-5":{"w":"공공요금을 부과하면 이용자가 비용을 가격으로 인식해 수요를 조절하므로 가격기능으로 자원배분의 효율성을 높일 수 있다.","c":"중","v":1},"세무사2022_59-22-1":{"w":"효용가능경계 위에서는 한 사람의 효용을 늘리려면 다른 사람의 효용을 줄여야 하므로 효율과 공평을 동시에 개선할 수 없다.","c":"상","v":1},"세무사2022_59-22-2":{"w":"평등주의 성향이 극단으로 가면 가장 효용이 낮은 사람만 중시하는 롤즈의 W = min(U_A, U_B)가 되어 사회무차별곡선이 L자 모양이다.","c":"상","v":1},"세무사2022_59-22-3":{"w":"롤즈의 사회후생함수는 가장 불리한 사람의 효용만 보는 W = min(U_A, U_B)다.","c":"상","v":1},"세무사2022_59-22-4":{"w":"W = U_A + 2U_B에서는 B의 효용 1단위가 사회후생에 A의 2배만큼 기여하므로 B에게 2배의 가중치가 주어진다.","c":"상","v":1},"세무사2022_59-23-2":{"w":"중립세는 상대가격을 바꾸지 않아 대체효과가 없으므로 민간의 의사결정을 왜곡하지 않는다.","c":"상","v":1},"세무사2022_59-23-3":{"w":"시장실패가 있어야 정부가 개입할 이유가 생기므로 필요조건이지만 정부실패의 가능성 때문에 충분조건은 아니다.","c":"상","v":1},"세무사2022_59-23-4":{"w":"정부가 정책에 대한 민간의 반응을 정확히 알거나 통제하지 못하면 의도한 결과가 나오지 않아 정부실패가 발생한다.","c":"상","v":1},"세무사2022_59-23-5":{"w":"자연독점기업에 가격을 한계비용과 같게 정하면 생산이 효율적 수준에 이르러 독점의 비효율이 사라진다. 다만 손실은 따로 보전해야 한다.","c":"상","v":1},"세무사2022_59-36-2":{"w":"사회후생함수가 정해지면 변화 전후의 사회후생을 비교해 개선인지 판정할 수 있다.","c":"중","v":1},"세무사2022_59-36-3":{"w":"사회후생함수의 사회무차별곡선이 효용가능경계와 접하는 점이 사회후생이 가장 큰 자원배분이다.","c":"상","v":1},"세무사2022_59-36-4":{"w":"사회후생함수는 효용을 어떻게 비중 두어 합칠지에 대한 사회의 가치판단에 따라 공리주의 롤즈 평등주의 등 여러 형태로 정해진다.","c":"상","v":1},"세무사2022_59-36-5":{"w":"애로의 불가능성 정리는 서수적 선호만 쓸 때의 결과이고 센은 개인 간 비교 정보를 허용하거나 선택 범위를 제한하면 합리적이고 민주적인 사회적 선호의 도출이 가능하다고 보았다.","c":"중","v":1},"세무사2024_61-20-1":{"w":"중상주의(관방학) 시대의 재정 논의는 국가 수입을 어떻게 확보하느냐, 곧 과세의 정당성과 조세수입의 원천에 집중했다.","c":"중","v":1},"세무사2024_61-20-2":{"w":"애덤 스미스는 시장 가격기구가 자원을 효율적으로 배분하므로 정부는 국방 치안 사법 등 최소 기능만 맡아야 한다고 보았다(야경국가).","c":"상","v":1},"세무사2024_61-20-3":{"w":"바그너는 조세에 재정수입 확보뿐 아니라 누진세율로 분배의 불평등을 바로잡는 사회정책적 기능이 있다고 보았다.","c":"상","v":1},"세무사2024_61-20-4":{"w":"집단의사결정을 다룬 공공선택이론과 공공재 최적공급 이론의 토대는 빅셀의 자발적 교환이론과 린달 모형 등에서 놓였고 파레토의 효율 개념이 기준이 되었다.","c":"중","v":1},"세무사2024_61-25-2":{"w":"지원자가 졸업장을 제출하게 하는 것은 숨은 능력을 알리는 신호 장치로 역선택을 줄이는 방법이다.","c":"상","v":1},"세무사2024_61-25-3":{"w":"모든 차량에 책임보험을 강제하면 위험이 낮은 운전자도 가입하게 되어 역선택이 줄어든다.","c":"상","v":1},"세무사2024_61-25-4":{"w":"지원자가 자격증을 제출하는 것은 자신의 능력을 알리는 신호발송이다.","c":"상","v":1},"세무사2024_61-25-5":{"w":"판매자가 품질보증을 제공하면 구매자가 품질을 믿을 수 있어 중고차 시장의 역선택이 줄어든다.","c":"상","v":1},"세무사2025_62-22-1":{"w":"파레토 효율 상태는 누구의 효용도 줄이지 않고 다른 사람의 효용을 높일 수 있는 이동이 없는 상태다.","c":"상","v":1},"세무사2025_62-22-2":{"w":"후생경제학 제1정리는 외부성이 없고 시장이 완비된 일반경쟁균형이 파레토 효율적이라는 내용이다.","c":"상","v":1},"세무사2025_62-22-3":{"w":"애로는 위험과 불확실성에 대한 모든 조건부 상품시장이 갖춰지면 시장실패 없이 효율적 배분이 가능하다고 보였다.","c":"하","v":1},"세무사2025_62-22-5":{"w":"도덕적 해이는 거래 뒤 한쪽의 행동을 다른 쪽이 관찰할 수 없어 생기는 정보 비대칭의 결과이며 시장실패를 낳는다.","c":"상","v":1},"세무사2025_62-23-1":{"w":"시장실패는 정부개입의 필요조건이다.","c":"상","v":1},"세무사2025_62-23-2":{"w":"중립세는 상대가격을 바꾸지 않으므로 민간의 의사결정을 교란하지 않는다.","c":"상","v":1},"세무사2025_62-23-4":{"w":"정비이력을 의무로 공개하게 하면 구매자가 차량 품질을 알 수 있어 정보비대칭에서 오는 시장실패가 줄어든다.","c":"상","v":1},"세무사2025_62-23-5":{"w":"국민연금을 강제로 가입시키면 오래 살 위험이 높은 사람만 가입하는 역선택이 생기지 않아 사적 연금시장의 역선택 문제를 해결한다.","c":"중","v":1},"세무사2025_62-26-1":{"w":"평등주의적 사회후생함수는 효용이 낮은 사람에게 큰 가중치를 주고 효용이 높은 사람에게 작은 가중치를 준다.","c":"상","v":1},"세무사2025_62-26-2":{"w":"공리주의 W = U_A + U_B는 모든 구성원의 효용에 같은 가중치를 준다.","c":"상","v":1},"세무사2025_62-26-3":{"w":"롤즈의 사회후생함수는 최소 효용만 보는 W = min(U_A, U_B)다.","c":"상","v":1},"세무사2025_62-26-4":{"w":"W = U_A + 2U_B에서는 B의 효용에 A의 2배 가중치가 있어 B를 2배 중요시한다.","c":"상","v":1},"세무사2026_63-20-1":{"w":"유기체적 국가관은 사회를 하나의 자연적 유기체로 본다.","c":"상","v":1},"세무사2026_63-20-3":{"w":"유기체적 국가관에서 개인은 유기체의 한 부분이고 정부는 심장부에 해당한다.","c":"상","v":1},"세무사2026_63-20-4":{"w":"유기체적 국가관에서 개인은 전체의 일부로서만 의미를 가지며 전체의 이익에 봉사하는 것이 미덕이다.","c":"상","v":1},"세무사2026_63-20-5":{"w":"유기체적 국가관은 개인보다 전체를 앞세우는 전체주의적 사고를 바탕으로 한다.","c":"상","v":1},"세무사2026_63-21-2":{"w":"후생경제학 제1정리에 따라 경쟁균형은 파레토 효율적이고 제2정리에 따라 선호와 생산이 볼록하면 초기부존을 재분배해 어떤 파레토 효율 배분도 경쟁균형으로 달성할 수 있다.","c":"상","v":1},"세무사2026_63-24-1":{"w":"자연독점 구간에서는 평균비용이 계속 감소하고 평균비용이 줄어들려면 한계비용이 평균비용보다 작아야 한다.","c":"상","v":1},"세무사2016_53-26-1":{"w":"완전경쟁시장에서는 과세 후 균형의 수요가격과 공급가격의 차(조세 쐐기)가 같으면 종가세와 종량세의 귀착이 같다.","c":"상","v":1},"세무사2016_53-26-2":{"w":"조세수입은 쐐기와 거래량의 곱이므로 균형에서 쐐기와 거래량이 같으면 종가세와 종량세의 조세수입이 같다.","c":"상","v":1},"세무사2016_53-26-3":{"w":"생산량이 같을 때 종가세는 소비자가격에 비례해 세액이 정해지는데 종가세의 세액이 더 크므로 조세수입이 종량세보다 많다.","c":"상","v":1},"세무사2016_53-26-5":{"w":"생산량이 같으면 소비자잉여와 생산자잉여 감소분이 같으므로 사중손실도 종가세와 종량세에서 같다.","c":"상","v":1},"세무사2016_53-29-3":{"w":"토지는 공급이 고정되어 있어 과세가 토지 거래량을 바꾸지 않으므로 토지 소유자가 세금을 모두 부담한다(미래 세금의 현재가치만큼 지가 하락).","c":"상","v":1},"세무사2016_53-33-1":{"w":"편익원칙은 공공서비스에서 얻는 이익에 비례해 세금을 내므로 근로소득에 따른 한계세율이 오르지 않아 근로의욕을 해치지 않는다.","c":"상","v":1},"세무사2016_53-33-2":{"w":"외부성 때문에 편익이 불특정 다수에게 퍼지는 공공재는 편익을 받는 사람을 가려내 비용을 물리기 어려워 편익원칙으로 재원을 조달하기 어렵다.","c":"중","v":1},"세무사2016_53-33-4":{"w":"편익원칙은 개인이 얻는 편익만큼 내는 자발적 교환의 논리로 빅셀의 자발적 교환이론에 근거한다.","c":"상","v":1},"세무사2016_53-33-5":{"w":"편익원칙은 편익에 비례해 비용을 부담하므로 소득이 낮아 편익을 적게 받는 사람에게서 재분배 재원을 거둘 수 없다.","c":"상","v":1},"세무사2016_53-36-3":{"w":"이윤세는 이윤의 일정 비율을 거두므로 이윤을 극대화하는 생산량과 가격이 그대로여서 기업의 행동을 바꾸지 못한다.","c":"상","v":1},"세무사2017_54-01-1":{"w":"공급이 고정된 자산에 과세하면 장래 세금의 현재가치만큼 자산가격이 내려가는 조세의 자본화가 일어난다.","c":"상","v":1},"세무사2017_54-02-1":{"w":"목적세는 용도가 정해진 조세로 교육세 교통·에너지·환경세 농어촌특별세 등이 예다.","c":"상","v":1},"세무사2017_54-02-2":{"w":"목적세는 용도가 정해져 있어 세수가 부족하면 다른 재원인 보통세를 전용해야 하는 문제가 있다.","c":"상","v":1},"세무사2017_54-02-4":{"w":"세수의 용도를 미리 정해 두면 예산 배분 과정에서 부처 간 경쟁과 정치적 갈등이 줄어든다.","c":"상","v":1},"세무사2017_54-02-5":{"w":"목적세는 쓰임새가 정해져 있어 재정의 탄력적 운용이 어려우므로 신축성을 떨어뜨린다.","c":"상","v":1},"세무사2017_54-06-1":{"w":"균형예산귀착은 한 조세의 세수로 조달한 정부지출의 분배효과까지 함께 분석한다.","c":"상","v":1},"세무사2017_54-06-2":{"w":"차별귀착은 정부지출과 다른 조세를 일정하게 두고 한 조세를 같은 세수의 다른 조세로 바꿀 때의 분배 효과를 비교한다.","c":"상","v":1},"세무사2017_54-06-3":{"w":"절대귀착은 다른 조세와 정부지출이 변하지 않는다고 놓고 한 조세의 분배효과를 분석한다.","c":"상","v":1},"세무사2017_54-06-5":{"w":"조세가 여러 개이면 각 세금과 각 지출의 효과를 동시에 따져야 해서 균형예산귀착 분석이 어렵다.","c":"상","v":1},"세무사2017_54-08-2":{"w":"물품세 부담은 상대적으로 탄력성이 낮은 쪽이 더 지는데 소비자 부담 비율은 공급탄력성 / (공급탄력성 + 수요탄력성)이므로 공급탄력성이 수요탄력성보다 클수록 소비자 귀착이 커진다.","c":"상","v":1},"세무사2017_54-08-3":{"w":"노동수요가 완전탄력적이면 세금으로 임금을 올릴 수 없어 근로소득세 부담은 모두 노동자에게 귀착된다.","c":"상","v":1},"세무사2017_54-08-4":{"w":"완전개방경제에서는 자본이 세계 시장 수익률을 찾아 이동하므로 세금을 전가할 수 없는 자본 사용자(노동 토지)가 부담한다.","c":"상","v":1},"세무사2017_54-08-5":{"w":"부분균형분석은 한 시장의 조세 효과만 따지고 다른 시장으로의 파급은 없다고 가정한다.","c":"상","v":1},"세무사2021_58-04-1":{"w":"동등비례희생 원칙에서 소득의 한계효용이 직선으로 감소하는 경우(한계효용의 소득탄력성이 1보다 큰 구간)에는 누진세가 정당화된다.","c":"중","v":1},"세무사2021_58-06-1":{"w":"독점기업은 세금의 일부만 가격에 반영하고 나머지는 이윤 감소로 부담하므로 조세가 소비자에게 모두 전가되지는 않는다.","c":"상","v":1},"세무사2021_58-06-2":{"w":"법인세 부담이 상품가격 인상으로 이어지면 소비자에게 전가된다.","c":"상","v":1},"세무사2021_58-06-3":{"w":"국민연금 기여금은 법으로 사용자와 근로자가 절반씩 내지만 임금이 조정되는 정도에 따라 노동수요와 노동공급의 탄력성이 실제 부담을 정한다(국민연금법).","c":"상","v":1},"세무사2021_58-06-5":{"w":"독점에서는 종가세와 종량세가 한계수입과 한계비용에 주는 영향이 달라 가격과 생산량 효과가 서로 다르다.","c":"상","v":1},"세무사2021_58-08-1":{"w":"세금을 붙여 소비자 가격이 160에서 180으로 오르는 것이 소비자 귀착 20에 해당한다.","c":"상","v":1},"세무사2021_58-08-3":{"w":"거래량이 60에서 40으로 줄어드는 것이 조세 부과 후 균형이다.","c":"상","v":1},"세무사2021_58-08-4":{"w":"단위당 세액 60에 거래량 40을 곱하면 조세수입은 2,400이다.","c":"상","v":1},"세무사2021_58-08-5":{"w":"소비자 가격이 20 오르고 거래량이 40이므로 소비자 부담은 20 x 40 = 800이다.","c":"상","v":1},"세무사2021_58-15-5":{"w":"조세의 자본화는 공급이 고정된 토지에 과세하면 미래 세금의 현재가치만큼 지가가 하락하는 현상이다.","c":"상","v":1},"세무사2022_59-09-2":{"w":"능력원칙은 지불능력이 큰 사람이 더 많이 내야 한다는 원칙이다.","c":"상","v":1},"세무사2022_59-09-3":{"w":"부양가족이 많으면 담세능력이 줄므로 공제를 통해 세금을 적게 내게 하는 것이 능력원칙이다.","c":"상","v":1},"세무사2022_59-09-4":{"w":"주행거리가 길수록 도로 이용 편익이 크므로 주행거리에 비례하는 자동차세는 편익원칙에 따른 것이다.","c":"상","v":1},"세무사2022_59-09-5":{"w":"공원 때문에 오른 집값은 공원에서 얻는 편익이 자산가치에 반영된 것이므로 재산세를 더 내는 것은 편익원칙에 따른 것이다.","c":"상","v":1},"세무사2022_59-10-2":{"w":"알링햄-샌드모 모형에서 절대위험기피도가 체감하면 세율이 오를 때 소득이 줄어든 소득효과로 위험을 더 피해 탈루소득이 줄어든다.","c":"상","v":1},"세무사2022_59-15-1":{"w":"조세 부과 후 시장가격이 120에서 150으로 오르는 것이 소비자 부담이 30 늘었음을 뜻한다.","c":"상","v":1},"세무사2022_59-15-2":{"w":"계산 결과 세수 3000과 거래량 50에서 단위당 세액이 60이므로 초과부담은 1/2 x 60 x 30 = 900이어서 문장의 450과 맞지 않는다. 문항 원자료를 확인해야 한다.","c":"하","v":1,"old":1,"ow":"O·X 표시 오류로 출제에서 뺌: 공식 정답(3번)은 맞지만 2번 「초과부담 450」은 계산과 다르다. 독점 P=200−Q, MC=40에 종량세 60이면 거래량 80→50, 총잉여 감소에서 조세수입을 뺀 초과부담은 2,850이다. 맞는 문장으로 내면 안 되어 출제에서 뺀다."},"세무사2022_59-15-4":{"w":"거래량 50에 단위당 세액 60을 곱하면 조세수입이 3,000이다.","c":"상","v":1},"세무사2022_59-15-5":{"w":"조세 부과 후 균형 거래량이 80에서 50으로 줄어든다.","c":"상","v":1},"세무사2023_60-04-1":{"w":"독점기업은 세금만큼 가격을 올리면 수요가 줄어 이윤이 감소하므로 가격을 일부만 올려 독점기업과 소비자가 나누어 부담한다.","c":"상","v":1},"세무사2024_61-02-1":{"w":"누진세에서는 평균소득이 같아도 소득 변동이 큰 개인사업자가 소득이 고른 근로소득자보다 더 많이 내게 되어 수평적 공평성이 깨질 수 있다.","c":"상","v":1},"세무사2024_61-04-2":{"w":"공급이 탄력적일수록 세금 부과로 거래량이 더 크게 줄어 후생손실이 커진다.","c":"상","v":1},"세무사2024_61-10-1":{"w":"알링햄-샌드모 모형은 납세자가 탈세로 얻는 이득과 적발 시 벌금을 비교해 기대효용을 극대화한다고 보고 탈세를 분석한다.","c":"상","v":1},"세무사2024_61-10-2":{"w":"알링햄-샌드모 모형은 납세자의 절대위험기피도가 소득이 늘수록 줄어드는 체감 특성을 가진다고 가정한다.","c":"상","v":1},"세무사2024_61-10-4":{"w":"알링햄-샌드모 모형은 세율 인상의 효과가 소득효과와 대체효과로 갈려 불분명하므로 세율은 적정하게 두고 감사확률이나 벌금률로 탈세를 막는 것이 낫다고 본다.","c":"상","v":1},"세무사2024_61-10-5":{"w":"감사확률을 높이려면 조사 인력과 비용이 들지만 벌금률은 법으로 올릴 수 있어 행정비용이 덜 든다는 점에서 벌금률 인상이 더 바람직하다고 본다.","c":"상","v":1},"세무사2025_62-02-1":{"w":"능력원칙에서는 자산가치가 오르면 담세능력이 커진 것이므로 재산세를 더 부담해야 한다.","c":"상","v":1},"세무사2025_62-03-1":{"w":"목적세는 세수의 용도가 정해져 있어 특정 분야 사업의 재원을 안정적으로 확보하게 한다.","c":"상","v":1},"세무사2025_62-03-2":{"w":"지방교육세는 지방세이면서 용도가 정해진 목적세다.","c":"상","v":1},"세무사2025_62-03-3":{"w":"농어촌특별세는 국세이면서 농어촌 지원에 쓰도록 용도가 정해진 목적세다.","c":"상","v":1},"세무사2025_62-03-4":{"w":"법인세는 납세의무자와 담세자가 같은 직접세이고 부가가치세는 납세의무자와 담세자가 다른 간접세다.","c":"상","v":1},"세무사2025_62-08-1":{"w":"절대위험기피도가 체감하면 세율 상승으로 순소득이 줄어들 때 위험을 더 피해 탈루소득을 줄이는 소득효과가 나타난다.","c":"상","v":1},"세무사2025_62-08-3":{"w":"감사확률이나 벌금률이 높아지면 탈세의 기대 비용이 커져서 탈루소득이 줄어든다.","c":"상","v":1},"세무사2025_62-08-4":{"w":"세율이 오르면 소득효과는 탈루소득을 줄이고 대체효과는 늘려서 서로 반대 방향이므로 총효과의 방향을 알 수 없다.","c":"하","v":1},"세무사2025_62-08-5":{"w":"알링햄-샌드모 모형은 납세자의 절대위험기피도 체감을 가정한다.","c":"상","v":1},"세무사2026_63-05-3":{"w":"독점기업은 세금을 모두 가격에 얹으면 판매량이 줄어 이윤이 줄기 때문에 일부만 소비자에게 전가하고 나머지를 스스로 부담한다.","c":"상","v":1},"세무사2017_54-16-1":{"w":"바그너의 법칙은 소득이 늘 때 공공재에 대한 수요가 소득보다 더 빠르게 늘어 정부지출 비중이 커진다는 것이다(소득탄력성 > 1).","c":"상","v":1},"세무사2017_54-16-3":{"w":"니스카넨 모형은 관료가 예산을 극대화하려 하므로 공공재 공급이 최적 수준보다 늘어나 정부지출이 커진다고 본다.","c":"상","v":1},"세무사2017_54-16-4":{"w":"보몰효과에 따르면 정부 서비스는 노동 집약적이라 기술혁신에 따른 생산성 향상이 사적재보다 느려 상대적 생산비가 올라간다.","c":"상","v":1},"세무사2017_54-16-5":{"w":"복지를 포함한 공공서비스는 소득이 늘 때 수요가 더 빠르게 늘어나는 소득탄력성이 큰 재화이므로 정부지출 비중이 커진다.","c":"상","v":1},"세무사2021_58-32-4":{"w":"배로의 리카도 대등정리는 국채 발행이 미래 세금을 뜻한다고 보고 민간이 저축을 늘려 상쇄하므로 국민저축과 투자에 영향이 없다고 본다.","c":"상","v":1},"세무사2021_58-35-1":{"w":"전통적 견해에서 감세는 가처분소득을 늘려 거래 목적의 화폐수요를 증가시킨다.","c":"상","v":1},"세무사2021_58-35-2":{"w":"감세로 가처분소득이 늘면 소비지출이 늘어 총수요곡선이 오른쪽으로 이동한다.","c":"상","v":1},"세무사2021_58-35-3":{"w":"리카도 대등정리에 따르면 감세를 국채로 메워도 합리적인 가계는 미래 세금을 예상해 감세액만큼 저축하므로 총수요는 변하지 않는다.","c":"상","v":1},"세무사2021_58-35-5":{"w":"한계소비성향이 1보다 작으면 정부지출 감소의 총수요 감소폭이 같은 금액의 감세에 따른 총수요 증가폭보다 커서 재정적자는 그대로이고 총수요는 줄어든다.","c":"상","v":1},"세무사2022_59-13-1":{"w":"조세지출예산제도는 조세감면의 규모를 예산서로 공개해 감면의 남발을 억제하고 재정의 투명성을 높이려는 제도다(국가재정법상 조세지출예산서).","c":"중","v":1},"세무사2022_59-13-2":{"w":"특별감가상각은 세법상 감가상각을 늘려 법인세를 줄여 주는 조세감면이므로 조세지출의 예다.","c":"상","v":1},"세무사2022_59-13-4":{"w":"기부금에 소득공제를 허용하면 세금이 줄어드는 만큼 정부가 보조금을 준 것과 같으므로 조세지출이다.","c":"상","v":1},"세무사2022_59-13-5":{"w":"투자세액공제는 투자액의 일정 비율만큼 세금을 깎아 주는 조세감면이므로 조세지출이다.","c":"상","v":1},"세무사2022_59-38-1":{"w":"브라운-잭슨은 바그너의 법칙을 중위투표자의 공공서비스 수요가 소득에 따라 늘어나는 것과 연결해 설명했다.","c":"상","v":1},"세무사2023_60-15-4":{"w":"배로의 대등정리에 따르면 정부지출이 같을 때 조세 조달과 국채 조달은 현재가치로 같아서 총수요에 영향을 주지 않는다.","c":"상","v":1},"세무사2023_60-38-4":{"w":"피콕-와이즈만은 전쟁 같은 사회적 혼란기에 정부지출이 늘면 평상시에도 그 수준이 유지되는 전위효과가 일어난다고 보았다.","c":"상","v":1},"세무사2024_61-15-1":{"w":"통화주의자는 호황기에 경제가 완전고용에 가까워 정부의 차입이 민간자금을 직접 대체하므로 구축효과가 더 크다고 주장한다.","c":"중","v":1},"세무사2024_61-15-3":{"w":"국채를 시중에서 전액 소화하면 자금 수요가 늘어 이자율이 오르고 민간투자가 줄어드는 구축효과가 생긴다.","c":"상","v":1},"세무사2024_61-15-4":{"w":"중앙은행이 국채를 인수하면 본원통화가 공급되어 통화량이 늘고 물가 상승 압력이 생긴다.","c":"상","v":1},"세무사2024_61-15-5":{"w":"중앙은행 인수는 이자율 상승 없이 통화량이 늘어 구축효과가 없으므로 시중 소화보다 총수요 증대효과가 크다.","c":"상","v":1},"세무사2024_61-21-1":{"w":"재정은 공공재 공급과 외부성 교정 등으로 시장이 못 하는 자원배분의 효율성을 높인다.","c":"상","v":1},"세무사2024_61-21-3":{"w":"실업보험과 누진 소득세는 경기에 따라 지출과 세수가 자동으로 변해 경기변동을 줄이는 자동안정장치다.","c":"상","v":1},"세무사2024_61-21-4":{"w":"공공재 외부성 독점 정보 비대칭이 재정이 개입할 수 있는 시장실패의 유형이다.","c":"상","v":1},"세무사2024_61-21-5":{"w":"재정을 통한 소득재분배는 같은 능력자 간 형평(수평적 공평)과 능력이 다른 사람 간 형평(수직적 공평)을 높일 수 있다.","c":"상","v":1},"세무사2024_61-39-1":{"w":"보몰효과는 정부 서비스가 노동집약적이어서 생산성 상승이 느려 비용이 상대적으로 빠르게 늘고 정부지출이 증가한다는 것이다.","c":"상","v":1},"세무사2024_61-39-2":{"w":"피콕-와이즈만은 혼란기에 사회가 늘어난 세 부담과 지출을 받아들이는 분위기가 생겨 지출이 증가한다고 보았다.","c":"상","v":1},"세무사2024_61-39-3":{"w":"정부지출승수는 1 / (1 - c)이므로 한계소비성향 c가 줄면 승수가 작아져 국민소득 증가폭이 줄어든다.","c":"상","v":1},"세무사2024_61-39-4":{"w":"한계소비성향이 1보다 작아도 0보다 크면 승수 1 / (1 - c)가 1보다 크므로 소득 증가분이 정부지출 증가분보다 크다.","c":"상","v":1},"세무사2025_62-15-1":{"w":"리카도 대등정리가 성립하면 민간이 미래 세금에 대비해 저축을 늘려 국채 수요가 충당되므로 이자율이 오르지 않고 구축효과도 없다.","c":"상","v":1},"세무사2025_62-15-2":{"w":"국채 발행으로 이자율이 오르면 외국 자본이 들어와 원화가 강세가 되어 환율이 하락하고 수출이 줄어 경상수지가 악화된다.","c":"상","v":1},"세무사2025_62-15-3":{"w":"러너의 전통적 견해에서 내부채무는 채권자와 채무자가 같은 국민이라 부담이 전가되지 않지만 외채는 미래세대가 해외로 갚는 부담을 진다.","c":"상","v":1},"세무사2025_62-15-5":{"w":"중복세대모형에서는 국채 발행으로 현재세대의 소비가 늘고 미래세대의 자본축적이 줄어 부담이 미래세대로 전가된다.","c":"상","v":1},"세무사2025_62-20-5":{"w":"한계소비성향이 1보다 작으면 정부지출 감소의 수요 감소폭이 같은 금액의 감세에 따른 수요 증가폭보다 커서 재정적자 변화 없이 총수요가 감소한다.","c":"상","v":1},"세무사2026_63-17-1":{"w":"국채를 시중에서 전액 소화하면 자금 수요가 늘어 이자율이 올라 민간투자가 줄어드는 구축효과가 생길 수 있다.","c":"상","v":1},"세무사2026_63-17-2":{"w":"통화주의자는 이자율에 민감한 화폐수요가 작고 민간투자가 이자율에 민감하다고 보아 케인즈학파보다 구축효과가 크다고 주장한다.","c":"상","v":1},"세무사2026_63-17-4":{"w":"중앙은행이 국채를 인수하면 이자율이 오르지 않고 통화량이 늘어 구축효과 없이 총수요가 늘어나므로 시중 소화보다 증대효과가 크다.","c":"상","v":1},"세무사2026_63-17-5":{"w":"중앙은행이 국채를 인수하면 본원통화가 늘어 통화량이 증가하고 인플레이션이 유발될 수 있다.","c":"상","v":1},"세무사2026_63-38-5":{"w":"조세지출예산제도는 조세감면의 규모를 예산서로 공개해 감면의 남발을 억제하고 재정의 투명성을 높이려는 제도다(국가재정법상 조세지출예산서).","c":"중","v":1},"세무사2026_63-39-1":{"w":"재정착각(푸비아니)은 주민이 공공지출의 조세 부담을 실제보다 작게 느껴 정부지출이 더 커지는 현상이다.","c":"상","v":1},"세무사2026_63-39-2":{"w":"배로의 대등정리는 정부지출이 같으면 재정적자의 조달 방식(조세 또는 국채)이 총수요에 영향을 주지 않는다고 본다.","c":"상","v":1},"세무사2026_63-39-3":{"w":"피콕-와이즈만의 전위효과는 혼란기에 높아진 정부지출 수준이 혼란이 끝나도 원래대로 돌아가지 않고 더 높은 수준에 머무르는 것이다.","c":"상","v":1},"세무사2026_63-39-4":{"w":"브라운-잭슨에 따르면 중위투표자의 공공서비스 수요의 소득탄력성이 크면 소득이 늘 때 공공서비스 수요가 더 빨리 늘어 정부지출 비중이 커진다.","c":"상","v":1},"세무사2017_54-30-4":{"w":"비례소득세로 중위투표자의 소득을 높이는 재분배를 하면 공공재가 정상재라서 중위투표자가 원하는 공급량이 늘어 효율 수준보다 과다 공급될 수 있다.","c":"중","v":1},"세무사2021_58-27-2":{"w":"중위투표자는 모든 투표자를 선호 순서로 늘어놓았을 때 한가운데에 있는 투표자다.","c":"상","v":1},"세무사2021_58-27-3":{"w":"중위투표자 정리의 결과는 중위투표자의 선호를 따르는 것이어서 개인별 한계편익의 합이 한계비용과 같은 효율적 수준과 일치한다는 보장이 없다.","c":"상","v":1},"세무사2021_58-27-4":{"w":"중위투표자 정리는 모든 투표자의 선호가 단봉형일 때 성립하고 다봉형이면 투표의 순환이 생길 수 있다.","c":"상","v":1},"세무사2021_58-27-5":{"w":"양당 경쟁에서 표를 극대화하려는 정치가는 중위투표자의 선호에 맞춰야 과반수 지지를 얻는다.","c":"상","v":1},"세무사2022_59-28-1":{"w":"과반수 투표는 선호가 순환하면 투표의 역설(콩도르세 역설)이 생겨 결정이 일관되지 않는다.","c":"상","v":1},"세무사2022_59-28-2":{"w":"최적다수결제에서 의결에 필요한 표수가 클수록 합의를 이끌어 내는 의사결정비용이 커진다(뷰캐넌과 털럭).","c":"상","v":1},"세무사2022_59-28-3":{"w":"린달 모형은 각자가 비용 분담 비율을 제시해 만장일치로 공급량을 정하는 전원합의제로 공공재의 효율적 공급이 가능함을 보였다.","c":"상","v":1},"세무사2022_59-28-4":{"w":"점수투표제는 각 대안에 점수를 매기게 하므로 전략적 행동이 없다면 선호의 강도를 가장 잘 반영한다.","c":"상","v":1},"세무사2022_59-30-1":{"w":"니스카넨 모형에서 관료는 예산을 극대화하려고 하므로 사회적 최적 수준보다 많이 생산한다.","c":"상","v":1},"세무사2022_59-30-3":{"w":"니스카넨은 관료제의 과다 생산을 막는 방안으로 정부는 비용만 부담하고 생산은 민간이 경쟁적으로 맡게 하는 방식을 제안했다.","c":"상","v":1},"세무사2022_59-30-4":{"w":"관료가 총편익과 총비용이 같아지는 수준까지 생산하면 순편익, 곧 사회적 잉여가 0이다.","c":"상","v":1},"세무사2022_59-30-5":{"w":"니스카넨의 관료는 예산 극대화를 추구하므로 총편익이 총비용과 같아지는 수준에서 생산량을 정한다.","c":"상","v":1},"세무사2025_62-27-2":{"w":"콩도르세 승자는 다른 모든 안과 일대일로 겨뤄 이기는 안이며 선호가 단봉형일 때 중위안인 20억이 이긴다.","c":"상","v":1},"세무사2025_62-27-3":{"w":"중위투표자 정리에 따르면 표를 얻으려는 두 정당이 모두 중위투표자의 선호에 접근하므로 공약이 비슷해진다.","c":"상","v":1},"세무사2025_62-27-4":{"w":"중위투표자 정리는 투표자의 선호가 모두 단봉형일 때 성립한다.","c":"상","v":1},"세무사2025_62-27-5":{"w":"다수결에서는 중위투표자를 얻어야 과반수가 되므로 중위투표자의 지지를 얻은 정당이 승리한다.","c":"상","v":1},"세무사2025_62-29-3":{"w":"관료는 예산을 극대화하려 하므로 한계편익과 한계비용이 같아지는 효율적 수준을 넘어 총편익과 총비용이 같아지는 수준까지 생산하려 한다.","c":"상","v":1},"세무사2026_63-28-3":{"w":"a는 b c d를 각각 6 대 4로 이겨 콩도르세 승자이고 보다 점수는 b 24점 a 18점이어서 보다 승자는 b다.","c":"상","v":1}};
